INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207204820', 'KIT 4 Pneus Maxzez Turbomax 225/45 R17 Aro 17 94Y XL', 'KIT 4 Pneus Maxzez Turbomax 225/45 R17 Aro 17 94Y XL Liberte o verdadeiro potencial do seu carro com o pneu Maxzez Turbomax 225/45 R17 Aro 17 94Y XL. Projetado para ótima aderência e dirigibilidade tanto em baixa quanto em alta velocidade, esse pneu oferecem precisão e controle, permitindo que você obtenha o melhor do seu veículo. O índice de velocidade Y indica especificamente uma capacidade de velocidade máxima de até 300 Km/h, enquanto o índice de carga máximo é indicado por 94 (670 Kg).', 1850.69, 1578.72, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-825zs-mm0cwbkdtybn2e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F540643031%2F58207204820', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693742291', 'Par Manguito Proteção Solar UV Manga Braço Esporte Mangote Vôlei Basquete Ciclismo Bike Esporte', 'Manguito Proteção Solar Esportivo Poker CARACTERÍSTICAS • Proteção UV 50+: Bloqueia raios solares nocivos para máxima segurança ao ar livre. • Material de alta qualidade: Feito com elastano para ajuste perfeito e maior durabilidade. • Tecnologia Insect Defend: Repelência contra mosquitos e insetos sem causar irritação à pele. • Tamanho único: Ajuste confortável para qualquer tipo de corpo. • Dimensões: 24,5 cm de comprimento por 8 cm de largura, cobrindo os antebraços de forma ideal, sem acumular suor. • Composição: 75% Poliéster, 20% Elastodieno, 5% Poliamida. Cansado de sentir dores e hematomas após treinos e jogos intensos? O Manguito Proteção Solar Esportivo chegou para elevar seu desempenho, oferecendo conforto, proteção e tecnologia de ponta para que você foque no que realmente importa: jogar e pedalar no seu melhor nível. Com sua tecnologia exclusiva Insect Defend, ele cria uma barreira protetora ao redor da pele, afastando mosquitos e insetos sem causar irritação. Além disso, sua proteção UV 50+ garante segurança contra raios solares, tornando-o ideal para treinos, jogos e pedaladas ao ar livre. BENEFÍCIOS • Liberdade de movimento: Materiais respiráveis e compressão ideal para maior performance. • Proteção inigualável: Tecnologia avançada para absorver impactos e minimizar o risco de lesões. • Conforto incomparável: Design ergonômico que se adapta ao corpo, proporcionando sensação de leveza durante todo o jogo, sem acumular suor. • Ideal para ciclistas: Proteção extra contra o sol e insetos em pedais longos, além de reduzir o atrito com o vento e melhorar a aerodinâmica. • Melhor recuperação muscular: A compressão auxilia na circulação sanguínea, reduzindo a fadiga durante e após o treino. O QUE ESTÁ INCLUSO? • 1 Par de Manguitos Proteção Solar Esportivo Poker. Junte-se à elite! Eleve sua performance e garanta proteção total dentro e fora das quadras e estradas! O PEDIDO ACOMPANHA NOTA FISCAL? Sim! Todos os pedidos são enviados com nota fiscal emitida para o CPF/CNPJ informado na compra. PRECISA DE AJUDA? Utilize o campo de perguntas e tire suas dúvidas diretamente com nossos atendentes.', 59.75, 31.25, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbqonz8loy1l52', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045256831%2F23693742291', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
