INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250447827', 'Vinil Egberto Gismonti - Egberto Gismonti (1973)', 'Vinil Egberto Gismonti - Egberto Gismonti (1973 / Transparente Translúcido) Lançado em 1973, o álbum homônimo Egberto Gismonti é um album do multi-instrumentista e compositor brasileiro Egberto Gismonti. Repertório do LP: Lado A: A1. Luzes Da Ribalta A2. Memória E Fado Academia De Dança Medley A3a. Dança Dos Homens A3b. Dança Das Sombras A4. Tango Lado B: B1. Encontro No Bar B2. Adagio B3. Variações Sobre Um Tema De Léo Brouwer B4. Salvador', 229.9, 229.9, NULL, 'Hobbies & Collections > Vinyl Records', 'https://cf.shopee.com.br/file/sg-11134201-825b1-mqnknzm08dtt55', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356917260%2F58250447827', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250146636', 'Smartphone Motorola Razr 60 - 256GB 12GB RAM+12GB Ram Boost, Tela dobrável 6,9" pOLED e externa 3,6”', 'O Motorola Razr 60 5G reinventa o conceito de smartphone dobrável com um design icônico que chama atenção desde o primeiro olhar. Com tela principal pOLED de 6,9" e uma tela externa de 3,6", você tem uma experiência visual completa — seja navegando em apps, assistindo vídeos ou conferindo notificações sem abrir o aparelho. Equipado com o poderoso processador MediaTek Dimensity 7400X, o Razr 60 entrega performance fluida no Android 15 para suas atividades diárias, multitarefa e aplicativos mais exigentes. Com 24 GB de memória RAM (12 GB + 12 GB RAM Boost) e 256 GB de armazenamento interno, você terá espaço e velocidade para tudo o que precisa — jogos, fotos, vídeos e muito mais. Registre seus melhores momentos com a câmera traseira principal de 50 MP com estabilização ótica e uma lente ultrawide para fotos amplas e criativas. A câmera frontal de 32 MP garante selfies nítidas e cheias de detalhes, perfeita para redes sociais ou videochamadas em alta qualidade. Com uma bateria de 4.500 mAh e carregamento rápido TurboPower, você não precisa se preocupar com a autonomia ao longo do dia — assista, jogue, trabalhe e conecte-se sem interrupções. E com 5G, Wi-Fi 6 e NFC integrados, o Razr 60 oferece conectividade moderna para qualquer situação. Além do visual sofisticado, o Motorola Razr 60 apresenta construção resistente com materiais de alta qualidade e certificação IP48 de proteção contra poeira e água, combinado com alto-falantes estéreo Dolby Atmos para som imersivo.', 3999.0, 3999.0, NULL, 'Mobile & Gadgets > Mobile Phones', 'https://cf.shopee.com.br/file/sg-11134201-821dv-mgmhbjd881zg5c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1627665738%2F58250146636', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
