INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998223924', 'Porta de Aço 215x75cm Laminada Minas Sul MGM Esquerda', 'As esquadrias MGM vêm recebendo ao longo dos anos vários prêmios concedidos através de pesquisas realizadas pelo IBOPE/ ANAMACO, tornando-se assim a número um no segmento da Construção civil. As esquadrias de aço MGM são projetadas para atender a uma grande variedade de públicos, são fornecidas com pintura de acabamento eletrostática a pó na cor branca garantindo uma cobertura uniforme e durabilidade superior, tendo como opção com ou sem grade e com ou sem vidro. Produtos produzidos em aço não são recomendados para as regiões litorâneas, podendo inclusive perder a garantia do produto. Garantia: 5 Anos Tipo de Vidro: Não possui Modelo da Porta: Abrir Escala de Brilho: Brilhante Lado de Abertura: Esquerda Textura da Porta: Veneziana Acompanha Puxador: 1 Origem do Produto: Nacional Tipo de Dobradiça: Simples Ambiente Principal: Sala de Jantar Acompanha Dobradiça: 3 Material do Batente: Aço Material do Puxador: Aço Quantidade de Folhas: 1 Acabamento do Puxador: Polido Material da Dobradiça: Aço Acabamento (Construção e Acabamento): Esmaltada Material Principal Construção e Acabamento: Aço Cor Predominante: Branco Tamanho do Produto: 215cm x 75cm Elétrica: Não Possui Grade: Não Possui Vidro: Não Acompanha Trinco: Sim Acompanha Batedor: Não Acompanha Batente: Sim Acompanha Fechadura: Sim Acompanha Guarnição: Não Necessita Instalação: Não Acompanha Olho Mágico: Não Possui Isolamento Acústico: Não Acompanha Manual de Instalação: Sim Marca: MGM Cor do Produto: Branco Linha ou Coleção: Minas Sul Medida do Vão (A x L): 217cm x 77cm Tipo de Certificado: Produto qualificado mediante a norma técnica ABNT NBR 10821. Peso (kg): 11.8361 Altura (cm): 215 Largura (cm): 75 Espessura (cm): 6 Largura do Batente: 6 Dimensão da 