INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598750533', 'Cama Solteiro em Madeira Maciça Nordik Branco/Lavado Branco Lavado', 'A Cama Solteiro Nordik combina conforto, robustez e um visual escandinavo que transforma qualquer dormitório em um refúgio acolhedor e cheio de estilo. Com estrutura totalmente em madeira maciça, a peça se destaca pelo trabalho artesanal que evidencia a beleza natural do pinus e pelas ripas verticais do encosto, que conferem leveza e personalidade ao ambiente. Seu design minimalista com linhas retas e pés torneados valoriza a sensação de amplitude, criando uma atmosfera contemporânea que se integra facilmente a diferentes estilos de decoração — do rústico ao moderno. O estrado de pinus, além de resistência, proporciona ventilação ao colchão, contribuindo para a conservação e o bem-estar durante o uso. Estilo: Moderno Peso (kg): 26.3 Garantia: 03 Meses Altura (cm): 104.2 Acabamento: Pintura Largura (cm): 108.6 Possui Baú: Não Possui Pés: Sim Possui Grade: Não Tipo de Cama: Convencional Possui Nichos: Não Possui Portas: Não Altura dos Pés: 31.9 Comprimento (cm): 209 Possui Gavetas: Não Possui Rodízio: Não Suporta Até (kg): 100 Possui Espelhos: Não Profundidade (cm): 209 Tamanho da Cama: Solteiro Tipo de Estrado: Removível Escala de Brilho: Fosco Material dos Pés: Madeira Maciça Acompanha Colchão: Não Origem do Produto: Nacional Acabamento dos Pés: Pintura Ambiente Principal: Quarto Material Principal: Madeira Maciça Necessita Montagem: Sim Possui Prateleiras: Não Material do Estrado: Pinus Possui Escrivaninha: Não Sapatas Niveladoras: Não Tipo de Madeira Maciça: Pinus Acompanha Cama Auxiliar: Não Complexidade da Montagem: Média: pode ser montado por mais de uma pessoa e/ou necessite de maior conhecimento para montagem Possui Trava de Segurança: Não Altura do Estrado até o Chão: 33 Peso Suportado por cada Cama: 100 Tipo de Madeira Maciça dos Pés: Pinus Altura do Estrado Superior até o Chão: 33 Permite a Utilização de Cama Auxiliar: Não Marca: Maison Arven Cor: Branco Lavado Cor do Produto: Branco Lavado Itens Inclusos: 1 Cama, Kit Ferragens e Manual de Montagem Cor Predominante: Branco Linha ou Coleção: Nordik Tamanho do Colchão Indicado (L x C): 88 x 188', 1032.21, 1032.21, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-7rdy7-mcliror5od3o9b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F23598750533', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
