INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19954816150', 'TOQUE E SINTA VAMOS LA - VEICULOS', 'Imagina além de ler a criança se divertir? A experiência de tocar e sentir deixa uma impressão duradoura na compreensão das crianças sobre o mundo ao seu redor. Este título foi pensado para tornar a leitura divertida e o aprendizado inesquecível, texturas únicas, texto incrível e ilustrações maravilhosas! Observações: livro cartonado (capa com acabamento melhor, estilo dura), importado e interativo.', 31.2, 31.2, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-22100-umazuv0euniv8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F19954816150', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6253870792', 'Poder: Para fãs de Once Upon a Time e Grimm - por Sarah Pinborough', 'a série Encantadas prova que contos de fadas são para adultos! Quando um príncipe mimado é enviado pelo seu pai para tentar desvendar os mistérios de um reino perdido, ninguém imagina os perigos que ele encontrará pela frente! Acompanhado da figura sóbria e sagaz do Caçador e de Petra, uma jovem valente que possui uma ligação muito forte com a floresta, o príncipe acaba encontrando um reino adormecido por uma estranha magia. Todos os seres vivos foram cercados pela densa mata e estão dormindo, em um sono pesado demais, que só poderia vir da magia. Mas que tipo de bruxaria assolaria uma cidade inteira e seus habitantes? E, principalmente, quem faria mal a uma jovem rainha tão boa e tão bela? A não ser, claro, que os olhos não percebam o que um coração cruel pode esconder...', 35.0, 35.0, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/b930411d38946a5f531d66f3ebef8641', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F6253870792', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
