INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22491587680', 'Refil Desengraxante H7 1 Litro', 'REFIL PARA ABASTECIMENTO H7 1 LITRO. O H-7 Desengraxante é um produto 100% biodegradável, a base de água, livre de ácidos ou solventes. Com isso é o produto ideal para usar na indústria, oficina, restaurante e também em casa. Basta borrifar o H-7 Desengraxante sobre a sujeira e esfregar com uma escova ou vassoura. Remover com água ou apenas um pano. O H-7 Desengraxante pode ser utilizado para limpezas diversas como: Máquinas Peças Motores Engrenagens Aviões Barcos Motos Correntes Pisos cimentícios ou cerâmicos Calçadas Pedras Pisos de porcelanato ou laminados Cerâmicas Rejuntes Azulejos Inox Alumínio Fogões Fornos Coifas Grelhas Panelas Balcões Armários impregnados com gordura Calçados Carpetes Roupas Toalhas Tapetes Ferramentas Caixas de gordura Equipamentos em geral Box de banheiro Bikes Churrasqueiras Portões Cadeiras de praia Piscinas Piche de asfalto da lataria ***ATENÇÃO*** COMPARE AS NUMERAÇÕES E DESCRIÇÃO DO ANÚNCIO COM A SUA PEÇA OU INFORMAÇÕES. EM NOSSO ANÚNCIO CONSTAM A MAIORIA DOS NÚMEROS DE CONVERSÃO PARA COMPARAR. CASO NÃO TENHA A NUMERAÇÃO QUE PROCURA, FAÇA UM PERGUNTA PARA QUE POSSAMOS LOCALIZAR A PEÇA EQUIVALENTE. EQUIPE DL AUTO PARTS.', 49.01, 49.01, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lianjdix5ub439', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F662883696%2F22491587680', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
