INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12320409528', 'Suporte Veicular Universal Para Celular Haste De Ventosa E Clip Ar Condicionado Tank Dinamic Gshield', 'O Suporte Veicular Tank Dinamic é prático e extremamente útil, especialmente para quem trabalha com transporte ou que gosta de acompanhar o transito pelo GPS no dia a dia. Com ele, é possível deixar o celular próximo às mãos e no campo de visão do motorista. Possui braços laterais ajustáveis que possibilita o uso de aparelhos de 6cm até 9,5 cm de largura, através do botão de ajuste, é possível regular e adaptar o suporte conforme o tamanho do seu smartphone! E graças a tecnologia da trava Gravity, você pode adequar a haste na posição que deseja e fixá-la, o suporte fica firme e o celular permanece seguro, para suportar trepidações e altas velocidades. Se tiver dúvidas utilize o campo de perguntas no final da página ou leia as avaliações de outros consumidores. ESPECIFICAÇÕES - Marca: Gshield - Tamanho: 11,5cm (altura) - Cor: Preta - Compatibilidade: celular de 6cm até 9,5 cm de largura - Movimentação: 360° - Fixação: trava de pressão ou presilha de pressão ajustada a entrada do ar-condicionado ITENS INCLUSOS - 1x Suporte Tank Dinamic - 1x Haste Flexível com Air Lock de sucção 1x Presilha de pressão para saída de ar', 129.99, 129.99, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Phone Chargers and Holders', 'https://cf.shopee.com.br/file/7fb1632d984d4284afe06a51f8842e0e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F12320409528', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
