INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898914184', 'Kit 2 Calcinhas Fio Dental Rafa Parize Basic Microfibra', 'O Kit Calcinhas Fio Dental Rafa Parize traz conforto, leveza e delicadeza para a sua rotina. Feitas em microfibra de toque macio e tecido respirável, essas calcinhas oferecem ajuste anatômico e sensação de frescor o dia todo. Composição: 89,10% poliéster | 6,44% elastano | 4,46% algodão Características: Tecido em microfibra leve, respirável e macio ao toque. Modelagem fio dental com ajuste anatômico. Não marca sob a roupa, ideal para o dia a dia. Cores delicadas e femininas para todas as ocasiões. Sensação de frescor e conforto prolongado. Qualidade e praticidade da marca Rafa Parize.', 25.99, 21.98, NULL, 'Women Clothes > Lingerie & Underwear > Panties', 'https://cf.shopee.com.br/file/sg-11134201-81zuy-mmkhr86grx1d32', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1536193928%2F23898914184', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18899193293', 'Coleção Minhas Primeiras 101 Palavras - Box com 3 Livrinhos', 'Projetada para ensinar de maneira lúdica e divertida, a coleção ajuda as crianças a expandir seu vocabulário e aprender novas palavras. Cada livro se concentra em um tópico específico para permitir que as crianças explorem diferentes áreas de conhecimento e linguagem. Minhas Primeiras 101 Palavras – Alfabeto ajuda as crianças a aprender o alfabeto e as palavras associadas a cada letra. Minhas Primeiras 101 Palavras – Animais introduz os animais às crianças, permitindo que associem imagens de animais a seus nomes. Meus Primeiros 101 Objetos – Números, Cores e Formas ensina sobre números, cores e formas usando objetos do cotidiano. Essa é uma maneira educativa e envolvente de apresentar palavras, conceitos e informações importantes para as crianças em uma fase inicial de desenvolvimento. Através de ilustrações cativantes e abordagem lúdica, as crianças podem aprender enquanto se divertem.', 89.7, 37.43, NULL, 'Books & Magazines > Books > Baby & Soft Books', 'https://cf.shopee.com.br/file/sg-11134201-7rcby-lqtbhw7dtn9424', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F18899193293', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
