INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22992917364', 'Espuma Do Banco + Base do Banco X-Cell CRF 150 - CRF 230 - Todos Os Anos', 'EMPRESA: J&J MOTORCYCLES Veja Algumas das Vantagens de Comprar Conosco: • Qualificações Positivas • Rapidez no Envio • Ótimo Atendimento • Compra Totalmente Segura ......................................................................................................................................................... PRODUTO: Espuma Do Banco X-Cell CRF 150 - CRF 230 - Todos Os Anos ......................................................................................................................................................... DESCRIÇÃO: • 1 Espuma Do Banco • 1 Base do Banco + 1 Espuma • Material: Soft-Célula • Fabricante: X-Cell • Marca: Honda • Modelo: Crf 150 / Crf 230 • Versão: Todas • Ano: Todos • Produto Paralelo Com Ótima Qualidade ***************************************************************** • A espuma de banco X-cell é considerada muito macia e confortável, transmitindo segurança na hora de pilotar. Confeccionada com espuma de tri-densidade (soft-célula) tecnologia quase mantém com mesmo molde dos modelos originais, não necessita de nenhuma adaptação para ser instalado.', 144.99, 144.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lt1e3s6v4glpda', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F307813655%2F22992917364', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8716103530', 'Kit Reparo Pulverizador Guarany com Compressão Prévia - 1,5 Litros', 'MANUTENÇÃO ORIGINAL PARA MÁXIMA PERFORMANCE E PRESSÃO O Kit de Reparo para Pulverizador Guarany é o conjunto oficial de peças de reposição para o modelo de compressão prévia PCP-1P. Essencial para manter a eficiência do seu equipamento, este kit soluciona problemas comuns de perda de pressão, vazamentos no gatilho ou falhas na compressão, devolvendo ao pulverizador a performance de um item novo. BENEFÍCIOS PRINCIPAIS: • Peças Originais Guarany: Garantia de ajuste perfeito e compatibilidade total com os componentes internos do pulverizador. • Restauração da Pressão: Substitui vedações ressecadas ou desgastadas pelo uso constante de produtos químicos. • Durabilidade Prolongada: Componentes fabricados em materiais resistentes, prolongando a vida útil do seu equipamento profissional. • Economia Garantida: Evita a substituição completa do pulverizador, permitindo uma manutenção rápida e de baixo custo. • Fácil Substituição: Componentes intuitivos que permitem a troca direta pelo próprio usuário ou técnico. COMPATIBILIDADE: • Pulverizador de Compressão Prévia Guarany Modelo: PCP-1P. MODO DE USAR: • Desmonte cuidadosamente o cabeçote e o sistema de compressão do pulverizador. • Remova os anéis de vedação (O-rings) e retentores antigos. • Limpe as sedes de vedação com um pano limpo para remover resíduos de produtos químicos. • Instale os novos componentes do kit, certificando-se de que estão bem posicionados. • Remonte o equipamento e realize um teste apenas com água para validar a vedação e a pressão. DICA CARXPARTS: • O uso constante de produtos alcalinos (como o Sintra) ou ácidos pode ressecar as vedações com o tempo. No Playbook CarXperience, recomendamos ter sempre um kit de reparo reserva em seu estoque para evitar paradas na operação. Para aumentar a vida útil das borrachas novas, aplique uma fina camada de graxa de silicone nos anéis O-ring antes da montagem.', 37.65, 37.65, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/br-11134207-820la-mqw09ekvho933a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F384950713%2F8716103530', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
