INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593242092', 'Hypofloat 5L Dub Boyz Lava Autos Pré Lavagem Automotivo', 'HYPO FLOAT 5L - LAVA AUTO PRÉ LAVAGEM - DUB BOYZ DESCRIÇÃO: Shampoo alcalino com pH 9, formulado à base de D''limoneno, um poderoso agente de limpeza natural derivado da casca da laranja. Este produto foi desenvolvido para remover todas as partículas de sujeiras soltas na superfície sem a necessidade de esfregação. Isso evita o atrito durante a lavagem, o que pode causar micro riscos. DILUIÇÃO: Baldes ou Shampoozeiras - 1:400 Snow Foam - 1:30 CARACTERÍSTICAS: - Espuma densa. - Poder de limpeza. - Ação desengraxante. - Alta diluição.', 138.92, 138.92, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Shampoo', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lzhnbgb29sph0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F23593242092', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293688774', 'Controle Remoto DJI FPV 3 (DJI Avata 2/DJI Neo) BR - DJI1044', 'Controle remoto DJI FPV 3 (DJI Avata 2) BR (DJI1044) Uma nova experiência de voo: conheça o DJI FPV 3. Projetado para o DJI Avata 2, esse novo controle da DJI está pronto para levar você a um novo nível. Compatível com transmissão de vídeo DJI O4 e com um design de antena integrado, ele permite um voo muito mais aprimorado e otimizado. O DJI FPV 3 é mais leve e possui um tempo de operação ainda mais longo. Os sticks dos controles estendidos em 2 mm permitem um encaixe mais confortável, facilitando o uso do controle, seja com um ou dois dedos. Além dos modos Normal e Esporte, o DJI FPV 3 apresenta uma nova forma de voar. Com o modo Manual, pilotos mais avançados podem praticar suas habilidades e uma performance mais elaborada com seu drone. O DJI FPV 3 também é compatível com simuladores, como Liftoff, Uncrashed, DCL e The Drone Racing League. Ficha técnica Marca: DJI Modelo: DJI1044 Peso: aprox. 240 g Cor: Cinza Conteúdo da Embalagem: 1x controle remoto DJI FPV 3, 1x par de sticks de controle do DJI FPV 3, 1x chave de fenda em forma de L Dimensões (CxLxA): 165 x 119 x 62 mm Tempo de operação: aprox.10 horas Tempo de carregamento: aprox. 2 horas Garantia: 12 meses Imagens meramente ilustrativas.', 1969.0, 1969.0, NULL, 'Cameras & Drones > Drone Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rbl3-m5uh2oajlzfb76', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F750964153%2F23293688774', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593353680', 'Glazox Zacs Selante Cerâmico Renovador de Pintura 500ml', 'GLAZOX 500ML ZACS DESCRIÇÃO: GLAZOX é um selante cerâmico desenvolvido com polímeros de última geração e Sio,, O produto aumenta o nível de brilho, proporciona total hidrorrepelêcia na pintura veicular e promove proteção de até 6 meses. MODO DE USO: 1- Agitar bem o produto antes de usar. 2- Após lavar e secar o veículo, pulverizar o produto na superfície em área não superior à 60cm x 60cm. 3- Em seguida, realizar o acabamento com uma toalha de microfibra até obter o brilho desejado. 4- Repetir o procedimento até a conclusão do veículo.', 52.8, 52.8, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0lkyni96vep88', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F22593353680', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
