INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898337603', 'Massa De Polir Luxcar Tira Riscos Recupera Pintura Queimada', 'MASSA DE POLIR TIRA RISCOS LUXCAR 500 G --------------------------------------------------------------------------------------- ELABORADA COM MATERIAS-PRIMAS NOBRES E TECNOLOGICAS, A MASSA DE POLIR TIRA RISCOS LUXCAR TEM COMO CARACTERISTICA PRINCIPAL RENOVAR PINTURAS DANIFICADAS PELA ACAO DO TEMPO, ELIMINANDO ARRANHOES E IMPERFEICOES PROMOVENDO UM BRILHO PROTETIVO DESDE O INICIO DO POLIMENTO. DEVIDO AO SEU ALTO PODER ABRASIVO, E INDICADO PARA POLIMENTO DE PINTURAS NOVAS E REPINTURAS DE PECAS DE QUALQUER NATUREZA, COMO CHAPAS OU FIBRAS PINTADAS. --------------------------------------------------------------------------------------- CONTEUDO NA EMBALAGEM: 1 NOTA FISCAL 1 MASSA DE POLIR TIRA RISCOS LUXCAR 500 G --------------------------------------------------------------------------------------- CARACTERISTICAS DO PRODUTO: IMAGEM ILUSTRATIVA ALTA QUALIDADE E DURABILIDADE COD INTERNO DO PRODUTO: 11020066 --------------------------------------------------------------------------------------- ANTES DE FINALIZAR A COMPRA: VERIFIQUE COM MUITA ATENCAO ATRAVES DAS FOTOS E DESCRICAO SE O PRODUTO E COMPATIVEL COM O MODELO QUE DESEJA ADQUIRIR. NOS NAO NOS RESPONSABILIZAMOS POR MA INSTALACAO OU MAU USO DO PRODUTO. PARA EVITAR TRANSTORNO PROCURE UM PROFISSIONAL ESPECIALIZADO.', 48.86, 48.86, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/sg-11134201-820ms-mo02esj5afwi50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F390168708%2F22898337603', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
