INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11198889083', 'Suporte Celular Gps Carro Veicular Trava Automatica 360º', 'Novo Suporte Prático, Super Seguro e Resistente. Diferente e melhor do que qualquer outro suporte que você viu! Universal: Compatível com Smartphones e GPS de até 4 à 6.8 polegadas 100% articulável Suporte veicular universal para Smartphone/GPS/Iphone trava automática base ventosa pratica. Com o suporte para Smartphone e GPS você terá fácil o mapa do seu trajeto enquanto se locomove no trânsito. As alças laterais se abrem até 8 cm, permitindo adaptação para vários tamanhos de dispositivos. Já a haste flexível, possui um comprimento de 24 cm, possibilitando diversos ajustes de forma simples e prática. A fixação é feita por uma ventosa e uma trava de sucção. Os ajustes possibilitam que o usuário customize o posicionamento da maneira que desejar, deixando o suporte na posição mais confortável e mais fácil de visualizar. Rápido e fácil de instalar. Itens inclusos 1 Suporte Veicular - MAIS Segurança! - MAIS Proteção! - MAIS Velocidade!', 55.0, 25.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Phone Chargers & Holders', 'https://cf.shopee.com.br/file/sg-11134201-824gs-me618bhfxqmeb7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F376716003%2F11198889083', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
