INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259445160', 'Linguiça Calabresa Seara', 'A Linguiça Calabresa Seara é feita com carnes nobres selecionadas e defumada naturalmente, garantindo um sabor autêntico e um tempero marcante com pimenta calabresa. Ideal para o feijão e para diversas receitas! * Experimente fatiar e adicionar em um macarrão ao sugo. * Prepare um delicioso arroz de carreteiro. * Utilize em molhos para pizzas ou como petisco.', 15.49, 15.49, NULL, 'Food & Beverages > Fresh & Frozen Food > Meat', 'https://cf.shopee.com.br/file/sg-11134201-81zus-miyqbkt58tfnbb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555072%2F58259445160', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993920657', 'Conjunto Sala de Jantar Mesa Tampo de Madeira 4 Cadeiras Sophie Madesa', 'O Conjunto de Jantar Sophie , da Madesa, é perfeito para renovar sua sala de jantar ou cozinha. A mesa possui tampo retangular em MDP e acomoda com muito conforto quatro pessoas. A base no formato pedestal agrega beleza e realça a modernidade deste conjunto. As cadeiras são produzidas em MDF e MDP, com assento estofado super fácil de limpar e combinar com os mais variados estilos de decoração. Para completar, o acabamento é feito em Pintura Poliéster ecológica , com 7 camadas de proteção e durabilidade. Medidas da cadeira: - 89 cm de altura - 37 cm de largura - 44 cm de profundidade Medidas da mesa: - 78 cm de altura - 120 cm de largura - 90 cm de profundidade Itens inclusos: - Uma (1) Mesa com base pedestal e tampo de MDP - Quatro (4) Cadeiras com assento estofado Código do produto: XMMDJA0401707GBE XMMDJA0401707GFL XMMDJA0401707GFB XMMDJA040170J7PT Obs.: - A Madesa não disponibiliza serviço de montagem - Imagens meramente ilustrativas. O conjunto é composto pela mesa e quatro cadeiras. - O produto segue com manual e todas as ferragens necessárias para a instalação 1 – O produto vem montado? Se não, vocês realizam a montagem? R.: A Madesa não disponibiliza serviço de montagem. Todos os produtos seguem com manual de instalação e as ferragens necessárias. Alguns produtos possuem vídeo explicando o passo a passo da montagem. 2 – Vocês possuem loja física? Posso retirar meu produto em mãos? R.: Não possuímos loja física, apenas loja virtual. Confira as opções de envio ao colocar o seu CEP. 3 – Qual é o valor do envio? Posso pagar separadamente? R.: O valor do envio é calculado com base no peso e volume do produto, e no CEP de destino. Você pode calcular o valor e prazo de entrega no simulador. 4 – A Madesa entrega em todo Brasil? Como é feita a entrega? R.: Sim, entregamos no Brasil inteiro através de transportadoras parceiras. 5 – Os produtos possuem garantia? R.: Sim. A Madesa oferece 3 meses de garantia para defeitos de fabricação. A Madesa possui compromisso com a sustentabilidade. Geramos energia limpa em nossa própria usina, priorizamos fornecedores responsáveis e utilizamos plástico reciclado em nossa produção. Além disso, reinserimos sobras no ciclo de reciclagem e investimos no desenvolvimento de nossos colaboradores e da comunidade. Garantia: Este produto conta com 1 ano de garantia total, sendo 3 meses de garantia legal e 9 meses de garantia contratual. A garantia cobre exclusivamente defeitos de fabricação e vícios ocultos. Não estão cobertos: problemas decorrentes de montagem incorreta, uso inadequado, exposição à umidade, calor ou luz solar direta, modificações no produto ou desgaste natural.', 779.99, 652.16, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-7reow-m8wcvka5pz6h68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F872473112%2F22993920657', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
