INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23191573385', 'Kit 5 Sancas de Isopor Moldura de Teto Forro Decorativa 1 Metro', 'Kit 5 Sancas de Isopor 1 Metro Observação: Não é enviado os Furos nem as Led Pode ser utilizada massa corrida para aplicação do produto. Recomendamos para dar acabamento a própria massa corrida não sendo muito diluída. Para pintar use tinta a base de Água Medidas do produto Kit 5 Sancas de Isopor 01 cada unidade: Comprimento - 100cm Largura - 20cm Espessura - 4,5cm Medidas do produto Kit 5 Sancas de Isopor 02 cada unidade: Comprimento - 100cm Largura - 15cm Espessura - 10cm Especial para Forros de Gesso e Tetos de Laje', 99.9, 94.9, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/br-11134207-7qukw-li7rzhsi6xm86e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322399178%2F23191573385', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23694224140', 'Armário de Cozinha Compacta 180 cm Rustic/Verde Vik Madesa 02', 'A Cozinha Compacta da Linha Vik da Madesa é a escolha ideal para quem busca maximizar o espaço sem abrir mão de elegância e praticidade. Com 180 cm de largura, essa cozinha compacta oferece organização inteligente e um design clássico, que une o charme do estilo americano com toques modernos e sofisticados. Além disso, a linha Vik é funcional em cada detalhe. As portas possuem dobradiças com amortecimento, garantindo um fechamento suave e silencioso, enquanto as gavetas permitem abertura total, garantindo muito mais facilidade. O acabamento de alta resistência da estrutura é em tom amadeirado Rustic e das frentes em Verde, possui uma textura suave ao toque. O destaque fica por conta dos puxadores ponto em ouro envelhecido, feitos com metal resistente, trazem personalidade e um charme único. Os armários e balcões foram cuidadosamente projetados para aproveitar ao máximo o espaço, o balcão de pia, permite a instalação de pia de inox ou pedra. Além disso, o aéreo com porta basculante possui um sistema de pistão a gás que mantém a porta suspensa quando aberta, proporcionando mais praticidade e segurança no uso diário. Medidas totais: Altura: 225 cm Largura: 180 cm Profundidade: 52 cm (módulos inferiores) 31 cm (aéreos) O que você recebe: 1 Aéreo de 120 cm com 2 portas 1 Balcão de Pia com 2 portas e 3 gavetas (não acompanha tampo) 1 Aéreo de 60 cm com 1 porta basculante Código do produto: GRVK180002M3 É Importante saber: As imagens são meramente ilustrativas; os eletros e a decoração não acompanham o produto; A Madesa não oferece serviço de montagem; Produto acompanha manual e ferragens necessárias. A Madesa se dedica à sustentabilidade: temos uma usina própria que gera energia para uma de nossas fábricas, priorizamos fornecedores responsáveis e reciclamos plásticos na produção. Também investimos no desenvolvimento dos colaboradores e em ações sociais. Garantia: Este produto conta com 1 ano de garantia total, sendo 3 meses de garantia legal e 9 meses de garantia contratual. A garantia cobre exclusivamente defeitos de fabricação e vícios ocultos. Não estão cobertos: problemas decorrentes de montagem incorreta, uso inadequado, exposição à umidade, calor ou luz solar direta, modificações no produto ou desgaste natural.', 2089.99, 1782.6, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rdyx-mc6rhhk59h378f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F872473112%2F23694224140', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
