INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20697923514', 'Carrinho Portátil para Máquina de Solda Cilindro Vonder Suporte Transporte Soldagem Roda Resistente', 'Carrinho Portátil Para Máquina De Solda E Cilindro Vonder O Carrinho Portátil para Solda é a solução ideal para quem busca praticidade e organização no transporte de equipamentos de solda e cilindros de gás. Com capacidade de carga de até 50 kg e estrutura em aço carbono, este carrinho é robusto e eficiente, facilitando o manuseio de máquinas de solda em diversos ambientes. Itens Inclusos 1 Carrinho Portátil para Máquinas de Solda; Manual de instruções. Detalhes Técnicos Capacidade de carga: Até 50 kg; Material: Estrutura em aço carbono (resistente e durável); Dimensões: 700 mm x 395 mm x 710 mm; Peso: Aproximadamente 12,8 kg; Aplicações: Transporte de máquinas de solda e cilindros de gás de até 4 m³. Por que escolher este produto? ✔ Produto novo e original; ✔ Pronta entrega e envio em até 24 horas; ✔ Compra 100% segura.', 729.99, 729.99, NULL, 'Home & Living > Tools & Home Improvement > Trollies', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1r3pdea800824', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1363787561%2F20697923514', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794431603', 'Carregador Parede Ugreen Porta Usb-A/C Máx 65W Azul Rosa', 'Carregador Parede Ugreen Portas Usb-A/C Máximo 65W Azul-Rosa, Design Robot, Ampla Compatibilidade 1. Capacidade Elevada e Versátil: O Carregador Robot Ugreen é uma solução de carregamento poderosa e versátil, equipada com uma porta USB-A e duas portas USB-C, proporcionando até 65W de potência máxima. É ideal para alimentar rapidamente uma variedade de dispositivos, desde smartphones até laptops. 2. Design Moderno em Azul-Rosa: Com um acabamento elegante na cor Azul-Rosa, este carregador não só é funcional, mas também um acessório estético para qualquer espaço. Ele adiciona um toque de cor e design contemporâneo ao seu escritório ou estação de trabalho em casa. 3. Tecnologia de Carregamento Rápido: As portas USB-C suportam o carregamento rápido, permitindo que você recarregue seus dispositivos em velocidades significativamente reduzidas em comparação com carregadores padrão. Este recurso é perfeito para quem precisa de eficiência e rapidez. 4. Portabilidade e Conveniência: Compacto e leve, o Carregador Robot Ugreen é fácil de transportar e usar em diferentes locais. Seja em casa, no escritório ou em viagens, ele garante que você sempre terá acesso a uma solução de carregamento rápido. 5. Segurança Avançada: Com múltiplas proteções incorporadas, este carregador protege seus dispositivos contra sobrecarga, sobretensão e superaquecimento. Assim, você pode ficar tranquilo sabendo que seus dispositivos estão sendo carregados de maneira segura e eficiente. Garantia 90 dias', 345.73, 345.73, NULL, 'Mobile & Gadgets > Accessories > Cables, Chargers & Converters', 'https://cf.shopee.com.br/file/br-11134275-81z1k-mf188hhseoljb8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1163359442%2F22794431603', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698880267', 'Câmera Veicular Azdome M01 Pro Dual 1080p Adas + Micro Sd', 'Câmera Veicular Azdome M01 Pro Dupla Frontal e Traseira Full HD 1080p Tela de 3 Polegadas Visão Noturna WDR Sensor G Gravação em Loop Sistema ADAS Monitoramento de Estacionamento com Cartão 64GB 1. Monitoramento Duplo de Alta Resolução Azdome: Registra simultaneamente a movimentação frontal e traseira do veículo com sensores Full HD 1080p, oferecendo ampla cobertura de ângulo que reduz os pontos cegos no trânsito diário. 2. Visão Noturna Avançada com Tecnologia WDR: O sistema de processamento de imagem ajusta de forma automática a exposição de luz, capturando detalhes importantes como placas de veículos e sinalizações mesmo em ambientes de baixa luminosidade. 3. Sensor G e Gravação em Loop Automática: O sensor de gravidade integrado detecta impactos ou frenagens bruscas, travando o arquivo de vídeo atual para que não seja sobrescrito, preservando os registros em um cartão de memória de 64GB incluso. 4. Assistência de Condução com Sistema ADAS: Tecnologia embarcada que oferece alertas de saída de faixa e proximidade de veículos, servindo como um suporte tecnológico eficiente para as viagens de curta ou longa distância. 5. Modo Estacionamento e Tela de 3 Polegadas: Monitoramento contínuo para o automóvel enquanto estiver estacionado, combinado com uma tela compacta e nítida para configuração rápida das funções e visualização imediata dos vídeos salvos. Garantia 90 dias MARCA: AZDOME SKU: 9356 R.NUMBER: M01 Pro EAN: 6973888260368', 539.58, 539.58, NULL, 'Cameras & Drones > Security Cameras & Systems > Others', 'https://cf.shopee.com.br/file/br-11134275-81z1k-meeomiz5ce82b5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1163359442%2F23698880267', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298685658', 'Emblema VW CAPO FUSCA Cromado Fusca antigo', 'Emblema logo VW capo fusca cromado - Fusca antigo -Medidas: 7,7 x 7,7 cm confirmar medidas antes da compra com seu veículo Cor: Cromado - Aplicação: * Fusca antigo - Emblema com fita dupla face - Valor referente a 01 unidade - As fotos do produto são apenas ilustrativas. - Este produto não é original. Apenas compatível com o modelo do veículo. - Dúvidas? Mandem em nosso chat!', 22.1, 21.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbdxkqodjg1l82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1254320229%2F22298685658', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
