INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394284888', 'Bóia Paulistinha De Arremesso C/Chumbo 10cm 35g Ideal Para Pesca De Robalos Carpas Pirara Cores Diversas Pescaria', 'Bóia Paulistinha Arremesso com Chumbo e Chocalho – 10 cm, 35 g – Cores Diversas A Bóia Paulistinha Arremesso com Chumbo é fabricada em plástico de alta densidade, material que garante resistência e durabilidade. Em seu interior, possui esferas que produzem ruído tipo chocalho, aumentando o poder de atração dos peixes predadores. Conta com chumbo embutido como lastro, o que proporciona arremessos mais longos e precisos, mesmo com vento. Seu design é ideal para quem busca bom desempenho na pescaria. É muito utilizada na pesca de robalos em mangues, com iscas vivas como camarão, sardinha ou lambari. Também se destaca em pesqueiros, sendo eficaz na captura de carpas e tucunarés. Com aproximadamente 10 cm de comprimento e 35 g de peso, é uma ferramenta essencial para pescadores que valorizam praticidade, sensibilidade e resultado. Produto de qualidade, desenvolvido pela tradicional marca Bóias Paulistinha. Especificações: Marca: Bóias Paulistinha Modelo: Plástica com chumbo e chocalho Material: Plástico e chumbo Comprimento: 10 cm Diâmetro: 5 cm Peso aproximado: 35 g', 40.89, 38.85, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcwf8rgqt44y22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F320275364%2F22394284888', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
