INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54803197999', 'Crianças Geniais | Villa Lobos', 'A Coleção Crianças Geniais apresenta os primeiros anos de vários personagens que marcaram o nossa História, mostrando que tudo pode ser bem parecido com as coisas que você vive no seu dia a dia: família irmãos, amigos, escola, brincadeiras e até mesmo alguns probleminhas de percurso… Aqui todos eles brincam, estudam, se relacionam e, principalmente, sonham em transformar o mundo, de maneira diferente e para melhor. 22x22 cm 24 Páginas', 12.9, 7.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-822wr-mich39xqh4ox1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F54803197999', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
