INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7686341200', 'Kit 2 Borracha De Porta Tipo Original Sandero 2012 2013 2014', 'Detalhes do Produto: Kit 02 Borracha De Porta Tipo Original Sandero e Logan 2007 Até 2014 e Duster 2011 Até 2016 Os veículos possuem componentes de borracha nas portas, vidros e no teto que tem por função evitar a infiltração de água e também no caso das Canaletas e Pestanas formam o trilho do vidro. A avaliação periódica desses componentes é recomendada, para que eventuais infiltrações não comprometam a lataria, provocando sua corrosão e molhando o interior do veiculo. Compatível com veículos: Sandero 2007 2008 2009 2010 2011 2012 2013 2014 Logan 2007 2008 2009 2010 2011 2012 2013 2014 Duster 2011 2012 2013 2014 2015 2016 Especificação Técnica: Alta resistência e durabilidade Qualidade padrão original Borracha casco de cobra Impede a entrada de pó e outros materiais Impede a infiltração de água Reduz o nivel de ruídos externos Evita correntes de ar, perda de climatização Na cor preta Importante: Garantia da borracha: 02 anos contra defeito de fabricação Valor de 2 borrachas (serve para todas portas) Imagens meramentes ilustrativas Recomendamos que a instalação seja feita sempre por um profissional A Nolascoshopnão se responsabiliza por mal instalação ou uso indevido do produto Itens Inclusos: 02 Borrachas de porta (02 anos de garantia)', 158.26, 158.26, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/fda2b4fc357f5bf30286ea6fd3fde082', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F391224294%2F7686341200', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19597632808', 'Mini Beijos de Morango com 12 pacotes de 15g cada - Fini', 'Beijos de morango Fini, um clássico da marca. Com fórmula nova, muito mais macia e saborosa. No pacote contém meia esfera na cor rosa e branco, com sabor de morango Display com 12 pacotes com 15g de produto em cada, ideal para rapidos lanches, levar na bolsa, deixar na gaveta e distribuir para os amigos, E perfeito para usar em decorações de mesas de festas e pratos de confeitaria, tornando tudo mais colorido, com um toque único e especial! Disponivel também em: 500g, 250g e 90g.', 15.02, 15.02, NULL, 'Food & Beverages > Snacks > Sweets & Candy', 'https://cf.shopee.com.br/file/sg-11134201-7rces-ls1ooq4l29dr45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F992995220%2F19597632808', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
