INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18207191052', 'VINHO PULENTA FINCA LA ZULEMA MALBEC 2019 750ML', 'varietal de Malbec cujas uvas são provenientes de vinhedos da Finca La Zulema, plantados em 1992 em Agrelo – Luján de Cuyo (Mendoza), traz consigo um respeitoso 90 pontos pelo crítico James Suckling e, apesar de não ter alcançado a faixa dos 90 pontos na Robert Parker Wine Advocate (ficou com 88 pontos), a resenha de Luis Gutiérrez o descreve com perfeição: “um jovem, direto e frutado Malbec, engarrafado sem amadurecimento em barricas. Um ótimo Malbec de entrada, justo e acessível.” A história da Pulenta Estates remonta ao ano de 1902, quando Ângelo Pulenta e Palmina Spinsonti, deixam a comuna de Ancona na Itália e emigram para a Argentina. Décadas se passaram e a família se tornou uma das mais respeitadas da vitivinicultura argentina. Atualmente a vinícola é gerida por Eduardo e Diego Pulenta, da quarta geração.', 115.08, 115.08, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/f8173da0ae5948e8491543d87dd87bde', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F661273874%2F18207191052', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
