INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22893553667', 'Camiseta Shopito - I''m a Doguinho Lover', '🛒✨ Lançamento Exclusivo na Streetblanks! ✨🛒 Chegaram as camisetas estampadas oficiais da Shopee! Para os verdadeiros apaixonados por fazer comprinhas, apresentamos 3 estampas incríveis que trazem o espírito da Shopee diretamente para o seu estilo. E, claro, não poderia faltar ele: o mascote Shopito em versões criativas e cheias de personalidade! Garanta a sua e leve a vibe das compras para o seu dia a dia! 🧡👕 Conheça a peça: Uma escolha clássica e de alta qualidade, com excelente custo-benefício. Confeccionada em malha fio 30.1 de algodão penteado, proporciona conforto e ótima transpiração. Sua modelagem streetwear traz medidas maiores no comprimento, gola com anel de 2,7 cm e ribana canelada 2×1 com elastano, garantindo estilo e durabilidade. O reforço ombro a ombro adiciona ainda mais resistência à peça. Quem valoriza qualidade, escolhe a Streetblanks. Informações Técnicas Composição: 100% algodão fio 30.1 penteado; Gramatura: 180 g/m²; Gola em anel de 2,7 cm, ribana canelada 2×1 com elastano e pesponto de 2 agulhas; Reforço ombro a ombro; Bainha e barras com 2 cm; Estampas aplicadas em DTF (Direct to Film); Etiqueta interna de composição; Etiqueta de tamanho interna no ombro. Pra encontrar o tamanho ideal, encontre a tabelas de medidas na galeria de fotos e faça uma comparação com uma camiseta que veste bem em seu corpo. Atenção O tamanho G1 corresponde ao tamanho XG; As cores nas fotos podem variar de acordo com o seu monitor ou dispositivo; Encolhimento em produtos de algodão é natural e podem ocorrer entre 3% a 5%; As medidas das peças podem sofrer variações de até 1% nos tamanhos informados na tabela.', 79.99, 79.99, NULL, 'Men Clothes > Tops > T-Shirts', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m3dhopo