INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893990406', 'MOTOR DO LIMPADOR PARABRISA GRAND SIENA NOVO PALIO 520059780', 'MOTOR DO LIMPADOR SE QUISER CONFIRMAR A APLICAÇÃO ANTES DA COMPRA, PODE CONTAR COM A GENTE. VOCÊ PODE: CONFERIR O CÓDIGO ORIGINAL DA PEÇA OU, SE PREFERIR, ENVIAR UMA FOTO AQUI NO CAMPO DE PERGUNTAS RESPONDEMOS COM ATENÇÃO E RAPIDEZ PRA TE AJUDAR A ACERTAR NA ESCOLHA. ESPECIFICAÇÕES TÉCNICAS · VOLTAGEM – 24V · PLUG – 4 PINOS CÓDIGOS ORIGINAIS · FIAT: 520059780 CÓDIGOS SIMILARES APLICAÇÃO FIAT GRAND SIENA - 2012 ATÉ 2021 FIAT NOVO PALIO - 2012 ATÉ 2017 REFERÊNCIA · CEMAK: CK-7.404 GARANTIA 3 MESES INFORMAÇÕES IMPORTANTES PRODUTO NOVO ACABAMENTO DE ALTA QUALIDADE BOA DURABILIDADE PARA USO NO DIA A DIA DA OFICINA ANTES DA COMPRA PARA GARANTIR A APLICAÇÃO CORRETA, RECOMENDAMOS: CONFERIR O CÓDIGO ORIGINAL DA PEÇA COMPARAR COM AS IMAGENS E ESPECIFICAÇÕES DO ANÚNCIO SE PREFERIR, PODE NOS CHAMAR NO CAMPO DE PERGUNTAS FICAMOS À DISPOSIÇÃO PRA TE AJUDAR A CONFIRMAR ANTES DA COMPRA. INSTALAÇÃO A INSTALAÇÃO DEVE SER REALIZADA POR PROFISSIONAL QUALIFICADO. ISSO GARANTE O MELHOR DESEMPENHO DA PEÇA E EVITA QUALQUER TIPO DE PROBLEMA NO SISTEMA. SOBRE ATENDIMENTO E SUPORTE SE HOUVER QUALQUER DÚVIDA OU NECESSIDADE APÓS A COMPRA, PODE CONTAR COM A GENTE. EM CASO DE DIVERGÊNCIA EVITE UTILIZAR-SE DO CAMPO RECLAMAÇÃO, NESTE CASO, NOS CHAME PELO CHAT QUE NOSSA EQUIPE ESTÁ PRONTA PRA TE AJUDAR DA FORMA MAIS RÁPIDA E SIMPLES POSSÍVEL. INFORMAÇÕES DO PRODUTO TODAS AS INFORMAÇÕES TÉCNICAS SÃO FORNECIDAS PELO FABRICANTE. SOBRE A PEÇA DO MECÂNICO A PEÇA DO MECÂNICO TRABALHA COM FOCO EM QUEM VIVE DA MECÂNICA E PRECISA DE AGILIDADE, CLAREZA E CONFIANÇA NO DIA A DIA. SE SURGIR QUALQUER DÚVIDA ANTES OU DEPOIS DA COMPRA, PODE CHAMAR. A IDEIA É FACILITAR SEU TRABALHO.', 360.0, 360.0, NULL, 'Spare Parts and Accessories for Vehicles > 