INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493222134', 'Mini Mop Portátil Pano Limpeza Mesa Absorve Espreme Sujeira', 'MINI MOP PORTÁTIL LIMPA TUDO --------------------------------------------- Material: Plástico Medidas: 15,5 cm x 29,5 cm --------------------------------------------- Um "Mini Mop Portátil Limpa Tudo" um dispositivo compacto projetado para limpeza de superfícies pequenas e de difícil acesso. Um mini mop portátil geralmente composto por um cabo telescópico e uma almofada de limpeza. O cabo telescópico permite ajustar o comprimento conforme necessário, tornando-o conveniente para alcançar áreas de difícil acesso, como cantos, frestas ou superfícies elevadas. A almofada de limpeza geralmente removível e lavável, permitindo a reutilização. Esse tipo de mop ideal para a limpeza rápida de pequenas áreas, como pisos laminados, azulejos, bancadas, mesas ou outras superfícies planas. Ele pode ser usado para remover poeira, sujeira leve ou pequenos derramamentos. Geralmente, o mini mop portátil leve e fácil de transportar, tornando-o conveniente para uso doméstico ou até mesmo em viagens.', 35.0, 14.7, NULL, 'Home & Living > Home Care Supplies > Mops', 'https://cf.shopee.com.br/file/sg-11134201-7rdwr-lz0lpkg9c2did3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F376716003%2F23493222134', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
