INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393058237', 'Fonte De Alimentação Pc Gamer Cowboy Atx 600w Leds Rgb', 'Fonte de Alimentação PC Gamer Cowboy ATX 600W Leds RGB A fonte de Alimentação Cowboy ATX 600W foi desenvolvida para atender às principais exigências dos fanáticos por games, esta fonte não só fornece uma energia estável, mas também adiciona um toque de estilo ao seu setup com seus LEDs RGB integrados. Com 600W de potência, essa fonte proporciona energia estável necessária para suportar configurações de PC gamer de médio a alto desempenho. E conta com ventiladores silenciosos que garantem uma operação eficiente e resfriamento adequado, mesmo em sessões de jogos intensas e leds em RGB integrados para dar uma experiência visual incrível, adicionando um toque de estilo e personalização ao seu sistema. Dimensões: 15x14cm (CxL) Peso: 1,006kg Especificações: - Modelo: KP-535RGB - Potência: 600W - Fonte Bivolt - MTBF de 100.000 horas 25°C - Proteção contra curto circuito OVP/OCP/SCP - Chaveamento manual 100/230Vac - Cooler de 120mm ultra silencioso - Cabos com capa de proteção - Normas técnicas IEC60950 (Segurança elétrica) IEC61000 (Segurança eletromagnética) - 1 Conector ATX 20+4 Pinos - 1 Conector ATX 12V - 3 Conectores SATA - 3 Conectores IDE - 1 Conector FDD - Compatível com placas mãe de 20 e 24 pinos - Chave Seletora de tensão Itens inclusos: 1 Fonte de Alimentação 1 Cabo de Energia Warranty Duration:3 Months', 330.0, 231.09, NULL, 'Computers & Accessories > Desktop & Laptop Components > Power Supply Units', 'https://cf.shopee.com.br/file/sg-11134201-7rbm3-m5udo5rrvivsec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F376716003%2F23393058237', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209464128', 'Gin London Pink Strawberry Beefeater', 'Desfrute de um gin vibrante e saboroso com Beefeater Pink Strawberry, uma versão moderna do clássico London Dry Gin, infundido com aroma natural de morango. Perfeito para quem busca um toque adocicado e refrescante. Ideal para ser apreciado puro com gelo, em drinks ou em coquetéis criativos. Harmoniza bem com tônica, limonada e frutas frescas como morangos. Beba com moderação.', 119.79, 119.79, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/sg-11134201-8259p-mqnelxu8934f9d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555024%2F58209464128', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
