INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798407082', 'Suporte Notebook Cooler USB 12" a 19" 6 Ventoinhas Ângulo Ajustável Oberon OR-SP251', 'Suporte com Cooler USB Oberon OR-SP251 é a escolha ideal para quem busca desempenho eficiente na refrigeração do notebook aliada a um design moderno e funcional. Compatível com notebooks de 12 a 19 polegadas, ele oferece ampla versatilidade para atender diferentes tamanhos de dispositivos. Equipado com 6 ventoinhas de velocidade ajustável, proporciona excelente ventilação, mantendo seu equipamento em temperatura ideal mesmo durante tarefas mais exigentes. Seu ângulo inclinado ajustável permite melhor ergonomia e conforto durante o uso prolongado. Alimentado por uma conexão USB com tensão de 5VDC e potência de 4,5W, oferece praticidade sem a necessidade de fonte externa. Fabricado com material resistente, garante durabilidade e segurança no dia a dia. ESPECIFICAÇÕES: - Modelo: OR-SP251 - Marca: Oberon - Tensão: 5VDC via porta USB - Potência: 4,5W - Compatível com: Notebooks de 12" a 19" - Ventoinhas: 6 unidades com velocidade ajustável - Inclinação: Ajustável - Material: Resistente CONTEÚDO: 1 Suporte com cooler', 166.22, 127.05, NULL, 'Computers & Accessories > Peripherals & Accessories > Cooling Pads', 'https://cf.shopee.com.br/file/sg-11134201-7reol-m8we0rs8u1lu2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F376716003%2F23798407082', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23328100327', 'Brinquedo Arco e Flecha Infantil Radical com Luz Alvo e Flechas com Ventosas', 'O Anúncio Contém: 01 Arco Infantil, 01 Alvo, 01 Aljava (porta-flechas),03 Flechas com ventosa. Perguntas Frequentes: As flechas são seguras? As flechas possuem ponta de ventosa, tornando a brincadeira mais segura para as crianças. Qual o material do produto? Fabricado em plástico resistente e livre de toxicidade, ideal e seguro para o uso infantil. O arco possui luzes? Sim, o arco possui pontos de luz que acendem, tornando a brincadeira mais emocionante. Indicado para qual faixa etária? Recomendado para crianças a partir de 5 anos. Kit Arco e Flecha Infantil – Aventura e Pontaria para os Pequenos! Este kit de arco e flecha da Brinqkids é o presente perfeito para incentivar o esporte, a coordenação visual-motora e a brincadeira ativa. O arco e a aljava são temáticos e coloridos, chamando a atenção dos pequenos aventureiros. As luzes adicionam um toque especial, elevando a experiência de "Super Arqueiro"! É fácil de manusear e montar, e o alvo com pontuação permite que as crianças se desafiem em competições divertidas de mira. Informações e Dimensões: -Arco: Aproximadamente 59cm de altura. -Flechas: Aproximadamente 41cm de comprimento. -Aljava: Aproximadamente 30cm de altura. -Alvo: Aproximadamente 20cm de diâmetro. -Idade recomendada: A partir dos 5 anos. -Marca: Brinqkids. -Produto novo e em estoque. -Todos os produtos têm seguro contra extravio. -Todas as informações são de responsabilidade do fabricante e/ou fornecedor. -As cores e detalhes do produto podem variar levemente conforme o lote. -Aviso Legal: A cópia total ou parcial desta descrição e/ou fotos é proibida e protegida pela Lei nº 9.610/98 de Direitos Autorais.', 129.9, 79.9, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhi0t9xcstfnd8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F405000440%2F23328100327', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
