INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20750004205', 'Kit Churrasqueira Gol Bola G2 Saveiro Parati Premium', 'Kit Churrasqueira do Para-Brisa – Gol / Parati / Saveiro G2 Bola – Premium O Kit Churrasqueira do Para-Brisa para Volkswagen Gol, Parati e Saveiro G2 (Bola) é fabricado em material premium de alta resistência, garantindo encaixe perfeito, excelente acabamento e longa durabilidade. Instalada na base do para-brisa, a churrasqueira protege o sistema de ventilação contra água, folhas e sujeira, além de manter o visual original do veículo. Produto novo, com padrão tipo original e instalação simples. Compatibilidade: Volkswagen Gol Bola G2 – 1995 a 1999 Volkswagen Parati Bola G2 – 1995 a 1999 Volkswagen Saveiro Bola G2 – 1995 a 1999 Volkswagen Gol Special – 2000 a 2002 (Aplicação na base do para-brisa dianteiro.) Características: Kit completo (lado direito e esquerdo) Linha Premium Excelente acabamento Alta resistência e durabilidade Encaixe perfeito Padrão tipo original Produto novo Conteúdo da Embalagem: 1 Churrasqueira 1 Borracha Vedação 6 Tampinhas de Arremate da Churrasqueira 6 Parafusos de Fixação com Buchas Tempo de Garantia: GARANTIA 3 MESES Observações: PARA EVITAR PROBLEMAS NA INSTALAÇÃO DO PRODUTO ELA DEVE SER FEITA POR UM PROFISSIONAL', 200.26, 180.24, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/edee41edddcbced8083a3772f72f782e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F691145803%2F20750004205', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
