INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497095338', 'Mochila Laptop Harry Potter Mapa do Maroto Imaginarium para Notebook até 14 Polegadas', 'A Mochila Laptop Harry Potter Mapa do Maroto Imaginarium é a escolha perfeita para quem deseja unir praticidade, organização e um toque de magia no dia a dia. Inspirada no icônico Mapa do Maroto, ela traz acabamento em tom marrom com detalhes bordados exclusivos, que remetem diretamente ao universo de Hogwarts. Projetada para acompanhar sua rotina, a mochila possui alças acolchoadas ajustáveis, alça de mão reforçada e dois bolsos laterais funcionais. Seu interior conta com duas aberturas principais com fechamento em zíper: a primeira oferece amplo espaço e compartimentos internos ideais para acessórios essenciais como celular, chaves e óculos; já a segunda é dedicada para armazenar com segurança um notebook de até 14". Além disso, acompanha uma tag identificadora, garantindo mais praticidade em viagens e deslocamentos. Fabricada em materiais de qualidade, combina resistência e estilo para fãs da saga que buscam funcionalidade no dia a dia. Especificações: Contém: 1 mochila e 1 acessório (não vendidos separadamente) Material: 70% algodão, 30% poliéster Forro: 100% poliéster Ferragens: zinco Detalhes: 70% poliuretano, 30% poliéster Capacidade máxima: 5 kg Compartimento para notebook de até 14" Medidas: 42 cm (altura) x 32 cm (largura) x 20 cm (profundidade) Cuidados: limpar com pano levemente umedecido; evitar produtos químicos e abrasivos Validade: indeterminada', 629.0, 629.0, NULL, 'Men Bags > Backpacks', 'https://cf.shopee.com.br/file/sg-11134201-7rbnl-lnj4goyctqx8c4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F789092088%2F22497095338', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
