INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17892370453', 'Jardim dos Sonhos | Felicidade Plena', 'Você merece um tempo para chamar de seu! Assim, deixe de lado o estresse do dia a dia, respire fundo e entre no jardim dos sonhos. Colorir cada página sem seguir regras ou padrões. Aqui, só há espaço para a sua criatividade e, claro, para o seu relaxamento. Sem contar os benefícios terapêuticos da atividade de colorir são comprovados no mundo todo, entre os quais, proporcionar relaxamento e melhorar o foco. Teste e comprove você também!', 24.99, 19.99, NULL, 'Books & Magazines > Books > Others', 'https://cf.shopee.com.br/file/sg-11134201-23020-7cxi3nt6s1mv0d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F17892370453', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497312561', 'Mochila Grande Slim Notebook 15 Sestini Elegance - Nude', 'Mergulhe na fusão de elegância e utilidade com a Mochila Grande Slim Notebook 15 Sestini Elegance Nude. Projetada para acompanhar o ritmo da vida moderna, ideal para faculdade, trabalho, ambientes mais formais e até viagens curtas. Garanta que seu equipamento esteja sempre protegido contra impactos e arranhões. Esta mochila se destaca por seu compartimento acolchoado exclusivo, que acomoda notebooks de até 15 polegadas com segurança. Segurança avançada: puxador com trava antifurto e bolso escondido nas costas para proteção extra dos seus bens. Conforto superior: alças e costas espumadas que garantem bem-estar mesmo com a mochila cheia. Design elegante e slim: a cor nude e o formato slim conferem um visual sofisticado, perfeito para ambientes profissionais e casuais. Funcionalidade inteligente: bolsos laterais expansíveis e alça carona para maior praticidade no dia a dia e em viagens. Altura (cm): 43 Largura(cm): 43 Profundidade (cm): 16 Peso (kg): 1 Capacidade Total (L): 19', 429.9, 429.9, NULL, 'Baby & Kids Fashion > Baby & Kids Accessories > Bags & Luggage', 'https://cf.shopee.com.br/file/sg-11134201-81zv1-miedujuit81v0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F867958784%2F22497312561', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20697786639', 'Chinelo Mae e Filha Sandália Birken Feminina Confortável Menina Promoção Camin', 'Chinelo Mae e Filha Birkin Feminino Flat Brilho Strass Moda Camin 28 ao 39 Descubra o conforto e estilo incomparáveis com nossas sandálias disponíveis nos tamanhos 28 a 39! Perfeitas para todos os momentos, elas combinam design moderno e ajuste perfeito para garantir que seus pés estejam sempre na moda, seja no dia a dia ou em ocasiões especiais. Encontre o par ideal para você e dê um toque de elegância ao seu visual! *ATENÇÃO* Para compra MÃE E FILHA, terá que efetuar a compra de dois modelos desse mesmo anuncio. Podendo variar na numerações e cores distintas ou totalmente iguais! TABELA DE NUMERAÇÃO Nº Tam. Medida em centímetros Nº 28 ➝ 18,1 cm Nº 29 ➝ 18,7 cm Nº 30 ➝ 19,3 cm Nº 31 ➝ 19,9 cm Nº 32 ➝ 20,5 cm Nº 33 ➝ 22,1 cm Nº 34 ➝ 22,7 cm Nº 35 ➝ 23,5 cm Nº 36 ➝ 24,1 cm Nº 37 ➝ 24,8 cm Nº 38 ➝ 25,5 cm Nº 39 ➝ 26,2 cm Nº 40 ➝ 26,5cm ESPECIFICAÇÕES TÉCNICAS Indicado para: Dia a Dia Material: PVC Solado: PVC Recomendações de Uso: Indicado para dia a dia, passeios e viagens. Garantia do Fabricante: Contra defeitos de fabricação.', 69.9, 64.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lzag6sv2x8htd0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F741801874%2F20697786639', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259662247', 'Ração Úmida Whiskas Sachê Frango ao Molho para Gatos Adultos', 'Whiskas Sachê Frango ao Molho é uma ração úmida deliciosa e nutritiva, feita com ingredientes naturais de alta qualidade, vitaminas e minerais. Cozidos a vapor, os pedacinhos de frango são irresistíveis para seu gato! * Refeição completa e balanceada para gatos adultos. * Ajuda a manter a saúde do trato urinário. * Sem conservantes, corantes ou aromatizantes artificiais. Guia alimentar: sirva 3 sachês por dia para gatos adultos de 4kg. Cada sachê de Whiskas equivale a 1/4 de xícara de Whiskas seco (1 xícara = 200ml).', 3.79, 3.79, NULL, 'Pets > Others', 'https://cf.shopee.com.br/file/sg-11134201-82633-mj72mdl2nw1u89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554850%2F58259662247', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
