INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23791577124', 'Sabonete Íntimo Bloqueador de Odor OAZ - 300 ml', 'Sabonete Íntimo Bloqueador de Odor OAZ - 300 ml Com o sabonete íntimo bloqueador de odor da OAZ você mantém sua região íntima protegida e livre de cheiros indesejáveis. Além disso, sua fórmula vegana não contém adição de parabenos e possui tecnologia anti-odor, promovendo mais conforto e confiança durante a correria de seu dia-a-dia. Sabonete Íntimo Bloqueador de Odor OAZ Possui a tecnologia Odor Control, que neutraliza possíveis odores e ativa as defesas naturais da região íntima, trazendo sensação de proteção, frescor e aroma agradável. Sua fórmula hipoalergênica conta também com Ácido Lático e Prebióticos, que limpam suavemente a região íntima sem agredir a flora e regulam o pH vaginal. Ginecologicamente testado. Diferenciais: Reforça as defesas naturais Limpa suavemente Bloqueia odores indesejados Modo de uso: Aplicar o sabonete em uma pequena porção na palma de sua mão e lavar durante o banho na região genital externa, previamente umedecida. Espalhar até obter espuma. Em seguida, enxaguar abundantemente. Restrição de Uso: Em caso de irritação interrompa o uso e consulte seu médico. Mantenha-o fora do alcance de crianças. Aplicar somente nos órgãos genitais externos. Não use caso tenha hipersensibilidade aos componentes da fórmula. Evite contato com os olhos, caso isso ocorra, enxágue abundantemente. O uso excessivo de sabonete na região íntima pode ser uma fonte de irritação genital. Conservar em temperatura ambiente. Proteger da luz. Especificações: Código interno: 400009209 Ean: 7891317024376 Volume: 300ml Importante: * Produtos de decoração não inclusos. Imagens meramente ilustrativas; * As cores dos objetos podem sofrer alterações devido a luminosidade, configurações do monitor e até mesmo a percepção do usuário; * Os dados divulgados são de responsabilidade do fabricante/fornecedor.', 39.99, 39.99, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-7qvef-li9246vlq2h9c1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341217898%2F23791577124', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21899251460', 'Pneu Barum by Continental Aro 16 Bravuris AT 235/70R16 106T', 'Marca: BARUM Modelo: BRAVURIS AT Medida: 235/70R16 Largura: 235 Perfil: 70 Tamanho de Aro: 16 Índice de peso: 106 - 950 kg, 106 Índice de velocidade: T - 190 km/h, T Tipo de Veiculo: SUV Tipo de terreno: AT RunFlat: Não Sidewall: BSW LETRAS PRETAS Extra Load: Não Desenho: Simétrico UTGQ: N/A Adesão à àgua: E Eficiência energética: F Ruído externo: 75 *Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. Sobre a marca Barum A marca Barum nascida na Europa a partir da união das marcas Checoslováquia Bata, Rubena e Mitas, a Barum iniciou sua produção em 1966, em Otrokovice, na República Checa. Em 1993, a marca passa a fazer parte do Grupo Continental e, em 2014, se torna conhecida mundialmente. Qualidade aliada à custo-benefício é a principal característica dos produtos da Barum.', 940.12, 940.12, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rdw6-lxlq23zu490fd6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F21899251460', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
