INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19498640215', 'BRAÉ Divine Shampoo e Cond 250ml + Mascara 200ml e Leave-in', 'Kit BRAÉ Divine Shampoo, Condicionador, Mascara Capilar e Leave-in Divine Ten in One O Kit Contém: 01- Shampoo BRAÉ Divine - 250ml; 01- Condicionador BRAÉ Divine - 250ml; 01- Mascara Capilar BRAÉ Divine – 200ml 01- Leave-in Ten in One BRAÉ Divine - 200g Sobre o produto: Shampoo Divine: deixa os fios mais alinhados e disciplinados durante a limpeza. Condicionador Divine: traz um cuidado hidratante que desembaraça e disciplina os fios rebeldes. Máscara Divine: restaura profundamente a fibra capilar e recupera a força e a maleabilidade dos fios sem pesar. Leave-in Ten in One Divine: apresenta 10 (dez) poderes de reparação em um único produto, proporciona hidratação, resistência, proteção térmica e UV, combate o frizz e a Modo de usar: Aplique o Shampoo BRAÉ Divine nos cabelos molhados e massageie o couro cabeludo até formar espuma. Enxágue. Repita o procedimento se necessário. Após lavagem com Shampoo BRAÉ Divine, aplique a Máscara de Hidratação Braé Divine mecha a mecha, começando pelas pontas, massageando suavemente até chegar à raiz. Deixe agir de 10 a 15 minutos e enxágue. Espalhe o condicionador sobre os fios úmidos depois de usar o shampoo. Comece pelas pontas, massageie suavemente e deslize os fios entre os dedos até que estejam desembaraçados. Deixe agir por alguns minutos e enxágue. Aplique o leave-in diretamente no comprimento até as pontas do cabelo seco ou úmido. Não necessita de enxágue. Finalize como desejar. Resultado Cabelo, desembaraçado e disciplinado, livre do frizz e saudável. Cuidados/Restrições Sempre prefira utilizar uma espátula para retirar o produto de dentro do pote, para garantir a proteção e eficiência do produto. Evite o contato com os olhos. Caso isso aconteça, enxágue com água em abundância. Havendo irritação, suspender o uso e procurar orientação médica. Não ingerir. Manter fora do alcance de crianças. Uso externo.', 725.73, 352.05, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7qve4-lhtgelt20i0908', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F361729924%2F19498640215', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
