INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42914213765', 'Bomba Para Graxa 4 Kg Manual 6432 Bremen', 'Descrição do Produto Facilite a Lubrificação com a Bomba Manual para Graxa com Alavanca 4Kg! Projetada para oferecer praticidade e eficiência, esta bomba manual é a solução ideal para aplicação de graxa em uma variedade de equipamentos e máquinas. Com capacidade para 4kg de graxa, garante um fluxo suave e controlado, proporcionando uma lubrificação precisa e uniforme. Sua alavanca ergonômica oferece conforto durante o uso, tornando-o ideal para trabalhos prolongados. Seja para uso profissional em oficinas mecânicas, indústrias ou para tarefas de manutenção em casa, esta bomba é uma ferramenta essencial. Simplifique sua rotina de lubrificação hoje mesmo com esta bomba manual de qualidade! Características: • Utilizada em serviços de lubrificação, tais como oficinas e pequenas industrias. Especificações Técnicas: • Capacidade: 4 kg • Fabricada em chapa de aço • Mangueira: 1/4” Conteúdo da Embalagem: • 1 Bomba Manual • 1 Válvula anti-retorno • 1 Disco seguidor • 1 Extensão rígida • 1 Acoplador • 1 Mangueira 1/4” Garantia: • 6 Meses. Já incluso 3 Meses Legais. Código de Barras: • 7899735005762 Ref.: BREMEN-6432 Marca.: BREMEN *Imagens meramente ilustrativas *Todas as informações divulgadas são de responsabilidade do Fabricante/Fornecedor', 224.9, 181.45, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Others', 'https://cf.shopee.com.br/file/sg-11134201-81zui-midax5dfuhood9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F844004880%2F42914213765', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26832914573', 'Inoar Kit Hyaluronic Force Sh 500ml + Cond 500ml', 'Inoar Kit Hyaluronic Force Sh 500ml + Condicionador 500ml O kit Inoar hyaluronic force foi elaborado com ativos de alta performance que preenchem todas as camadas dos cabelos fortalecendo e reconstruindo a fibra capilar. O Ácido hialurônico penetra no fio e tem uma e tem uma capacidade excelente de reter água, tornado o cabelo mais hidratado por muito mais tempo. Os danos são reparados instantaneamente. Resultados visíveis já na primeira aplicação: Cabelos saudáveis, macios maleáveis e com brilho incrível. Contém: 1-Inoar Hyaluronic Force Shampoo 500ml 2-Inoar Hyaluronic Force Condicionador 500ml', 57.82, 52.04, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7reob-m8ev961wlzmq13', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290896931%2F26832914573', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
