INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397557004', 'Intimus Absorvente Gel Tripla Proteção Suave Com Abas De 32 Unidades', 'Intimus Gel Tripla Proteção Suave com Abas 32 Unidades: Absorção Rápida e Conforto O Absorvente Intimus Gel Tripla Proteção Suave com Abas em pacote econômico com 32 unidades é projetado para oferecer proteção completa, conforto e segurança para dias de fluxo moderado a intenso. Sua tecnologia Tripla Proteção garante absorção rápida, barreiras antivazamento e controle de odor. Com cobertura suave, ele é delicado para a pele íntima, minimizando irritações. O gel absorvente transforma o líquido em gel, mantendo a sensação de seco. As abas fixam o absorvente de forma segura. O pacote com 32 unidades econômico para uso contínuo. Tripla Proteção e Conforto: Tripla Proteção: Absorção, Antivazamento e Controle de Odor.Cobertura Suave: Conforto e delicadeza para peles sensíveis. Com Abas: Fixação segura e proteção lateral. 32 Unidades: Embalagem econômica para uso mensal. Troque o absorvente a cada 4 horas ou sempre que sentir necessidade. Descarte em lixeira. A proteção completa que te dá segurança e conforto com suavidade.', 41.69, 41.69, NULL, 'Health > Personal Care > Feminine Care', 'https://cf.shopee.com.br/file/sg-11134201-8262g-ml5jvoktc9hfe8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251200960%2F22397557004', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
