INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22597733333', 'Kit 2 Pilhas Recarregável AAA Palito + Carregador Avant Use', 'Kit Carregador e Pilhas Recarregáveis AAA Avant Use (2 Pilhas - 1000 mAh) O Kit Carregador e Pilhas Recarregáveis AAA Avant Use é a solução completa e prática para seus dispositivos que exigem energia de alta performance e durabilidade. O kit inclui: 2 Pilhas Recarregáveis AAA de 1000 mAh: Oferecem maior autonomia para seus dispositivos, com alta capacidade e desempenho. Carregador de Pilhas com Cabo USB: Permite carregar as pilhas de forma rápida e eficiente, com design moderno e prático. Características: Alta capacidade: As pilhas recarregáveis de 1000 mAh garantem maior autonomia para seus dispositivos. Recarregável: Reduz o impacto ambiental e economiza dinheiro a longo prazo, pois pode ser recarregada diversas vezes. Versatilidade: Perfeita para uma variedade de dispositivos como controles remotos, relógios, brinquedos, lanternas, câmeras digitais, e muito mais. Segurança: Produzidas com rigorosos padrões de segurança, garantindo o uso seguro e confiável. Embalagem prática: O kit inclui tudo que você precisa para começar a usar suas pilhas recarregáveis. Especificações: Modelo: 1 carregador + 2 Pilhas AAA Tensão nominal: 1.2V Tipo: Pilhas recarregáveis Ni-MH Conteúdo: 1 carregador e 2 pilhas Código de Barras: 7899452038319 Garantia: 12 meses para defeitos de fabricação. Sobre a Avant Use: A Avant Use é uma marca reconhecida pela qualidade e inovação em seus produtos. Com foco em oferecer soluções eficientes e duráveis, a Avant Use se destaca no mercado por oferecer produtos que atendem às necessidades do dia a dia, sempre com a segurança e confiabilidade que você precisa.', 129.9, 39.99, NULL, 'Home Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-82600-mkdigh8rdurq8d', 'https:/