INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58211075641', 'Chinelo Infantil Rider Core NBA', 'O Chinelo de Dedo Infantil Core NBA Rider traz um visual versátil e moderno, ideal para o dia a dia das crianças. Com base confortável e prática, é perfeito para acompanhar diferentes momentos com leveza e estilo. O destaque fica por conta da grafia em bloco de cor na palmilha, inspirada nos principais times da NBA, além da versão institucional da liga. Um modelo que combina o universo do basquete com o DNA urbano da Rider, garantindo conforto e personalidade para os pequenos fãs do esporte. *Pedidos realizados através de CNPJ não serão faturados.', 39.99, 39.99, NULL, 'Baby & Kids Fashion > Boy Shoes > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-823qs-moh98qpt30uj6f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1012616199%2F58211075641', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
