INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46608587995', 'Combo Kits 2 Camisa Masculina Ciclismo Premium Manga Curta Ziper Total Elite Pedal Bike', 'Camisa de Ciclismo Masculina: Destaques do produto: Fita refletiva traseira para mais segurança em pedais com baixa luminosidade. Zíper invisível total que traz praticidade e um visual mais clean. Bolsos traseiros para carregar itens essenciais com facilidade. Corte anatômico que se ajusta melhor ao corpo e favorece a mobilidade. Punho com elástico para mais firmeza e conforto. Barra reforçada para melhor ajuste e maior durabilidade. Mais benefícios para o seu pedal: Tecido esportivo que ajuda a manter o corpo seco e a temperatura equilibrada. Proteção UV, com tratamento antibacteriano e anti microbiano. Produzida em poliéster sublimado de alta qualidade, com excelente resistência e cores duradouras. Sobre a Loja Para Ciclistas: • Especialistas em artigos para ciclismo. • Produtos de qualidade e pronta entrega. • Atendimento de segunda a quinta, das 8h às 18h e sexta das 8h às 17h. LOJA PARA CICLISTAS – O que faltava para o seu pedal está aqui!', 159.9, 119.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > T-shirts', 'https://cf.shopee.com.br/file/br-11134207-820l5-mogxwu1uvshx1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F379576060%2F46608587995', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9841538039', 'Calça Ciclismo Masculino Forro De Gel Bolsos Preta Roupa Bicicleta Inverno Conforto Bike Pedal Mtb', 'Calça de Ciclismo Masculina com Forro em Gel - Conforto, Proteção e Performance para Seus Pedais! Principais Características: • Corte Anatômico Masculino: Ajuste perfeito ao corpo, proporcionando conforto e liberdade de movimento. • Tecido de Compressão: Elasticidade ideal para um caimento confortável e ajuste seguro. • Forro em Gel Densidade 100: Proteção contra impactos, reduzindo dores e desconfortos durante pedaladas curtas, médias ou longas. • Rápida Evaporação do Suor: Mantém a pele ventilada e seca, garantindo maior conforto térmico. • Proteção UV: Segurança extra contra os raios solares. • Costuras Reforçadas: Maior durabilidade e resistência ao uso contínuo. • Ideal para: Mountain Biking, Ciclismo de Estrada e Cicloturismo. Sobre a Loja Para Ciclistas: • Especialistas em artigos para ciclismo. • Produtos de qualidade e pronta entrega. • Atendimento de segunda a quinta, das 8h às 18h e as sextas das 8h às 17h. LOJA PARA CICLISTAS – O que faltava para o seu pedal está aqui!', 129.9, 79.89, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Bottoms', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lvn8w8i9hbfwa3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F379576060%2F9841538039', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
