INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22796564111', 'Torre Didática Com Bolinha Chocalho Educativo Pedagógico Bebe Criança Colorido', 'Estimule o desenvolvimento dos sentidos do seu bebê com o Conjunto Torre e Bola com Chocalho! Perfeito para bebês em fase de crescimento, este brinquedo oferece uma experiência divertida e educativa ao mesmo tempo. Destaques do Produto: Estimulação sensorial: O chocalho interno produz sons agradáveis ao ser agitado, promovendo o desenvolvimento auditivo e a coordenação motora. Design colorido e atrativo: As cores vibrantes capturam a atenção do bebê, tornando a brincadeira ainda mais envolvente. Fácil de segurar: Projetado para mãos pequenas, oferece conforto e segurança durante o manuseio. Material seguro e durável: Feito com polipropileno resistente, garantindo segurança e longa durabilidade. Portátil e leve: Ideal para brincadeiras em casa ou durante passeios, garantindo diversão em qualquer lugar. Especificações: Material: Polipropileno. Dimensões: Torre: 11 cm (largura) x 11 cm (altura). Bola: 15,5 cm (diâmetro). Peso: Torre: 75 g. Bola: 60 g. Idade Recomendada: A partir de 12 meses. Conteúdo da Embalagem: 01 Torre com Chocalho. 01 Bola com Chocalho. Certificação: Registro INMETRO: 000122/2022. Proporcione momentos de aprendizado e diversão com este brinquedo educativo que ajuda no desenvolvimento sensorial e motor do seu bebê!', 31.99, 27.97, NULL, 'Mom & Baby > Toys > Baby & Toddler Toys', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m62mxpzidaite3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F22796564111', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
