INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13543547957', 'Farol Punto 2008 2009 2010 2011 2012', 'Código do Produto: 75175 O farol é uma peça essencial para sinalização e visibilidade em vias noturnas e para maior segurança eles devem estar sempre em bom estado. E aqui temos o produto ideal para você. Este item possui material de alta qualidade e resistência, composto com sua lente em acrílico lisa, encaixe da lâmpada H4 que suporta até 55W e um design que deixa seu carro com aspecto diferenciado de todos os outros. Compatível com: Fiat - Punto 2008 - Punto 2009 - Punto 2010 - Punto 2011 - Punto 2012 Especificações Técnicas: - Máscara Cromada - Foco Simples - Regulagem Manual - Encaixe da Lâmpada H4 - Lente Lisa - Material da Lente em Acrílico - Material da Carcaça em Plástico - Suporta Lâmpadas de até 55W ATENÇÃO Garantia - 3 Meses O valor anunciado é referente a unidade. A Empresa não se responsabiliza pela má instalação do produto. Procure por um profissional especializado!', 372.25, 372.25, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/b9673b6cc28608e3e1359e86e3f030a4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F469347212%2F13543547957', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
