INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19298189957', 'Cubo Roda Traseiro S/ Rolamento Kombi 1.4 1.6 (1976 - 2012) 48mm - IR17105', 'Especificações Técnicas: • Marca: IRB Automotive • Cód. da montadora: 2115016191CRT • Posição: Traseira • Furo do rolamento: 48 mm • Furos: 5x112,35 • Estrias: 12 • Inclui rolamento: Não • Cód. de similares: ALB70-453 / CRC01010 / FWB0525 / HFCT 03 / AL-845 / NKF 8029 Aplicações: - Volkswagen Kombi 1.4 / 1.6 (1976 – 2012) O Cubo de Roda IRB é fabricado em aço forjado, o que significa alta capacidade de suportar cargas pesadas em condições ambientais diversificadas. E desenvolvidos para ter uma ótima performance em qualquer território nacional! IRB é uma marca brasileira que fornece peças automotivas voltada ao segmento de reposição para todo Brasil. Atendendo frotas de veículos nacionais e importados! A IRB projeta cubos garantindo: - Uma instalação fácil e precisa; - Maior resistência; - Melhor integridade estrutural. Não esqueça de verificar a motorização, ano, modelo e o furo do rolamento! Na dúvida mande mensagem para verificarmos a aplicação do produto para você. Evite erros na compra!', 134.9, 124.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mao7cjlythq1cf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1497249598%2F19298189957', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
