INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20699759773', 'Super Tweeter Selenium Jbl St200 Ghost 100w Transparente 8 Ohms Original', 'PRODUTO À PRONTA ENTREGA, COMPRA SEGURA COM ENVIO IMEDIATO, NOTA FISCAL E GARANTIA! O JBL ST200 Ghost é a escolha perfeita para quem busca alta performance em altas frequências, com a credibilidade da marca JBL e um visual moderno e arrojado que valoriza qualquer sistema de som automotivo ou profissional. Diferenciais do Produto: - Alta Potência: 100W RMS com excelente eficiência e definição nas altas frequências; - Som Cristalino: ideal para reforçar agudos em sistemas automotivos, trios elétricos, caixas acústicas e sonorização profissional; - Design Exclusivo Ghost: estrutura transparente que destaca o visual do seu sistema de som. - Durabilidade: materiais de alta qualidade, resistência e desempenho superior. - Instalação Facilitada: fiação acessível e estrutura que se adapta facilmente a projetos diversos. Especificações Técnicas: - Impedância 8 Ohms; - Resposta de frequência 2.000 a 20.000Hz; - Sensibilidade: W 1 M:105 dB SPL - Potência RMS: 100W (com uso de crossover); - Potência RMS: 70W; - Diâmetro da Bobina: 46 mm; - Material do ímã: Ferrite de bário; - Peso do ímã: 220 g; - Material da tampa: Policarbonato; - Material do fio da bobina: Cobre; - Material da forma da bobina: Poliimida; - Volume ocupado pelo transdutor: 0,5 L ( 0,018 pés cúbicos). Conteúdo da Embalagem: - 01 Super Tweeter 200 Ghost; - 01 Certificado de garantia e Manual. Importante: - Garantia de 1 Ano; - Valor Unitário; - Imagens Meramente Ilustrativas; - A Subgrave recomenda que a instalação seja feita por profissional especializado, não nos responsabilizamos pelo mau uso do produto.', 141.89, 141.89, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mabpoyf7i3jt18', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F414508631%2F20699759773', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
