INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12220011599', 'Kit Livro - 365 Atividades com Unicórnios+Barbie', 'O Kit contém 2 livros: 365 atividades com unicórnios Os lindos fantásticos unicórnios esperam por você para este momento mágico! Encante-se com 365 atividades e desenhos para colorir do mundo da fantasia! Editora: Ciranda Cultural Edição: 1, 2018 Autor: Ciranda Cultural Idioma: Português Páginas: 288 Dimensões: L 15.50 x A 23.00 x E 1.30 ISBN: 9788538089797 A história fantática daBarbie - Dia de praia Barbie e suas amigas decidiram passar o dia na água, deram muitas risadas e, claro, conversaram sobre todas as novidade. Venha descobrir um pouco mais sobre o dia dessas amigas. Editora: Ciranda Cultural Edição: 1, 2020 Autor: Ciranda Cultural Idioma: Português Páginas: 10 Dimensões: L 17.00 x A 19.00 x E 0.50 ISBN: 9786555000283', 39.8, 19.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/2b8d307eea18e861d202bb6cf5247917', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F12220011599', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41018378924', 'Livro Na cena do crime - por trás da fita amarela', 'A verdade nem sempre aparece à primeira vista. Mas os vestígios falam. E o perito sabe escutá-los. Com décadas de atuação no Departamento de Homicídios e de Proteção à Pessoa (DHPP), Ricardo Salada nos conduz por dentro das cenas de crime mais complexas do país. Em "Na cena do crime: Por trás da fita amarela", ele revela como nascem os laudos que sustentam investigações, expõe falhas recorrentes na preservação de provas e compartilha lições aprendidas em campo entre sangue, silêncio e contradições. Um retrato honesto da perícia criminal brasileira, escrito por quem viveu tudo de muito perto. Editora: Principis Edição: 1, 2025 Autor: Ricardo Salada Idioma: Português Páginas: 224 Dimensões: L 15.50 x A 22.50 x E 1.20 ISBN: 9786550972899 Coleção: Não se aplica Linha Editorial: Principis - Autores contemporâneos Faixa Etária: + 18 anos Assuntos (tags): Não ficção, Crime, Perícia, Investigação, Brasil, Bastidores, True crime, Crimes reais, Ciência forense, Baseado em fatos reais, Assassinato, Policial, Justiça, Julgamento, Criminosos, Perícia criminal, Criminologia, Polícia, Perito, Psicopata, Crimes famosos, Crimes históricos, Investigação forense, Morte, Documentário, Casos reais, Cenas de crime BISAC: Crimes Reais / Crimes Reais / Forense Linha de Produto: Principis Encadernação: Brochura Acabamento: Laminação fosca e verniz localizado Material: Papel', 39.9, 39.9, NULL, 'Books & Magazines > Books > Adult''s Books', 'https://cf.shopee.com.br/file/sg-11134201-824h5-meh1trorqbk6e6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F41018378924', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
