INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21899829055', 'Hills I/d Digestive Care Lowfat Cães 3,85kg', 'Hill’s Science Diet: formulada para pets saudáveis, com opções específicas para filhotes, adultos e idosos. Os alimentos são feitos com ingredientes naturais e de fácil digestão, com foco em saúde cardíaca, renal, pele e pelagem. Hill’s Prescription Diet: indicada por veterinários para auxiliar no tratamento de condições específicas, como problemas renais, digestivos, urinários, obesidade e alergias alimentares. Cada fórmula é desenvolvida com base em diagnósticos clínicos.', 409.87, 327.9, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbfjvmap5apk0f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F438604073%2F21899829055', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
