INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41368270177', 'Blusa UV Termica Infantil Menina Proteção Solar Moda Praia Feminina Verão Escolha Sua Cor Preferida l06', 'Camiseta Térmica Infantil Moda Praia Para Meninas – Poliflex Proteção, leveza e liberdade para brincar no sol! Você escolhe o tamanho e a quantidade: Camisetas UV, ideais para usar no verão, na praia, na piscina ou em dias quentes ao ar livre. As camisetas são confeccionadas em Poliflex leve e elástico, garantindo mais conforto, proteção e durabilidade — sem pesar no corpo da criança. - Composição do Produto Malha Poliflex Leve, elástica e de secagem rápida Ideal para moda praia e atividades ao sol Modelagem térmica com manga longa - O que você vai receber Todas as peças são enviadas de forma sortida, com cores variadas. - Tabela de Medidas – Camiseta Térmica Tam 2 – Busto 26 cm | Comprimento 37 cm Tam 3 – Busto 27 cm | Comprimento 39 cm Tam 4 – Busto 30 cm | Comprimento 45 cm Tam 6 – Busto 32 cm | Comprimento 47 cm Tam 8 – Busto 34 cm | Comprimento 48 cm Tam 10 – Busto 36 cm | Comprimento 53 cm As medidas podem variar até 2 cm conforme o processo de confecção. - Vantagens das Camisetas Térmicas Poliflex -Tecido confortável, que acompanha os movimentos da criança -Ótima opção para brincar no sol com leveza -Proteção e secagem rápida para o verão -Pode ser usada também como segunda pele no frio -Excelente custo-benefício nos kits com mais unidades - FAQ – Perguntas Frequentes As camisetas protegem do sol? Sim. O tecido Poliflex é ideal para exposição ao sol, com toque leve e cobertura eficiente. As peças são térmicas ou apenas moda praia? São camisetas térmicas com composição Poliflex, que funcionam bem em climas quentes ou como segunda pele em temperaturas amenas.', 40.0, 24.9, NULL, 'Baby & Kids Fashion > Girl Clothes > Swimwear', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mi08mpf1105d0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341167297%2F41368270177', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23799149912', 'Simulador de Caminhada 110kg com Display', 'Simulador de Caminhada com Display TANDER TSDC 110 kg Leve seu cardio para qualquer ambiente com o Simulador de Caminhada TANDER TSDC. Compacto, dobrável e portátil (com rodas de transporte), ele reproduz o movimento natural da caminhada — ideal para uso residencial ou academias que buscam uma opção de baixo impacto para queima de calorias, fortalecimento de pernas e glúteos e melhora do condicionamento. O display eletrônico mostra tempo, passos, calorias, velocidade, distância e total percorrido, ajudando você a acompanhar a evolução. Com ajuste de resistência mecânico e estrutura em aço com componentes reforçados, o TSDC suporta até 110 kg, oferecendo praticidade, conforto e segurança no dia a dia. Benefícios Baixo impacto: protege as articulações enquanto melhora resistência e condicionamento. Portátil e prático: dobrável + rodas = fácil de guardar e transportar. Ajuste de intensidade: resistência mecânica para adequar o esforço ao seu ritmo. Monitoramento completo: display com tempo, passos, calorias, velocidade, distância e total.', 562.8, 562.8, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-821fo-mgmiceo4zg200b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F427153374%2F23799149912', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197346886', 'Farol Dianteiro Hilux SR SRV 2012 2013 2014 2015 Máscara Cromada Foco Simples Lente Lisa Acrilico', 'Farol Dianteiro Toyota Hilux SR SRV 2012 2013 2014 2015 Máscara Cromada Características: Produto novo de ótima qualidade; Feito sob medida, encaixe perfeito; Não acompanha lâmpadas e soquetes. Especificações técnicas: Foco simples; Máscara cromada; Cor da carcaça: preto; Encaixe de lâmpada H4; Regulagem de foco manual; Lente lisa em acrílico resistente; Suporta lâmpadas até 55 watts. Compatível com os modelos: Hilux SR SRV 2012 a 2015. Códigos originais: 81130 0K450; 81170 0K450. Garantia: 90 dias. Dica: Dê um novo visual para o seu carro, aqui você encontra os melhores produtos com os melhores preços. Importante: NÃO somos responsáveis pela má instalação ou mau uso do produto, para evitar transtornos procure por um profissional especializado.', 372.22, 372.22, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ls38t8ifk36s32', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1147747289%2F22197346886', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19098274523', 'Leave-in C.Kamura Intense One Curls Ondulados 2ABC 200g', 'Leave-in C.Kamura Intense One Curls Ondulados 2ABC 200g Leave-in desenvolvido especialmente para cabelos ondulados (tipos 2ABC), que hidrata, define e controla o frizz sem pesar. Sua fórmula leve preserva a estrutura natural dos fios, proporcionando movimento, maciez e brilho aos cachos. Modo de Usar Com os cabelos limpos e úmidos, aplique o leave-in do comprimento às pontas. Distribua uniformemente e finalize como desejar. Pode ser usado diariamente para manter os cachos definidos e hidratados. Resultado Cabelos ondulados definidos, hidratados, com frizz controlado, brilho natural e toque suave. Conheça a Marca C.Kamura é a marca profissional criada pelo renomado hairstylist Celso Kamura. Com tecnologia de ponta e alta performance, seus produtos entregam resultados de salão no cuidado diário dos cabelos.', 69.99, 59.49, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-82595-mg816tcha9l4b8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577811878%2F19098274523', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259672241', 'Lagunitas IPA Cerveja Long Neck', 'A Lagunitas IPA é uma cerveja American Indian Pale Ale (IPA) que nasceu em 1995 na Califórnia. Uma versão única de um estilo antigo, preservando o aroma e amargor dos lúpulos cítricos e florais americanos. Perfeita para harmonizar com hambúrguer, carnes gordurosas, churrasco, comida mexicana, queijo roquefort, gorgonzola e gouda. Além de saborosa, a Lagunitas apoia ONGs que cuidam de cachorros de rua e músicos independentes.', 12.99, 12.99, NULL, 'Food & Beverages > Alcoholic Beverages > Beer & Cider', 'https://cf.shopee.com.br/file/sg-11134201-825zo-mj72osdxpkaqee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555006%2F58259672241', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254083809', 'Eudora La Piel Booster Biocolágeno Sérum Concentrado 25ml', 'O Sérum Concentrado Corporal La Piel Booster de Biocolágeno é um poderoso tratamento firmador indicado para a área do pescoço, colo e mãos. Produzido com uma combinação de Biocolágeno, Niacinamida e Pantenol, atua para hidratar, melhorar a firmeza e a elasticidade da pele em 14 dias de uso. Sua fórmula contém 10x mais Biocolágeno e Pantenol e sua formulação é leve, sendo rapidamente absorvida pela pele. Além disso, seu uso combinado com qualquer hidratante desodorante da linha La Piel ajuda você a obter resultados ainda melhores. Dermatologicamente testado Vegano Livre de sulfato, parabenos, petrolatos e óleo mineral Embalagem com 10% de plástico reciclado Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free. Confira toda a linha La Piel que vai transformar - e revolucionar - a sua pele. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 57.9, 57.9, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-8260e-mjymfctyzx1cfd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F58254083809', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258810275', 'Sala de Jantar 220x110 Stone 8 Cadeiras Yara Terra Cota Bom Pastor', 'Sala de Jantar 220x110 Stone MDF/Vidro 8 Cad. Bom Pastor A Sala de Jantar Stone 220x110 MDF/Vidro com 8 Cadeiras Yara Bom Pastor é perfeita para quem deseja um ambiente imponente, moderno e sofisticado. A mesa mede 2,20 x 1,10 m, oferecendo muito espaço para acomodar família e convidados com conforto. Sua base possui acabamento em BP, material superdurável contra riscos e manchas, e conta com a tecnologia Protekto Plus, que protege contra bactérias e bolor, mantendo os móveis mais higiênicos, sem manchas, sem odores indesejados e com durabilidade prolongada. Essa proteção é incorporada diretamente ao painel durante a fabricação, garantindo eficiência por toda a vida útil do produto. O tampo em vidro traz elegância ao ambiente e facilita a limpeza do dia a dia, unindo beleza e praticidade. O conjunto conta com a exclusive cadeira Yara. Produto direto da fábrica, com qualidade Bom Pastor para compor sua sala de jantar com muito estilo. Medidas Mesa: Altura 80 cm / Largura: 1,10 m / Comprimento: 2,20 m Cadeira: Altura 95 cm / Largura: 51 cm / Comprimento: 60 cm Observação: o vidro é enviado colado no tampo para facilitar a montagem Peso suportado pela cadeira: Até 120Kg Observações importantes: A Loja Bom Pastor não faz montagem de produtos. Todos os produtos acompanham manual de montagem. A montagem é de exclusiva responsabilidade do adquirente. É imprescindível a contratação de um montador profissional para montar o produto. Não nos responsabilizamos por danos de quaisquer naturezas causados no produto pela montagem. Produtos podem apresentar diferenças de tonalidades entre a foto na tela e o produto real, devido a calibração de cor da tela. Os objetos decorativos que ambientam as fotos não são vendidos e não acompanham o produto. Favor confira se todos os volumes que constam na nota, foram descarregados. E verifique se as embalagens estão em boas condições no momento da entrega. A Loja Bom Pastor e o serviço de transporte não se responsabilizam por produtos que precisem subir escadas, ou serem içados para algum andar superior e não realizam tais serviços e este serviço fica a cargo do cliente. Verifique as dimensões do produto antes de finalizar a compra. Certifique-se que o produto passa por escadas, vãos, portas ou janelas antes de finalizar a compra.', 2599.0, 2399.0, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-8262q-mmc7xhw6vj0ide', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1563516628%2F58258810275', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393048977', 'Rack para TV Até 75 Polegadas 2 Gavetas 220cm Industrial Freijó/Preto - Dalla Costa', 'Descrição: Com design moderno e atemporal, o Rack Curvo F43 combina cortes e formas para remeter ao estilo industrial. Esse produto 100% MDF possui 2 gavetas com puxadores plásticos e corrediças metálicas, que conferem uma maior resistência à peça. Espaçoso e versátil, esse rack tem design industrial feito com ripas 100% MDF, fixadas com ferragens de alta resistência. Com pintura de 6 camadas de proteção, a alta qualidade do acabamento faz com que esse produto da Dalla Costa se destaque em qualquer espaço. Características: - Tipo do Móvel: Rack - Garantia (dias): 180 - Sistema de Montagem: Parafusos, cavilhas e Minifix. - Grau de Dificuldade da Montagem: Médio - Como os Móveis Chegarão na Minha Casa: Desmontado em caixas, acompanhado de todas as peças, ferragens e manuais para montagem. - Indicação de Uso: Sala de Estar - Observação: Objetos decorativos que aparecem nas imagens, não acompanham o produto. - Recomendação de Manutenção: Para conservar a cor e os aspectos originais do produto, leve em consideração: Levantar a peça ao deslocá-la, o que ajuda a evitar danos à base e aos pés; Não utilizar água em abundância na peça, somente um pano levemente umedecido para a limpeza ou um espanador seco; Utilizar panos preferencialmente brancos, para evitar manchas e seque bem o móvel após a limpeza; Utilize somente água, nunca produtos químicos, abrasivos, solventes, ceras, sabonetes não neutros ou produtos de limpeza doméstica, visto que podem danificar o acabamento; Não coloque objetos quentes diretamente em cima do móvel para não causar bolhas, manchas ou outros danos, opte por utilizar um apoio; Se possível, não exponha sua peça diretamente ao sol, utilize cortinas ou persianas para bloquear os raios de luz, para que a pintura não desbote. Esses cuidados são muito simples e auxiliarão seu produto a permanecer em perfeito estado por muitos anos. - Revestimento /Acabamento: Pintura UV - Espessura da Estrutura: 3 mm, 12 mm, 6 mm, 15 mm, 24 mm, 25 mm - Quantidade de Gavetas: 2 - Ideal para TVs até: 75 Polegadas - Medidas do Painel (A x L x P): 0 x 0 x 0 cm - Peso Suportado no Tampo (kg): 25 kg - Tipo de Rack: Sem Painel - Tamanho: Grande - Peso Suportado nas Gavetas (kg): 5 - Material das Corrediças: Metálica - Tipo da Corrediça: Convencional - Quantidade de Prateleiras: 1 - Peso Suportado nas Prateleiras: 10 Kg - Material do Puxador: Plástico - Linha: Industrial - Material da Estrutura: MDF - Escala de brilho: Fosco - Tipo: Lojista e E-commerce - Quantidade de Pés: 3 - Material dos Pés: MDF - Necessita de Fixação na Parede?: Não - Possui Furação para Passagem de Cabos: Não - Possui Puxadores?: Sim - Pode Ser Montado Invertido?: Não - Possui Pés?: Sim - Possui Rodízios ?: Não - Necessita de Montagem: Sim - Possui Gavetas?: Sim - Acompanha LED: Não - Acompanha Suporte para TV: Não - Medidas do Rack (A x L x P): 60 x 220 x 35,5 cm - Possui Vidro?: Não - Possui Portas?: Não - Possui Espelho?: Não - Possui Prateleiras?: Sim', 682.49, 682.49, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/sg-11134201-7rd63-lvkh8jvsabvf41', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1226105437%2F22393048977', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20797673118', 'Palheta Gm Cobalt 2011 2012 2013 2014 2015 2015 2016 2017 18', 'Descrição JOGO DE PALHETA DIANTEIRA AEROFIT ORIGINAL BOSCH 01 - Palheta Bosch lado motorista 26" / 50CM 01 - Palheta Bosch lado passageiro 16" / 45CM APLICAÇÃO: - GM Cobalt 2011 - GM Cobalt 2012 - GM Cobalt 2013 - GM Cobalt 2014 - GM Cobalt 2015 - GM Cobalt 2016 - GM Cobalt 2017 - GM Cobalt 2018 - GM Cobalt 2019 - GM Cobalt 2020 ENCAIXE : GANCHO Garanta máxima eficiência e segurança em todas as condições de estrada com as palhetas Bosch Aerofit. Produto original Bosch com nota fiscal inclusa. Características: Encaixe Gancho para instalação fácil e segura. Maior durabilidade e eficiência comprovadas. Nova embalagem moderna. Tratamento de grafite para limpeza suave. Estrutura robusta para estabilidade em todas as situações. Recursos Destacados: Tecnologia de ponta e inovação para uso com conexões especiais. Borracha aprimorada com Power Protection Plus, garantindo uma limpeza suave e silenciosa. Lâmina de aço Evodium pré-tensionada, oferecendo uma adaptação perfeita ao para-brisa. Produto novo, com aplicação compatível com peças originais. Construção robusta projetada para um desempenho duradouro, independentemente das condições climáticas. Processo de instalação simples e rápido para sua conveniência. Substituição Recomendada: Observe sinais de problemas no para-brisa e nas palhetas. Dicas de manutenção incluídas para prolongar a vida útil das palhetas. Importante: Substitua as palhetas pelo menos uma vez por ano. Em caso de dúvidas sobre a compatibilidade do seu veículo, pergunte no campo de perguntas do anúncio. Garanta uma visão clara e eficiente em qualquer condição com as Palhetas Bosch Aerofit. Compre já!', 74.94, 74.94, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rd6i-lujdrod6ymmnc6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337450537%2F20797673118', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201834018', 'Eudora Creme Para Pentear Siàge Revela Os Cachos 500g', 'O Creme Para Pentear Siàge Revela Os Cachos é um tratamento ideal para cabelos cacheados:Ondulados, crespos e em transição. Possui fórmula inteligente que reconhece os pontos de torção do fio, fornecendo cachos maravilhosos! Fórmulas com Elastina, combinada à Manteiga de Karité, que garantem alta definição, força, elasticidade e 3X menos frizz. Este creme para pentear hidrata imediatamente e proporciona o máximo da definição para os cachos. Multibenefícios: -Cabelos fáceis de modelar; -Definição por até 2 dias; -Balanço natural; -Proteção térmica 230°C; -Frizz bloqueado até a próxima lavagem. O resultado são Cachos impecáveis, ultra hidratados e definidos até a última volta. Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 68.0, 59.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-822z5-mi53yafa2tjc90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F58201834018', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254072742', 'Eudora Instance Esfoliante Corporal Perfumado Frutas Vermelhas 180g', 'O Esfoliante Corporal Perfumado Instance Frutas Vermelhas é vegano e essencial para uma rotina completa de autocuidado, proporcionando uma esfoliação suave da pele. Com sementes de morango e extratos naturais, ele age delicadamente sem agredir a pele, renovando-a e proporcionando mais maciez. A fragrância frutal alegre e surpreendente, que une o dulçor das frutas vermelhas com notas cremosas de baunilha, torna o seu banho mais prazeroso. Conheça as características que farão você se apaixonar: Promove renovação suaveContém sementes de morango e extratos naturaisFórmula vegana que garante mais maciez Este item atende à necessidade de ter a pele esfoliada e renovada, deixando-a mais macia e perfumada para o dia a dia. Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 44.9, 44.9, NULL, 'Beauty > Skincare > Face Scrub & Peel', 'https://cf.shopee.com.br/file/sg-11134201-82606-mjyj1sdghpmse6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F58254072742', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894243194', 'Máquina De Lavar 10kg Britânia Semi Automática Blr03', 'Além de eficiente, a Máquina de Lavar 10kg Britânia BLR03 Semi Automática garante muita economia, pois possui baixo consumo de energia e alta eficiência de lavagem. Com 10 Kg de capacidade e dispenser duplo para sabão e amaciante, ela é ideal para todas as necessidades. A Máquina de Lavar 10kg Britânia BLR03 conta com incríveis 7 programas que possibilitam mais opções para cuidar das suas roupas. Programas para lavagem desde roupas até edredom, além de permitir escolher o programa em função do tipo da roupa e nível de sujeira. Além disso, ela possui filtragem de fiapos, desligamento automático e painel intuitivo, super fácil de usar! E não para por aí! A Máquina de Lavar 10kg Britânia BLR03 tem um agitador com design exclusivo que aumenta a eficiência e o poder de limpeza das suas roupas. É a praticidade e eficiência que você precisa no seu dia a dia. MODELO: BLR03 Capacidade de lavagem: 10kg Programas de operação: 7 para escolher o programa em função do tipo da roupa e nível de sujeira Função Timer: sim Tampa: Transparente Filtragem de fiapos: sim Dispenser: 2 compartimentos para sabão e amaciante Painel fácil de usar: sim Desligamento automático: sim Dimensões Do Produto: Altura: 95,5 cm Largura: 58 cm Profundidade: 51 cm Peso: 8,84 kg Garantia: 12 meses', 599.0, 549.0, NULL, 'Home Appliances > Large Household Appliances > Washing Machines & Dryers', 'https://cf.shopee.com.br/file/sg-11134201-7rdx1-mcgnsaqlstrr1e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1561901020%2F22894243194', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997829768', 'Sofá com Carregador USB e Molas no Assento Retrátil Reclinável Nice 2,10m Velosuede - NETSOFAS', 'Exclusividade com requinte NETSOFAS. Com um visual que vai levar sofisticação e aconchego para os ambientes da sua casa, o SOFÁ NICE COM MOLAS NO ASSENTO é uma peça digna de elogios em qualquer decoração. Internamente, ele possui madeira na estrutura, um ótimo material para o uso diário. Já por fora, o VELOSUEDE faz com que todo mundo tenha vontade de ficar nele sem hora para sair e deixa os momentos em frente à televisão ainda melhores. Ah, ele se transforma rapidamente com os assentos abertos adaptar-se à sua rotina e necessidades e ainda apresenta CARREGADOR USB para quando quiser ficar conectado às redes sociais. Muitos benefícios para um lar que merece ser igualmente incrível ;) Informações técnicas: Material da estrutura: Madeira Maciça de Eucalipto 100% de reflorestamento, produto ecologicamente correto. Enchimento do Assento: Espuma D-33 Soft, Percinta Elástica e Mola Bonnel. Enchimento do Encosto: Percinta Elástica, Flocos de Espuma e Fibra de Poliéster Siliconada. Fixação da Estrutura: Grampos galvanizados antiferrugem. Revestimento / Tecido: VELUDOCRISTAL. Chaise: Não Possui. Praticidade: Modelo Bipartido, facilidade para transportar até o local desejado. Medidas: Altura aproximada: 104cm (fechado) e 87cm (aberto). Largura aproximada: 210cm. Profundidade aproximada: 107cm (fechado), 165cm (aberto) Peso aproximado: 73kg. Necessita Montagem: Sim. Necessita Montador Especializado: Não. A montagem do produto pode ser feita facilmente seguindo o manual de instruções que acompanha a embalagem do produto. Não é necessário técnico especializado. Capacidade em KG por Lugar: Aproximadamente 150kg USB: Sofá com uma tomada contendo duas entradas USB para carregamento de eletrônicos, potência de 5V. Não incluso fonte de energia. Extensão do cabo da tomada pode variar de 70cm a 90cm. Garantia: 90 dias contra defeito de fabricação. *a contar da data do recebimento da mercadoria. Limpeza: Aspirar o Produto para eliminar a poeira, utilizar um pano levemente umedecido com água e sabão neutro, seguido de pano seco. Não limpar com escovas ou produtos abrasivos. Recomendações de Manutenção: Usar em local seco, não molhar. Evitar exposição ao sol, para que o produto não sofra alterações na cor. ATENÇÃO! A tonalidade do produto pode sofrer variações entre a imagem de exibição e o item físico. Imagens meramente ilustrativas. Não nos responsabilizamos pela montagem/instalação dos produtos. Os objetos que ambientam as fotos não acompanham o produto. Verifique as dimensões do produto e certifique-se que o percurso que ele fará até o local de uso permite sua passagem. Nós não nos responsabilizamos por transporte de produtos, caso não caibam em elevadores, acima de três lances de escada e não cabendo na passagem das escadas, por içamentos ou desmontagens de produtos. Quaisquer despesas deste tipo ficam a cargo do cliente. Reservamo-nos o direito de possíveis erros de digitação. Anúncio sujeito a alteração sem aviso prévio. Antes da entrega, nossos produtos passam por um rigoroso controle de qualidade para que cheguem até o cliente em perfeitas condições, entretanto, em casos de desacordo com o proposto, o comprador deverá contatar o nosso SAC e/ou a loja aonde a compra foi efetuada. Sofá com USB. Tomada com duas entradas USB, extensão do cabo é de 70cm a 90cm podendo sofrer variação, dependendo do modelo. O prazo para solucionar os problemas identificados é de até 30 dias úteis, contados a partir da data do posicionamento do SAC com o comprador.', 2290.29, 2290.29, NULL, 'Home & Living > Furniture > Sofas', 'https://cf.shopee.com.br/file/sg-11134201-7rfgy-m3dvyc1fc8h144', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F916172870%2F23997829768', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259461608', 'Macarrão Instantâneo Lámen Tomate Suave Turma da Mônica Nissin', 'O macarrão instantâneo Lámen Nissin sabor Tomate Suave da Turma da Mônica é prático, fica pronto em apenas 3 minutos e garante a diversão das crianças! * Modo de Preparo: Fogão: 1. Ferva 450ml de água. 2. Junte o macarrão e cozinhe por cerca de 3 minutos. 3. Retire do fogo, coloque o tempero do envelope e misture bem! Micro-ondas: 1. Coloque 450ml de água e o macarrão em um recipiente próprio para micro-ondas. 2. Cozinhe em potência alta por 5 minutos, parando na metade do tempo para mexer. 3. Retire do micro-ondas, misture o tempero e sirva! A Nissin Foods do Brasil é líder no segmento de macarrão instantâneo e investe sempre em boas práticas para satisfazer as necessidades de seus consumidores.', 3.49, 3.49, NULL, 'Food & Beverages > Convenience / Ready-to-eat > Instant Noodles', 'https://cf.shopee.com.br/file/sg-11134201-8259f-mqnellw0i68eb0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555142%2F58259461608', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259227237', 'Bota Coturno Tatico Lightness Confort Black 8627-1 - Airstep', 'A Bota Lightness Confort 8627-1 Black da Airstep é projetada para quem busca conforto, resistência e versatilidade em um calçado tático. Com tecnologia avançada, essa bota é leve e ideal para uso prolongado, garantindo uma experiência agradável em diferentes tipos de terreno. Sua construção robusta a torna perfeita para ambientes úmidos, permitindo desempenho em condições adversas. Entre suas principais características, destacam-se a Tecnologia de Conforto IBTEC, que proporciona um ajuste perfeito aos pés, e um respirador lateral que facilita a ventilação e drenagem de água. Seu material, em Couro Hidrofulgado de 2.0mm e Cordura 1000, assegura durabilidade e conforto, enquanto o protetor acolchoado de tornozelo oferece estabilidade durante atividades dinâmicas. Com design leve e disponível em tamanhos de 35 a 46 BRA, a Bota Lightness Confort 8627-1 Black atende a diversas necessidades, garantindo segurança e conforto. Ficha Técnica - Campo: Bota Lightness Confort 8627-1 Black - Tecnologia: IBTEC - Couro: Hidrofulgado 2.0mm - Material do Cano: Cordura 1000 - Forração Interna: Nylon Tridimensional - Altura do Cano Interno: 19,5 cm (7,6" polegadas) - Altura do Cano Externo: 22,9 cm (9,1" polegadas) - Peso: 590 gramas (tamanho 40 BRA) - Numeração Disponível: 35 ao 46 BRA (5 ao 13 USA)', 490.42, 490.42, NULL, 'Sports & Outdoors > Sports Footwear > Others', 'https://cf.shopee.com.br/file/sg-11134201-820ol-mnaa08qewd1g5c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1782892383%2F58259227237', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40328558740', 'Conjunto 2 Assentos Reposição para Cadeiras Charles Eames - Seat&co', '✨Assento Colorido para Cadeiras Eames 🎨🪑 🌟 Transforme sua cadeira Eames com muito mais cor, conforto e estilo! Nossos assentos coloridos foram projetados para se encaixar perfeitamente nos modelos clássicos, oferecendo não só um conforto excepcional, mas também aquele toque de personalidade que faz toda a diferença no seu espaço. 🎨 Disponíveis em diversas cores vibrantes, são ideais para quem deseja renovar a decoração com um toque de modernidade, charme e autenticidade. 💎 Qualidade e praticidade: Fabricados em polipropileno de alta qualidade, são resistentes, duráveis e fáceis de limpar, mantendo sua cadeira sempre bonita e funcional por muito mais tempo. 🏠✨ Perfeito para qualquer ambiente! Seja em espaços residenciais, escritórios, cafés ou ambientes comerciais, eles são a escolha ideal para quem busca design, conforto e versatilidade. 🔥 Destaque-se! Renove sua cadeira Eames com um assento que combina ✨estilo, 💖conforto e 💡funcionalidade! 📐 Especificações: 🛒 KIt com 2 Assentos 📏 Altura do encosto: 43 cm 📏 Largura total: 49 cm 📏 Profundidade total: 43 cm 🪑 Material: Polipropileno 💪 Capacidade de carga: 110 kg', 299.99, 128.8, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mkibtsbner5ub9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F791969908%2F40328558740', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
