INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253591802', 'Tenda Gazebo 2x2 Desmontável Fácil de Montar Reforçada Feira Feirinha Jardim Proteção Uv Branca', 'CARACTERÍSTICAS: Dimensão: 2m x 2m Altura: 1,90m Material Cobertura: Polietileno FPS60 Estrutura: Tubos Aço Pintura Epóxi Peso: 4kg Cor: Branca A Tenda Gazebo Tubular Bel é perfeita para quem busca sombra e conforto em atividades ao ar livre. Com cobertura em polietileno que bloqueia até 60% dos raios UV, ela protege contra o sol intenso, ideal para famílias em praias ou piqueniques. Sua estrutura tubular em aço com pintura epóxi garante durabilidade e resistência ao tempo, montando rapidamente sem ferramentas especiais. Leve e portátil, pesa apenas 4kg e vem com sacola para transporte fácil. Use em jardins, piscinas, campings ou eventos, desmontando em minutos para guardar compacto. Invista em qualidade Bel para momentos seguros e agradáveis ao ar livre, com garantia de 3 meses. BENEFÍCIOS: Proteção Solar: Bloqueia 60% raios UV, evitando queimaduras e garantindo conforto prolongado Fácil Montagem: Encaixe rápido sem ferramentas, pronta em menos de 5 minutos para uso imediato Portabilidade: Leve 4kg com sacola inclusa, ideal para transportar em viagens ou eventos DIFERENCIAIS TÉCNICOS: Estrutura Resistente: Aço epóxi anti-corrosão, suporta ventos moderados e uso frequente em ambientes externos O QUE ESTÁ INCLUSO? 1 Tenda Gazebo Tubular Bel 2x2 Polietileno Branca, espeques metálicos, tirantes e sacola transporte O pedido acompanha nota fiscal? Todo pedido efetuado segue acompanhado de nota fiscal emitida para o CPF/CNPJ informado na compra. Não efetuamos vendas sem emissão de nota fiscal. Precisa de ajuda? Utilize o campo de perguntas e esclareça suas dúvidas diretamente com um de nossos atendentes', 434.6, 269.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjodd61v5z41a9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045256831%2F58253591802', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202377801', 'Bola Biribol Rainha Piscina Impermeável Esporte Vôlei Aquático Macia Resistente Verão Oficial', 'CARACTERÍSTICAS: -Marca: Rainha -Modelo: Biribol -Tecnologia: Tecnofusion (100% impermeável) -Material: PVC -Miolo: Airbility (substituível e lubrificado) -Peso: 260g - 280g -Circunferência: 58cm - 60cm A Bola de Biribol Rainha é o equipamento ideal para quem busca elevar o nível das partidas de vôlei na piscina. Desenvolvida com tecnologia de ponta, ela oferece a combinação perfeita entre leveza e resistência, garantindo que suas horas de lazer sejam marcadas por jogadas precisas e muita diversão. Com um design vibrante em azul e amarelo, esta bola não apenas se destaca visualmente, mas também proporciona uma performance superior em ambientes aquáticos. Seja para um jogo casual com amigos ou para treinos mais intensos, a Rainha entrega a qualidade necessária para suportar o uso frequente sem perder suas propriedades originais. BENEFÍCIOS: -Impermeabilidade: Tecnologia Tecnofusion impede a absorção de água mantendo o peso original da bola. -Conforto: O material em PVC macio evita dores e impactos excessivos durante as jogadas. -Durabilidade: Construção robusta que garante longa vida útil mesmo sob exposição constante ao sol e cloro. DIFERENCIAIS TÉCNICOS: -Tecnofusion: Sistema de termofusão que elimina as costuras, tornando a bola totalmente esférica e resistente. O QUE ESTÁ INCLUSO? 1 Bola Biribol Rainha O pedido acompanha nota fiscal? Todo pedido efetuado segue acompanhado de nota fiscal emitida para o CPF/CNPJ informado na compra. Não efetuamos vendas sem emissão de nota fiscal. Precisa de ajuda? Utilize o campo de perguntas e esclareça suas dúvidas diretamente com um de nossos atendentes', 159.9, 95.09, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Volleyball', 'https://cf.shopee.com.br/file/br-11134207-820mg-mo49n8wf86ww1e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045256831%2F58202377801', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194403456', 'Sallve Hidratante Antiatrito', 'um creme corporal diário para prevenção e tratamento de assaduras. sua poderosa ação hidratante diminui a fricção entre as pernas, dobras de pele, a roupa e a pele, e outros, garantindo mais conforto e movimento no seu dia a dia. com textura superleve, ele age nas regiões já sensibilizadas, acalmando e auxiliando no processo de recuperação da pele. o que só ele faz? . previne a formação de assaduras . acalma e recupera a pele já sensibilizada . auxilia na uniformização de tom e textura da região . não deixa a região esbranquiçada ou pegajosa . oferece hidratação corporal prolongada como usar essa fórmula? 1. sobre a pele seca e limpa, aplique uma camada nas regiões do corpo mais propensas a assaduras e atritos. 2. espalhe gentilmente com movimentos circulares. 3. se sentir necessidade, retoque a aplicação ao longo do dia.', 69.9, 69.9, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meospddox1xf90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1609769712%2F23194403456', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
