INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258576869', 'Regulador retificador de voltagem Magnetron Honda Cg Fan 125 09/13 Carga Baixa Bateria', 'Regulador Retificador Magnetron Desenvolvido com tecnologia de ponta, ele garante que a voltagem enviada para a bateria seja constante e precisa, protegendo todo o sistema elétrico contra picos de tensão e garantindo uma vida útil prolongada para sua bateria. -------------------------------------- Compatibilidade : Honda - CG 150 Titan (KS/ES/ESD/Sport/Job): 2004/2008 - NXR 150 Bros (KS/ES/ESD): 2006, 2007, 2008. - CG 125 Fan / Cargo (KS/ES): 2009/2013 Conteúdo da Embalagem: - 01 Regulador Retificador Magnetron. - Voltagem de Saída: 14.5V ± 0.5V -------------------------------------- - Carga Estável e Segura: Mantém a voltagem ideal para carregar a bateria sem riscos de sobrecarga. - Partidas Rápidas: Garante que a bateria esteja sempre com a energia necessária para o acionamento do motor.', 69.0, 58.65, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-81zwj-mmvvqpu3ku1048', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F574587990%2F58258576869', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20214026329', 'Luminaria silicone nuvem - Imaginarium', 'A Luminária Silicone Nuvem vai te ajudar a atingir a iluminação em qualquer momento que precisar, e vai clarear as ideias em todo canto da casa, do seu quarto ao home office. Carregada de energia positiva, essa nuvem é pura evolução espiritual para seu espaço de descanso, trabalho ou estudos. Além de carismática, ela é toda macia, seu material é em silicone. E não para por aí, a iluminação é controlada pelo toque: Com o botão ligado, basta tocar nela para acender ou desligar a luz e diversas opções de iluminação nas cores: Vermelho, azul escuro, verde, amarelo, roxo, azul claro e branco. Baixo astral? Nuvem que num tem, com a Luminária Silicone Nuvem é só energia positiva. Informações técnicas Utilizar 3 pilhas AAA (não inclusas) Potência: 0,3W Tensão: 4,5VDC Número de LEDs: 4 LEDs Vida útil dos LEDs: 10.000 horas', 239.88, 239.88, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/7cffc3a69411fc58f91f2503d47867ee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F789092088%2F20214026329', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22597928572', 'Mesa Diretor Kappesberg Office Platinum 120cm', 'A perfeita união entre elegância e funcionalidade com a Linha de Escritório Office Platinum da Kappesberg. Moderna, os produtos unem beleza e resistência, garantindo uma composição única. Versátil, a Mesa Secretária R801 é perfeita para o ambiente de estudo, escritório ou home office. Com 77cm de altura, 1,20m de largura e 70cm de profundidade, seu tampo é produzido em chapa MDP de 15mm e 25mm com acabamento BP, matéria-prima de alta qualidade e mais resistente contra riscos e arranhões. Com as bordas engrossuradas de 40mm, o tampo, na cor chumbo, proporciona elegância e sofisticação ao espaço, sendo perfeito para ambientes sóbrios, enquanto a estrutura da mesa é metálica, com tubo quadrado pintado com tinta epóxi na cor preto fosco, o que garante maior resistência e durabilidade contra a umidade. Uma combinação com um design único, garantindo beleza e destaque ao seu ambiente. Os diferenciais ficam por conta do passa fio, na parte superior do tampo, garantindo organização e praticidade, e das sapatas reguláveis, permitindo fácil ajuste em todos os pisos e proporcionando estabilidade. Informações importantes: As imagens são meramente ilustrativas, não acompanha acessórios; Pode haver variação de cor de acordo com a calibragem da tela onde o produto está sendo visualizado; Todos nossos móveis são entregues desmontados; A montagem é sempre por conta do cliente (orientamos a contratação de um profissional qualificado, o manual de montagem acompanha o produto); O vídeo do produto pode ser genérico, então atente-se às imagens do anúncio para optar pela cor/modelo.', 751.28, 559.99, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-8260f-ml3ur8yjpb7pfe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1316611304%2F22597928572', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393826142', 'Mesa De Escritório em L Kappesberg 2 Gavetas Versatile Munique 170cm x 150cm', 'Beleza e funcionalidade você encontra na linha de escritórios Versatile. Móveis desenvolvidos para tornar o local de trabalho mais confortável, proporcionando o bem estar necessário para o seu dia a dia. A linha é composta por itens modulares, possibilitando que você crie o seu ambiente de trabalho ideal de acordo com a sua necessidade. Linha com acabamento em BP, com mais resistência e durabilidade. O kit office W21-1170 é ideal para quem busca praticidade no seu ambiente de trabalho. Possui pés com estrutura metálica na cor preto fosco e duas gavetas com chave. Informações importantes: As imagens são meramente ilustrativas, não acompanha acessórios; Pode haver variação de cor de acordo com a calibragem da tela onde o produto está sendo visualizado; Ambos os lados tem 59,6cm de profundidade (tampos); Todos nossos móveis são entregues desmontados; A montagem é sempre por conta do cliente (orientamos a contratação de um profissional qualificado, o manual de montagem acompanha o produto); O vídeo do produto pode ser genérico, então atente-se às imagens do anúncio para optar pela cor/modelo.', 1278.3, 919.99, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-81zwh-miga10uehvk396', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1316611304%2F22393826142', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
