INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22522562576', 'Sêneca - sobre uma vida melhor', 'Sêneca é o principal representante romano do estoicismo, doutrina filosófica caracterizada pela consideração do problema moral. Neste box especial você encontrará as obras: A vida feliz, Sobre a tranquilidade da alma e Sobre a brevidade da vida._x000D_ _x000D_ Editora: Principis_x000D_ Edição: 1, 2022_x000D_ Autor: Sêneca _x000D_ Idioma: Português_x000D_ Páginas: 352_x000D_ Dimensões: L 15.50 x A 22.60 x E 2.60_x000D_ ISBN: 7908312112523_x000D_ Coleção: Clássicos da literatura mundial_x000D_ Linha Editorial: Principis - Filosofia_x000D_ Faixa Etária: + 12 anos_x000D_ Assuntos (tags): Crescimento, Descoberta, Vida, Política, Estoicismo, Filosofia, Reflexão, Sabedoria, Amizade, Velhice, Ética, Discursos, Conselhos_x000D_ BISAC: Corpo, Mente & Espírito / Inspiração & Crescimento Pessoal_x000D_ Linha de Produto: Box Principis_x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação brilho_x000D_ Material: Papel', 59.9, 59.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/sg-11134201-23020-68apyl6jm0mv94', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F22522562576', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259444641', 'Biscoito Queijinho Piraque', 'Esse petisco salgado da Piraquê é um verdadeiro clássico. O Biscoito Salgadinho Queijinho é feito com queijo parmesão de verdade e assado, bem crocante. Os momentos felizes com os amigos ou com a família ficam ainda melhores com o Queijinho Piraquê. Ideal para aperitivos, lanches rápidos ou para acompanhar suas receitas favoritas.', 5.79, 5.79, NULL, 'Food & Beverages > Snacks > Biscuits, Cookies & Wafers', 'https://cf.shopee.com.br/file/sg-11134201-8262m-mj72lx6odqmfb1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555072%2F58259444641', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697989221', 'Lixadeira Orbital Lov 320 127V Vonder', 'Lixadeira orbital LOV 320, 127 V~, VONDER Possui formato ergonômico com punho emborrachado, proporcionando maior comodidade e controle nos trabalhos. Indicada para lixamento e acabamento em superfícies de madeiras e derivados. Especificações: Modelo: LOV 320 Potência: 320 W Oscilações por minuto (opm): 14.000/min Dimensões da base: 93 mm x 185 mm Coletor de pó: Possui Aceleração transmitida nas mãos - braços do operador - ah: 5,54 m/s² Incerteza da aceleração transmitida nas mãos - braços do operador - k: 1,5 m/s² Segue norma: IEC 62841-1 e IEC 62841-1-2-4 Tensão (V): 127 V~ Frequência (Hz): 50 Hz / 60 Hz Massa aproximada (peso) (kg): 1,8 kg Conteúdo da Embalagem: 1 Lixadeira orbital. Acompanha: 1 coletor de pó, 1 adaptador para aspirador de pó, 2 folhas de lixas G80, 2 folhas de lixas G120 e 2 folhas de lixas G150.', 453.76, 366.49, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m30xcbm05yvpfa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F23697989221', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8769903147', 'Livro - Peppa Pig - 365 Desenhos para colorir - Capa comum - Ciranda Cultural', 'Venha conhecer um pouco mais sobre o universo de Peppa Pig enquanto se diverte colorindo muitas ilustrações dessa turma divertida. Neste livro, além de curiosidades sobre a Peppa, sua família e seus amigos, há diversas histórias para alegrar os seus 365 dias! Editora: Ciranda Cultural Edição: 1, 2020 Autor: Paloma Blanca Alves Barbieri Idioma: Português Páginas: 288 Dimensões: L 15.60 x A 23.00 x E 1.60 ISBN: 9786555000986', 19.9, 19.9, NULL, 'Books & Magazines > Books > Sticker & Colouring Books', 'https://cf.shopee.com.br/file/f070bcde883bf21cc01db0c222a79843', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F8769903147', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797996234', 'Arame Revestido Com Pvc Verde Bwg 12 1 Kg Vonder', 'Arame revestido com PVC, verde, BWG 12, 1 kg VONDER Possui revestimento de PVC, que aumenta a proteção contra corrosão e a vida útil do arame. Indicado para instalação de gesso. Especificações Técnicas: Modelo: BWG 12 Acabamento do arame revestido: PVC Comprimento aproximado por (kg) do arame revestido: 18 m Cor: Verde Diâmetro do arame: BWG 12 (2,77 mm) Diâmetro do arame com revestimento: 3,80 mm Tipo de aço: Aço baixo teor de carbono Tipo do arame: Comercial Massa aproximada (peso) (kg): 1 kg Conteúdo Da Embalagem: 1 Rolo de arame com 1 kg.', 43.74, 35.64, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m2885q2d0z0mc9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F22797996234', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21240658682', 'Livro - Armand Dillo, The Armadillo W.Books', 'O tatu Taruto Tarantino é diferente dos outros. Ele gosta de contar histórias para a família à noite e de sair durante o dia para passear na floresta. Mas, de um momento para o outro, eles precisaram sair da toca em que viviam. Este livro, escrito por Donaldo Buchweitz e ilustrado por Bill Borges, é um convite para tornar a hora da leitura uma grande aventura._x000D_ _x000D_ Editora: Ciranda na Escola_x000D_ Edição: 1, 2021_x000D_ Autor: Donaldo Buchweitz_x000D_ Idioma: Inglês_x000D_ Páginas: 32_x000D_ Dimensões: L 24.00 x A 24.00 x E 0.50_x000D_ ISBN: 9786589956341', 39.9, 39.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/d3604cc685051e3f69d74d8e344fd954', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F21240658682', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397182887', 'Livro Literatura infantil Dirceu e Marília', 'Tão fascinante quanto a história são os seus vazios. E é o que encontramos neste relato que se passa numa noite fria de 1789, na qual Tomas Antônio Gonzaga, um dos poetas inconfidentes, era preso em Vila Rica, acusado de conspirar contra a Coroa portuguesa. E é neste instante que o autor Nelson Cruz liberta seu talento, entra na mente do poeta e partilha conosco o que ele poderia estar pensando._x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2023_x000D_ Autor: Nelson Cruz_x000D_ Ilustrador: Nelson Cruz_x000D_ Idioma: Português_x000D_ Páginas: 40_x000D_ Dimensões: L 19.00 x A 25.00 x E 0.30_x000D_ ISBN: 9786553841086_x000D_ Coleção: Não se aplica_x000D_ Linha Editorial: Ciranda na escola - Literatura infantojuvenil_x000D_ Faixa Etária: + 9 anos_x000D_ Assuntos (tags): Brasil, História, Colonização, Poesia, Pensamentos_x000D_ BISAC: Literatura Infantil / Histórica_x000D_ Linha de Produto: Literatura infantil_x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação fosca_x000D_ Material: Papel', 39.9, 39.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rbm5-lpffl8c86dglcf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F23397182887', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
