INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21007532742', 'Redescobrindo Sua Bíblia | André Coelho', 'Redescobrindo sua Bíblia De Gênesis a Apocalise uma análise objetiva de cada livro da Bíblia para você conhecer aplicar e sinar as verdades contidas na Palavra de Deus Redescobrindo sua bíblia deve alegrar corações de milhares de leitores que se identificam como cristãos evangélicos mas que têm poucuíssima ideia do conteúdo do Livro sobre o qual adoutrina e a prática cristã se fundamentam A Bíblia é o livro mais vendido no Brasil; mesmo assim a maioria dos seus donos carece de um conhecimento rudimentar do Livro dos livros Agora voce tem em mãos um livro repleto de informações detalhadas e panorâmicas para iniciantes e estudiosos para alunos e professores da Bíblia Não conheço outro livro em português que demonstre tanta criatividade na transmissão de tão amplo conhecimento da Bíblia e de maneira tão fácil de assimilar Somente folhear o livro confirmará a minhão opinião sobre a singular qualidade diática deste estudo panorâmico da Bíblia Além dos incontáveis fatos relacionados com a oriem autoria e conteúdo acompnhados de quadros mapas e outros meios de ensino o autor aproveitou a oportunidade para passar algumas lições interpretativas baseadas nas histórias do Antigo Testamento Quero oferecer os meus parabpens ao Pr André Colelho pelas muitas qualidades e informações deste manual Recomendado a leitores professores curiosos e a todos os que se sentem carentes de um conhecimento do Livro que mais influenciou nossa civilização ocidental Título Redescobrindo Sua Bíblia Autor André Coelho Páginas 496 Formato 23 x 16 x 1 cm Peso 745g ISBN 7897185853490 Editora Geográfica', 56.11, 56.11, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-81zva-mipz7iyy8f0h4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F21007532742', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20875555899', 'Bíblia Foi Por Amor | Letra Normal | NAA | Capa Dura', 'Bíblia Foi Por AmorBíblia Foi Por Amor com capa dura desenvolvida por O Verso da Vida traz uma capa Foi Por Amor. O modelo traz com sigo o texto NAA (Nova Almeida Atualizada), com letra no tamanho normal. A Nova Almeida Atualizada é uma tradução lançada em 2017 pela SBB, com o que há de melhor e mais recente no campo dos estudos teológicos e científicos sobre as Escrituras e seu contexto original. Resultado de uma profunda revisão da consagrada tradução Almeida Revista e Atualizada, a Nova Almeida Atualizada apresenta um texto clássico com uma linguagem atual, seguindo a norma padrão do português escrito e falado no Brasil. Título: Bíblia Foi Por Amor Linguagem: NAA (Nova Almeida Atualizada) Tamanho da Letra: Normal Capa: Capa dura foi por amor (coroa de espinhos) Índice: Não Páginas: 960 Formato: 20 x 14 x 1.5 cm Peso: 0.490 Kg ISBN: 7898680400233 Editora: O Verso da Vída', 46.31, 46.31, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134201-23030-m2gqgl2mihovc2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F20875555899', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42400910731', 'Life Planner: Vida e Finanças | Patrícia Lages | Capa Dura Espiral Organização', 'Life Planner: Vida e Finanças O Life Planner , produzido e escrito por Patricia Lages, escritora de best-seller e jornalista financeira do Jornal da Record, é guia com muito valor para ser explorado ao longo do ano, com o propósito de possibilitar que você, mulher, seja a personagem principal de sua história. Isso representar ter atitudes conscientes sobre todas as suas atividades, desde as mais simplórias até as mais relevantes. A ideia é sair do piloto automático, definir metas diárias e fazer escolhas conscientes para alcançá-las. Este planner contém temas como finanças, empreendedorismo e desenvolvimento pessoal. Ele oferece testes, análises, dicas e técnicas para ajudar você nesse processo diário , desafiador e empolgante. Tudo isso para que sua vida flua melhor, com propósito e qualidade, levando-a a viver um ano incrível. Olha algumas das coisas que o Life Planner tem para você: Roda do Equilíbrio da Vida; Análise SWOT; Descubra seus pontos fortes; Teste de Perfil Empreendedor; Seu plano de negócio com o Canvas; Plano de Leitura da Bíblia; Técnica Feynman — Aprenda um jeito simples de aprender mais; Reconheça seu formato de corpo — Manequim modelo; Com que roupa eu vou? — Tabela; Meu inventário — Peças de roupas; Dicas para economizar no supermercado; Investimentos — Mitos e verdades; Dicas de ouro; Calendário semanal; QR Code — 1 vídeo por semana; Devocional mensal; Planejamento de despesas; Orçamento mensal; Balanço mensal; Plano de ação; Resumo de despesas por categoria; Balanço anual. Atenção: Acompanha a caderneta de bolso: Diário de Consumo — Gastos gerais e Cartão de crédito Aproveite esses recursos e desfrute de uma vida plena. Especificações do Life Planner: Vida e Finanças Título: Life Planner: Vida e Finanças Autor(es): Patrícia Lages Ano de Edição: 2023 Capa: Dura Modelo: Organização Acabamento: Laminação Brilhante Miolo: Papel Off-Set Páginas: 240 Dimensões: Altura: 25 cm Largura: 18,5 cm Profundidade: 2,0 cm Peso: 0,740 kg ISBN: 9788577424726 Editora: Hagnos', 90.98, 90.98, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9kpdu14yqyqee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F42400910731', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
