INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298000604', 'Filtro Óleo Nissan Frontier 2006 a 2012 - 837826 - WO460', 'Filtro Óleo Nissan Frontier 2006 a 2012 837826 WO460 Espanhola - LE / SEL / SE / XE - 2.5 16v Turbo Diesel - Automático/Mecânico Basicamente, os filtros lubrificantes devem atender às funções de reter todos contaminantes que possam causar danos ao perfeito funcionamento do motor, mantendo as características de estrutura do óleo, uniformidade de circulação e eficiência no período de uso pelo motor. O Filtro do Óleo retém os contaminantes contidos no sistema de lubrificação, principalmente os abrasivos (metais) , provenientes do atrito das partes móveis do motor que permanecem em suspensão no óleo lubrificante.', 28.28, 28.28, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbki-lmqigwfd4j0r03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23298000604', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
