INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798814073', 'KIT 6 BISNAGA GRANDE FLEXÍVEL PROFISSIONAL 1 LITRO PARA MOLHOS - BISNAGA 1 LITRO', 'Aprimore a eficiência da sua cozinha com a Bisnaga Profissional Flexível de 1 Litro, uma ferramenta indispensável tanto para chefs quanto para cozinheiros domésticos. Fabricada com um plástico resistente e de alta flexibilidade, esta bisnaga é ideal para o uso diário, oferecendo durabilidade e um manuseio confortável. O corpo translúcido e com marcações de volume permite que você controle com precisão a quantidade de líquido, evitando desperdício e garantindo receitas perfeitas. A tampa com bico dosador e protetor assegura uma aplicação precisa e limpa, sendo ideal para: Molhos: Para sanduíches, saladas e pratos em geral. Confeitaria: Para aplicar caldas, recheios, coberturas e decorar bolos e doces com agilidade. Fácil de limpar e projetada para otimizar seu tempo, esta bisnaga de 1 litro é a solução perfeita para manter a organização e a precisão em todas as suas criações culinárias.', 64.85, 64.85, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-7rdwv-mdg2sr04rvfo4a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F23798814073', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
