INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198480671', 'Femme Way Cabelo e Unha 60cp Rev - Prevent', 'Femme Way Cabelo e Unha 60cp Rev - Prevent Descrição FEMME WAY CABELO E UNHA 60 CP é um suplemento alimentar de vitaminas e minerais em comprimidos. Apresentação 60 comprimidos revestidos Composição Ácido Pantotênico; Vitamina E; Biotina; Zinco; Picolinato de Cromo Advertência Este produto não é medicamento. Não exceda a dose indicada. Mantenha fora do alcance de crianças. Gestantes, nutrizes e crianças até 3 anos devem consultar o médico antes do uso. Conservar longe de luz, calor e umidade. Indicado para maiores de 19 anos Importante Decoração não inclusa. Imagens ilustrativas. Cores podem variar por luminosidade, monitor ou percepção. Dados fornecidos pelo fabricante/fornecedor.', 46.99, 46.99, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-7rfho-m9hc9xtzh09zcc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341217898%2F22198480671', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498910972', 'Caixa Dutada Sub 12 Polegadas Pioneer 350w Rms 4 Ohms Bobina Simples Grave Interno Porta Malas', 'ENVIO IMEDIATO! PRODUTO EM ESTOQUE, NOTA FISCAL E GARANTIA! Desfrute de graves potentes e qualidade sonora confiável com a Caixa Dutada + Subwoofer Pioneer TS‑W3060BR de 12 polegadas. Equipamento ideal para quem busca intensidade no som automotivo com graves sólidos, de qualidade e sem distorção. Especificações do Alto Falante: - Modelo do Subwoofer: Pioneer TS-W3060BR - Tamanho: 12 polegadas - Potência RMS: 350 Watts - Potência Máxima: 600 Watts (pico) - Impedância: 4 ohms - Resposta de Frequência: 30 Hz – 2.000 Hz - Sensibilidade: 87 dB (1W/1m) - Frequência de Ressonância (Fs): 46 Hz - Xmax (excursão máxima): 6 mm - Qts (fator de qualidade total): 0,96 - Vas (volume equivalente): 38,1 litros Medidas da Caixa: - Largura: 43,5cm; - Altura: 33,5cm; - Profundidade Superior: 20,5cm; - Profundidade Inferior: 32cm. Importante: - Imagens Meramente Ilustrativas. - Recomendamos que a instalação seja feita por profissional especializado, não nos responsabilizamos pelo mau uso do produto. SUBGRAVE A SUA LOJA DE ACESSÓRIOS AUTOMOTIVOS!', 489.79, 489.79, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-820lv-mo3yhtwliltu29', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F414508631%2F23498910972', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22097078253', 'Condrix Dog Tabs com 60 Tabletes 1200 Mg Organnact - 72 g', '- Indicado para manutenção e tratamento de patologias articulares; - Condroitina, glicosamina e extrato de cavalinha; - Muito mais absorção de nutrientes; - Rico em Sais Minerais. * Consulte sempre o médico Veterinário de sua confiança para o uso apropriado deste medicamento. Leia a bula ou informações descritas na embalagem. Detalhes O Suplemento Organnact Condrix Dog Tabs um suplemento alimentar que combina minerais quelatados, Dl-metionina, sulfato de condroitina A e glicosamina, além do extrato de Cavalinha, indicado para cães de qualquer idade. Dicas Especiais Suplemento alimentar indicado para cães de qualquer idade, contendo minerais e aminoácido. Apresenta-se em tabletes mastigáveis, facilitando a degustação do seu pet.Pode ser usado diariamente. Não esqueça de levar seu pet no veterinário de sua confiança. O CONDRIX DOG TABS é um suplemento alimentar que combina minerais quelatados, Dl-metionina, sulfato de condroitina A e glicosamina, além do extrato de Cavalinha, indicado para cães de qualquer idade. A glucosamina e condroitina são componentes denominados condroprotetores que fazem parte da estrutura de tendões, ligamentos, cartilagens e do líquido sinovial. Sulfato de Condroitina: é o maior constituinte da cartilagem e está diretamente ligado à síntese de proteoglicanos. Fornece estrutura, absorve nutrientes e permite a movimentação de moléculas pela cartilagem, propriedade importante visto que a cartilagem articular é desprovida de vasos sanguíneos. Sulfato de Glicosamina: é um composto derivado do metabolismo da glicose que auxilia na produção de proteoglicanas, apresentando-se como precursor da condroitina. Extrato de Cavalinha: a cavalinha é muito rica em sais minerais, principalmente silício, fósforo e cálcio. A abundância de sais de silício confere propriedades remineralizantes e contribui na manutenção do tecido conjuntivo. Modo de usar: Cães com 10 a 15 kg de peso: 1 tablete, duas vezes ao dia; Cães com 15 a 25 kg de peso: 1 tablete e 1/2, duas vezes ao dia; Cães com 25 a 50 kg de peso: 2 tabletes, duas vezes ao dia. Composição Celulose, cavalinha, maltodextrina, sulfato de condroitina, sulfato de glicosamina, aroma de carne, manganês aminoácido quelato, DL-metionina, enxofre ventilado (flor de enxofre).', 177.89, 129.9, NULL, 'Pets > Pet Healthcare > Vitamins & Supplements', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ln8n7hlizq2s5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F22097078253', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
