INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45655927313', 'Fantasia Medusa Feminina Adulta Kit Tiara Serpente Grande + Saia 40cm', 'Itens inclusos:1x Tiara com Cobras Grande 1x Saia 40 cm Dimensões do produto: Tamanho: Único - Veste Numeração de roupa 36 a 44. Comprimento da Saia 40 cm Especificações Técnicas Material: Plástico e Poliéster. Cor: Verde Produto a pronta entrega! Produto original! Transforme-se em uma Lenda Mitológica com o Kit Medusa Adulta! Chega de fantasias comuns! Se o seu objetivo é causar impacto e ser o centro das atenções no Halloween ou no Carnaval, o Kit Fantasia Medusa é a sua escolha definitiva. Esqueça as tiaras pequenas que somem no cabelo: este kit traz uma Tiara de Serpentes imponente, com design expansivo que cria o efeito visual de "cabeça de medusa" instantaneamente, sem pesar ou incomodar. Para completar o visual de Górgona com leveza e estilo, o kit acompanha uma Saia de Tule Verde Água. Feita em poliéster de alta qualidade, ela possui 40 cm de comprimento, o tamanho ideal para garantir liberdade de movimento na pista de dança sem ser curta demais. O elástico na cintura oferece um ajuste democrático e confortável, adaptando-se perfeitamente ao corpo para você curtir a festa do início ao fim sem apertos. Tiara de Alto Impacto com Design de Serpente Feita de material resistente, mas leve Saia com cintura elástica que se ajusta a diferentes manequins Saia com volume e movimento', 95.51, 95.51, NULL, 'Women Clothes > Costumes', 'https://cf.shopee.com.br/file/sg-11134201-82629-mkdw4r9opx54d7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1064041628%2F45655927313', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40507794274', 'Cabo Flat para Notebook Lenovo Ideapad S145-81V70008BR', 'Cabo Flat para Notebook Lenovo Ideapad S145-81V70008BR Este é um Cabo Flat bringIT compatível com o notebook Lenovo Ideapad S145-81V70008BR. O cabo flat é responsável pela conexão da tela do seu notebook e se estiver danificado pode causar diversos problemas de funcionamento no equipamento. Recomendamos que a troca do cabo seja feita por um profissional especializado. Para evitar problemas de compatibilidade, compare as fotos deste anuncio com seu equipamento original. Assim você consegue verificar as principais informações de compatibilidade e demais especificações do seu cabo flat: - Tamanho do cabo flat - Posição do conector - Número de pinos no conector Informações Técnicas Part Number original do produto: DC020023A00 Quantidade de Pinos: 30 Pinos Garantia: 3 meses de garantia contra defeitos de fabricação Referência: CB232-LN-0003', 53.64, 53.64, NULL, 'Computers & Accessories > Desktop & Laptop Components > Others', 'https://cf.shopee.com.br/file/sg-11134201-8259n-mq69sqq9mln193', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F392651618%2F40507794274', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
