INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19397516419', 'Bloco De Montar 350 Peças Encaixar com Rodinha Brinquedo Educativo Peças Oferta', 'Atenção: Conta cada pecinha, incluido as Rodinhas. ITEM ANUNCIADO 1 PACOTE DE BLOCO DE MONTAR COM 350 PEÇAS. Bloco Pinos 1,2 x 2,5 x 2,1 Cm Bloco Pinos 2,5 x 2,5 x 2,1 Cm Bloco Pinos 3,7 x 2,5 x 2,1 Cm Bloco Pinos 5,0 x 2,5 x 2,1 Cm Validade: Indeterminada Indicação: Maiores de 3 anos Cores: Sortidas Composição: Plástico. Os blocos de montar além de estimular a criatividade, auxiliam no desenvolvimento da concentração, da coordenação motora e do raciocínio lógico, fazendo com que as crianças busquem soluções de forma independente e sintam o prazer de ver o seu pequeno projeto concluído, contando com a possibilidade de desfazer e começar tudo de novo. QUALQUER DUVIDA ESTAMOS A DISPOSIÇÃO BOLINHA MÁGICA', 114.89, 91.91, NULL, 'Mom & Baby > Toys > Block Toys', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lnvxjc510yq4d0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045133925%2F19397516419', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
