INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19999552183', 'Kit 15 Caixas Massa Modelar + 15 Mini Giz + 15 Colorir + 60 Cortadores Kit Festa Aniversario Criança', '***ATENÇAO, NAO PERSONALIZAMOS E NEM FABRICAMOS NENHUM PRODUTO. TODOS VAO SORTIDOS NOS MODELOS DAS FOTOS. SEM POSSIBILIDADE DE ESCOLHA DE COR. ITEM ANUNCIADO 15 CAIXINHAS DE MASSINHAS DE MODELAR 65g 6 CORES (MODELOS DAS FOTOS) DIMENSÕES DA CAIXA DA MASSINHA: 9 CM DE ALTURA 7,4 CM DE COMPRIMENTO 1,5 CM DE LARGURA 60 UNIDADES DE CORTADOR DE MASSINHA - FORMINHAS COLORIDOS E SORTIDOS A coleção possui mais de 32 Modelos diferentes ( ANIMAIS SAFARI, DINOSSAUROS E COMUNS ) COLECIONE!!! (há Repetiçoes) Material de plástico Comprimento de 4 a 6 cm Altura 1,5 cm 15 REVISTA DE COLORIR SORTIDAS 15 Pag (ALFABETO, TABUADA, BIBLICO, PARA MENINAS, PARA MENINOS, ANIMAIS ENTRE OUTROS) Nesse link Nao é possivel escolher. TAMANHO: 27CMS X 20 CMS TEMAS SORTIDOS COM REPETIÇÃO DE CAPAS 15 CAIXINHAS DE MINI GIZ DE CERA 5 CORES (5x4 cm A Caixinha) ***ATENÇAO, SAO MINI GIZ. 5 CENTIMETROS A CAIXINHA. IDEAL PARA ANIVERSARIO, PRESENTES, PRENDA EM FESTA Criança BOLINHA MÁGICA', 111.49, 89.2, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m2cer2avy24m5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045133925%2F19999552183', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897493489', '12 Peças de Lâminas Preparadas para Microscópio Educativo Infantil Ensino Crianças', 'Kit com 12 Lâminas Preparadas para Observação em Microscópio Educacional Infantil As Lâminas Preparadas para Microscópio Lorben são feitas de plástico, sem bordas vivas e não machucam as crianças. Não quebram durante o uso e são fáceis de armazenar. Indicadas para observações botânicas, entomológicas e biológicas em microscópios educativos, destinados às crianças e jovem em iniciação científica. O Kit traz 12 lâminas com amostras separadas por cor: vermelhas para insetos e crustáceos, azuis para animais, amarelos para flores e verdes para plantas. Todas as lâminas marcam os nomes das amostras para facilitar a classificação. As amostras enviadas são: - Ovas de camarão - Asa de gafanhoto - Antena gafanhoto - Pelo de gato - Pena de canário - Pelo de coelho - Penugem de sicômoro - Penugem de dente-de-leão - Parte de abacaxi - Parte de folhagem - Fibra - Fécula de batata Marca: Lorben Material: Plástico Quantidade: 12 peças Tamanho da lâmina: aproximadamente 21x6cm Inclui: 1 Kit com 12 lâminas de microscópio preparadas OBS.: O Kit é composto de 12 lâminas: 3 vermelhas, 3 azuis, 3 amarelas e 3 verdes, contendo partes de diferentes amostras. As amostras serão enviadas conforme estoque, não sendo, necessariamente, as mesmas das imagens. Tamanho da embalagem: 20x30x5cm Peso da embalagem: 38g Código do produto: FC6072 Imagens ilustrativas. As tonalidades podem variar.', 79.9, 79.9, NULL, 'Health > Medical Supplies > Laboratory Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rd5b-lv4vd9wag0ibe7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F386114683%2F22897493489', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
