INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16557484583', 'Grão de Bico 8mm', 'O grão-de-bico é uma leguminosa rica em proteínas, fibras, vitaminas e minerais. Com uma textura firme e um sabor levemente adocicado, ele é amplamente utilizado em diversas cozinhas ao redor do mundo, sendo a base para pratos como hummus, saladas e ensopados. Ingredientes: Grão de Bico. ALÉRGICOS: PODE CONTER TRAÇOS DE GLÚTEN, LEITE, SOJA, AMENDOIM E CACAU POR CONTAMINAÇÃO CRUZADA. INFORMAÇÕES ADICIONAIS - EMBALAGEM MERAMENTE ILUSTRATIVA - PODE HAVER VARIAÇÃO DE COR DEPENDENDO DO LOTE. Entre em nossa loja e conheça outras opções de chás e ervas! Precisa de um produto que não conseguiu encontrar? Entre em contato conosco e iremos te ajudar. Contamos com uma grande linha de produtos!', 17.97, 14.2, NULL, 'Food & Beverages > Food Staples > Dried Goods', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mj8g9tfixqtd3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F657120589%2F16557484583', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
