INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198856320', 'CALDO BONE BROTH GALINHA V BRODO 500ML', 'O Bone Broth de Galinha Vero Brodo possui muito colágeno e proteínas, contribuindo para a saúde das articulações, pele e ossos. Seu longo tempo de cocção, que varia de 12 a 24 horas, garante a extração máxima de nutrientes dos ossos, proporcionando um caldo rico e altamente nutritivo. Feito com ingredientes 100% naturais, este caldo de ossos é ideal para consumo direto, proporcionando uma refeição saudável e rica em colágeno e proteínas. Além disso, pode ser utilizado para enriquecer suas receitas, adicionando um toque especial de sabor e nutrição.', 26.39, 19.99, NULL, 'Food & Beverages > Cooking Essentials > Stock, Gravy & Instant Soup', 'https://cf.shopee.com.br/file/br-11134207-81z1k-me4obrg84mpuaf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1605305232%2F23198856320', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
