INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23792783783', 'Bule Viena Baby 400ml Macchiato Invicta', 'O Bule Térmico Viena Baby Invicta é a versão compacta de um clássico da linha de garrafas térmicas Invicta, combinando design sofisticado, praticidade e alto desempenho térmico. Ideal para uso doméstico, ele mantém suas bebidas quentes ou frias por mais tempo, garantindo que seu café, chá ou qualquer outra bebida esteja sempre na temperatura ideal. Projetado para oferecer uma experiência mais confortável e sem desperdícios, o Bule Viena Baby conta com rolha dosadora para um fluxo preciso e um bico corta gotas, que evita respingos e mantém sua mesa sempre limpa. Além disso, sua estrutura compacta e resistente o torna perfeito para o dia a dia, seja em casa, no escritório ou em ambientes comerciais. CaracterísticasCapacidade: 400mlConservação térmica eficiente: Mantém líquidos quentes 5h ou frios por até 10h.Design compacto e sofisticado: Perfeito para qualquer ambiente.Rolha dosadora: Evita desperdícios e garante um fluxo preciso.Bico corta gotas: Para um servir mais prático e sem sujeira.Material resistente: Alta durabilidade para uso diário. Composição Produzido com materiais de alta qualidade, garantindo resistência e desempenho na conservação térmica.', 39.9, 39.9, NULL, 'Home & Living > Kitchenware > Tea, Coffee & Bartending Equipments', 'https://cf.shopee.com.br/file/sg-11134201-8259b-mqw7a6pt19mued', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F859051456%2F23792783783', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
