INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23034409950', 'Caneta esferográfica Cristal 1.0mm Azul caixa com 50 unidades Bic', 'Produto certificado no âmbito brasileiro de qualidade, conforme Portaria Inmetro Nº 333/2012: Segurança, Compulsório, Registro 000911/2015, OCP0040, INMETRO Caneta esferográfica clássica e favorita em milhares de lares, escritórios e escolas no mundo. Possui corpo hexagonal que assegura o conforto na escrita e transparente para visualização da tinta. Tinta de alta qualidade, que seca rapidamente evitando borrões na escrita. Maior Durabilidade: Escreve até 2 Km. Escrita macia. Fabricada com a quantidade certa de matéria-prima para uso prolongado e seguro. Não contém PVC. Possui tampa da mesma cor da tinta e também é ventilada em conformidade com padrão ISO. Na ponta conta com uma esfera de Tungstênio, perfeita e muito resistente, quase mais duras que o diamante. 100% das esferográficas são feitas por um processo altamente controlado. Desde seus início em 1950, a Companhia vem aperfeiçoando as máquinas e os processos de fabricação necessários para produzir canetas de alta qualidade e produzidas em massa. Detalhes: - Corpo transparente; - Corpo hexagonal não rola na mesa. - A cor da tampa indica a cor da tinta. - Tampa ventilada. - Ponta média de cobre de 1.0 mm com esfera de tungstênio.', 65.52, 42.47, NULL, 'Stationery > Writing & Correction > Pens & Inks', 'https://cf.shopee.com.br/file/sg-11134201-81zvn-mmj1m6b2ktfz78', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616550287%2F23034409950', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
