INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18350876830', 'Bíblia de Estudo Esperança Preta 2ª Ed Revisada e Atualizada', 'A Bíblia de Estudo Esperança é ideal para quem busca um estudo completo e ao mesmo tempo fácil de ser compreendido. A cada página, você irá encontrar de forma prática respostas, contidas no texto bíblico, para os mais diferentes questionamentos de sua própria vida. As respostas são objetivas, claras e abrangentes. Seja em casa, na família, no trabalho ou mesmo com os amigos, a Bíblia de Estudo Esperança servirá como sua ferramenta evangelística, apologética e de edificação. Conteúdo: São 365 perguntas e respostas divididas em 20 temas distintos: Deus e a Criação, Bíblia, Cristo, Pecado, Sabedoria, Salvação, Vida Eterna, Nova Vida, Igreja, Misticismo, Mundo Espiritual, Religião, Momentos Difíceis, Fraquezas, Sexualidade, Questões Difíceis, Família, Finanças, Mundo Atual, Datas e Textos Especiais. As perguntas foram cuidadosamente elaboradas a partir da doutrina, Bíblica fundamental, do contexto religioso brasileiro e do mundo contemporâneo.', 99.98, 99.98, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdditj1nn50yfc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F18350876830', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
