INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697778596', 'Torneira Para Lavatório De Parede Lotus Cromada Celite', 'Os produtos da Celite estão na memória e na rotina do brasileiro desde 1941, oferecendo o que há de melhor quando o assunto é metais e louças. Conheça mais um produto marcante da Celite: Torneira De Parede da Linha Lotus SOBRE A FABRICANTE: A Celite acompanhou a velocidade do dia a dia, aprendendo com a história e se conectando com o futuro. É atenta não só a realidade do mundo atual, mas também compreende o comportamento dos brasileiros. Combina espírito jovem e credibilidade dos consumidores que a acompanham há tempos.', 518.9, 518.9, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/sg-11134201-7rdwy-m04s6n1sglvec9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1225401015%2F22697778596', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
