INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193594390', 'Kit Marmita Harry Potter', 'Depois de um dia cheio de aventuras aprendendo novos feitiços, você quer dar uma mãozinha pra o seu filho na hora do lanche? A gente te ajuda! Com um kit que contêm um copo e uma marmita, ele nunca vai ficar na mão na hora de combater a barriguinha roncando! Não importa se é na escola ou em casa, esse kit te acompanha em todas as aventuras! O produto é importado, feito em plástico e silicone, possui detalhes incríveis que vão fazer você e seu filho se apaixonarem! Com uma marmita que contém 620ml, uma tampa que evita vazamentos na lancheira, e um talher, além de poder ir ao micro-ondas por até 2 minutos! E para acompanhar o lanche, nada melhor que um suco bem fresquinho! Com um copo que conta com 500ml e uma alça para te acompanhar enquanto corre pelos corredores de Hogwarts, além de conter um canudo em silicone! A hora do intervalo nunca mais será a mesma com esse kit! Especificações: Marmita: Altura: 7,5cm| Largura: 14,5cm| Comprimento: 6,5cm| Capacidade: 620ml| Material: Plástico e silicone Copo: Altura: 18,5cm| Largura: 5cm| Comprimento: 5cm| Capacidade: 500ml| Material: Plástico e silicone Cuidados e recomendações de uso: Não preencha com líquidos até a superfície, deixe pelo menos 1,5cm de espaço para poder fechar o copo. Choques ou quedas podem trincar ou quebrar o produto. Não é a prova de pequenos vazamentos, carregue o produto apenas na posição vertical e não coloque em bolsas ou mochilas. Lavar com água, esponja macia e sabão neutro. Não recomendado colocar no freezer. Não vai ao micro-ondas. Não utilizar produtos químicos e abrasivos.', 104.9, 104.9, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-822zz-mi0beq3qc4jp84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404743073%2F23193594390', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193179587', 'Bolsa Eu Amo Gato – Zonacriativa', 'Se você vive a correria do dia a dia e precisa de uma bolsa que acompanhe seu ritmo, essa shoulder bag é ideal para você! Se você é uma pessoa que ama gatinhos e carrega um monte de coisinhas que não consegue viver sem elas, essa vai ser a sua melhor companhia para a semana! O produto é nacional, feito em tecido sintético. possui detalhes incríveis que vão fazer você se apaixonar! Com um compartimento principal com fechamento em zíper, conta com um bolso, para você carregar tudo o que quiser! Com uma alça ergonômica, é confortável para você levá-la para todos os lugares! Feita em tecido sintético, é uma excelente companhia para a sua semana, te acompanha no trabalho, faculdade e rolê! Não importa onde é a aventura, essa bolsa te acompanha em todos os lugares! Especificações: Altura: 31cm| Largura: 41cm| Comprimento: 16cm| Bolsos: 1|Material: Tecido sintético Cuidados e recomendações de uso: Lavagem manual. Proibido alvejar. Não secar em tambor. Não passar. Não lavar a seco.', 149.9, 149.9, NULL, 'Men Bags > Backpacks', 'https://cf.shopee.com.br/file/sg-11134201-823pd-mohd3w2pshe19f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404743073%2F23193179587', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
