INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23994936418', 'Linguiça Calabresa Seara', 'A Linguiça Calabresa Seara é feita com carnes nobres selecionadas e defumada naturalmente, garantindo um sabor autêntico e um tempero marcante com pimenta calabresa. Ideal para o feijão e para diversas receitas! * Experimente fatiar e adicionar em um macarrão ao sugo. * Prepare um delicioso arroz de carreteiro. * Utilize em molhos para pizzas ou como petisco.', 15.49, 15.49, NULL, 'Food & Beverages > Fresh & Frozen Food > Meat', 'https://cf.shopee.com.br/file/sg-11134201-81zus-miyqbkt58tfnbb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554820%2F23994936418', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
