INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21799579057', 'Lona 2x2 Branca Forte Reforçada 150 Micras TNT para Piscina, Toldo, Cobertura', 'Sobre este Produto: Lona TNT 2x2 Metros: Versátil e funcional, pode ser usada em ambas orientações, sendo perfeita para diversas aplicações. Material: Polietileno tecido e revestido, 150 micras de espessura Resistência: Bordas reforçadas e costuras seladas com calor para maior durabilidade. Ilhoses de Alumínio à Prova de Ferrugem: Distribuídos a cada 1 metro para fixação segura. Prático e Durável: Lavável, reutilizável e fácil de armazenar. Uso Recomendado: Ideal para coberturas de emergência, proteção de materiais e equipamentos em ambientes fechados ou ao ar livre, eventos, camping e mais. Marca: TNT Cuidados: Limpar apenas com sabão neutro e esponja macia. Evitar contato com materiais pontiagudos. Assegurar que todos os ilhoses sejam utilizados para distribuir o peso e tensão uniformemente.', 74.85, 29.9, NULL, 'Home & Living > Tools & Home Improvement > Shades, Awnings & Tarpaulins', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m4z98r777n9he9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1064710210%2F21799579057', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23499037555', 'Alavanca Passador Absolute 12v Wild 2 1x12v Direito Mtb', '========================= SOBRE O VENDEDOR - Avelar Shop ========================= Presentes no mundo do ciclismo há 25 anos, 15 deles em competições esportivas e 10 como lojista, temos um grupo composto por 4 lojas físicas, Bike Shop Avelar Drumond, BH Concept, Avelar Shop e Bike Light, localizadas em Conselheiro Lafaiete/MG e Belo Horizonte/MG. Somos representantes das principais marcas de ciclismo do mercado e enviamos para todo o Brasil. Nossos envios acompanham nota fiscal e nossos produtos têm as devidas garantias asseguradas com os fornecedores/distribuidores oficiais das marcas. Além das lojas de Bicicletas, temos a empresa Avelar Sports, uma das líderes do país em locação de estruturas e organização de eventos. Vencedora do prêmio Guidom de Ouro 2019 com o evento "Internacional Chaoyang Estrada Real". =============== ESPECIFICAÇÕES =============== O design ergonômico do trocador facilita ajustes rápidos em diferentes tipos de terreno, garantindo um acionamento confortável que diminui a fadiga em longas distâncias. Alcance a velocidade desejada de forma rápida com um baixo consumo de energia; Garante maior durabilidade e desempenho consistentes; Leve, com apenas 136 gramas (com cabo); Design ergonômico que facilita ajustes rápidos. =============== CARACTERISTICAS =============== - Marca: Absolute; - Modelo: Wild 12v; - Lado: Direito [câmbio traseiro]; - Material: Alumínio e Polímero Termoplástico; - Velocidades: 12 (1x12); - Peso aproximado: 136 gramas (com cabo). - Produto original ABSOLUTE; - Importado por ISAPA; - Garantia de 90 dias; OBSERVAÇÃO: Fotos meramente ilustrativas. As especificações estão sujeitas a alterações sem aviso prévio, podendo variar com base na disponibilidade de componentes e outros fatores. ================ ENVIO DO PRODUTO ================ Seu produto será enviado em ATÉ 24 horas úteis após a confirmação do pagamento. =========== NOTA FISCAL =========== Todos os nossos produtos são enviados com nota-fiscal em seu nome e via transportadoras Mercado Livre ou parceiras. ==== SAC ==== O suporte ao cliente é um dos nossos compromissos! Após a aprovação da compra pelo Mercado Livre você terá acesso aos nossos contatos, e poderá contar com todo o apoio da nossa equipe de atendimento.', 159.0, 142.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-825a7-mg5cuvwg49aj02', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1640908297%2F23499037555', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
