INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56756387841', 'Pilha De Zinco AAA Com 4 Unidades Multi - PZ002', 'Pilha de Zinco AAA com 4 Unidades Multi - PZ002 Energia para o dia a dia com máxima economia. As Pilhas de Zinco AAA Multi PZ002 oferecem energia estável e confiável para aparelhos de uso diário e baixo consumo. Ideais para controles remotos, relógios e lanternas simples, garantem funcionamento eficiente com excelente custo-benefício. Com vida útil de até 3 anos, possuem composição antivazamento e são livres de mercúrio e cádmio, trazendo mais segurança para sua família e para o meio ambiente. Principais Benefícios: - Energia estável: ideal para uso diário. - Indicada para eletrônicos simples: controles e relógios. - Vida útil de até 3 anos: mais durabilidade. - Composição antivazamento: proteção extra. - Livre de metais pesados: mais segurança ambiental. - Excelente custo-benefício: economia garantida. Ficha Técnica Marca: Multi Modelo: Pilha De Zinco AAA Com 4 Unidades Multi - PZ002 Tipo: Pilha de Zinco Tamanho: AAA Quantidade: 4 unidades Vida útil: Até 3 anos Composição: Livre de mercúrio e cádmio Indicação de uso: Aparelhos de baixo consumo Garantia: 3 meses Imagens meramente ilustrativas.', 20.49, 19.9, NULL, 'Home Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-8262q-ml3r78y7x5a8e0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F389315825%2F56756387841', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44511336849', '30 Uni Forminha Flor De Lótus Azul Para Doces Finos', 'A Forminha de Plástico Flor de Lótus Azul Translúcida 30 Unidades Mirandinha chega para confeiteiras que querem dar aquele toque sereno e refinado nas produções, com o desenho delicado de pétalas abertas em flor abraçando cada brigadeiro como se fosse uma joia exposta. O tom azul translúcido tem aquela leveza de céu de manhã clara, que combina com qualquer mesa que peça calma, suavidade e elegância sem chamar atenção em excesso, deixando o doce ser o protagonista absoluto da apresentação. É a embalagem certa pra quem produz com olhar de quem entende que detalhe pequeno é o que separa a confeitaria amadora da profissional. Confeccionada em PS resistente e atóxico de alta qualidade, é leve, segura para contato com alimentos e mantém a forma original durante toda a exposição na mesa de doces, sem deformar, sem perder o brilho e sem encolher com o passar das horas. Com diâmetro de aproximadamente 2 cm e altura de 0,4 cm, foi pensada na proporção exata pra acomodar com perfeição um brigadeiro pequeno ou médio, valorizando o doce visualmente e criando aquele efeito de moldura que faz toda a diferença na fotografia da mesa montada e nas postagens das redes sociais. O tom azul abre portas pra uma infinidade de temas: chá de bebê de menino, batizado, festa marinheiro, fundo do mar, sereia, Frozen, espacial, futebol de time azul, casamento em paleta serena, despedidas de solteiro e qualquer celebração que peça aquela atmosfera suave de tranquilidade. A translucidez deixa a luz atravessar as pétalas criando reflexos azulados nas mesas montadas, dando aquele efeito de joia em vitrine que valoriza o capricho da confeiteira. Material: PS (poliestireno) Cor: Azul translúcida Modelo: Flor de Lótus Dimensões: 2 x 1,4 x 0,4 cm Conteúdo da embalagem: 30 unidades Código Fornecedor: 4343009', 46.71, 35.5, NULL, 'Home & Living > Party Supplies > Others', 'https://cf.shopee.com.br/file/sg-11134201-823r4-moskdjm75pn3c7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1507942655%2F44511336849', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
