INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206081455', 'Kit 3 Unidades Tempero SABOR A MI® Alho e Sal 300G', 'Sabor A Mi® Alho e Sal é um tempero completo à base de alho natural e sal, foi desenvolvido para trazer mais sabor e praticidade às receitas do dia a dia. O produto dispensa o uso de sal adicional e não contém conservantes, permite temperar os pratos na quantidade ideal, garantindo sabor consistente e controle no preparo. Utilização: - 1 colher de chá (5 g) tempera até 500 g de alimento; - Substitui o sal comum diretamente nas receitas; - Pode ser aplicado diretamente em carnes, legumes, marinadas, sopas, molhos e arroz; - Ideal para uso em alimentos crus ou durante o preparo térmico. Condições de armazenamento Manter em local seco, arejado e ao abrigo da luz. Após aberto, manter a embalagem bem fechada.', 23.58, 23.58, NULL, 'Food & Beverages > Cooking Essentials > Seasonings & Condiments', 'https://cf.shopee.com.br/file/sg-11134201-8262c-mlc4xget0t1f78', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1598062483%2F58206081455', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
