INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597314631', 'KIT 10~40 TOALHAS FESTA JUNINA PLÁSTICA DE MESA PARA CONVIDADOS LISA OU XADREZ 78X78 CM (CHOCO)', 'KIT COM 10 A 40 TOALHAS PLÁSTICAS DE MESA 78X78CM – MODELO LISO OU XADREZ PARA FESTAS, EVENTOS E USO DIÁRIO 🎉 PRATICIDADE E ECONOMIA PARA SUA FESTA OU NEGÓCIO! 📐 MEDIDAS: 78X78 CM (IDEAL PARA MESAS DE CONVIDADOS) 🎨 OPÇÕES DE ESTAMPA: LISA OU XADREZ – ESCOLHA SUA PREFERIDA! AS TOALHAS PLÁSTICAS DESCARTÁVEIS SÃO PERFEITAS PARA DECORAR COM PRATICIDADE, ECONOMIZANDO TEMPO E FACILITANDO A LIMPEZA. IDEAIS PARA ANIVERSÁRIOS, CHÁ DE BEBÊ, EVENTOS ESCOLARES, IGREJAS, BARRACAS DE COMIDA, FESTAS TEMÁTICAS E MUITO MAIS! ✅ MATERIAL PLÁSTICO FLEXÍVEL, LEVE E IMPERMEÁVEL ✅ COBRE BEM MESAS DE ATÉ 80X80 CM ✅ USO ÚNICO – MAIS HIGIENE E MENOS TRABALHO ✅ ESTAMPAS QUE COMBINAM COM QUALQUER TEMA OBSERVAÇÃO: PRODUTO ENVOLVIDO EM PACOTES COMPACTOS PARA FACILITAR O ENVIO. ESCOLHA A QUANTIDADE E ESTILO NO MOMENTO DA COMPRA! 🛒 GARANTA JÁ SUAS TOALHAS E DÊ UM TOQUE ESPECIAL À SUA FESTA COM ECONOMIA E ESTILO!', 23.85, 23.85, NULL, 'Home & Living > Decoration > Table Cloths', 'https://cf.shopee.com.br/file/br-11134207-7r98o-luhxfm1km0rp0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F23597314631', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20897460460', 'Rolo De Papel Alumínio 45 Cm X 65 Metros GRANDE VABENE (CHOCO)', 'Descrição: O rolo de Papel Alumínio da vabene foi desenvolvido para uso em fornos e churrasqueiras em residências, cozinhas industriais, restaurantes, lanchonetes, indústrias e tambem muito utilizado por cabeleireiros para fazer mechas em cabelo. Item fundamental na cozinha, a folha de alumínio serve tanto para armazenar quanto para grelhar alimentos. Vai do forno ao congelador suportando altas temperaturas e um congelamento extremo. Isso porque o alumínio é um produto muiro versátil e flexível, conduz bem o calor e serve para proteger, conservar e preparar os alimentos quentes e frios. Quantidade: 1 rolo Largura: 45cm Comprimento: 65m Espessura: 9µ (micras) Peso: 900g', 78.85, 49.85, NULL, 'Home & Living > Kitchenware > Aluminium Foil', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ln1b49nwx5qb62', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F20897460460', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50555830500', 'Palmeira Areca Artificial Realista com Pote Planta Decorativa 90cm e 110cm', 'Quer trazer sensação de frescor e amplitude sem complicação? A Palmeira Areca artificial é daquelas plantas que mudam o clima do ambiente na hora. Com folhas longas e volumosas, ela ocupa espaço com leveza, criando um visual tropical elegante sem exigir luz, água ou qualquer tipo de manutenção. Por que você vai amar • Planta de chão com presença forte e visual leve • Folhagem volumosa que preenche espaços grandes • Ideal para quem quer impacto sem manutenção • Acompanha pote preto, pronta para usar Onde você pode usar • Ao lado do sofá ou rack, preenchendo áreas amplas sem pesar na decoração • Em cantos de salas grandes ou integradas, quebrando o vazio e trazendo movimento • Em escritórios, recepções ou salas de espera, posicionada próxima a paredes ou vidros • Em varandas cobertas ou espaços comerciais, criando sensação de ambiente mais fresco e acolhedor Características do produto • Produto: Palmeira Areca / Areca-bambu artificial • Material das folhas: plástico • Acompanha pote preto de plástico Modelos disponíveis: • Palmeira Areca – 110 cm de altura x 65 cm de largura Composição: 2 troncos com folhas • Areca-bambu – 90 cm de altura x 23 cm de largura Cuidados • Limpar periodicamente com espanador • Não utilizar produtos químicos ou abrasivos Informações importantes • Planta enviada montada • Produto embalado em caixa de papelão e protegido • Imagens meramente ilustrativas • Pode haver variação de tonalidade conforme a tela do dispositivo Um detalhe que faz toda a diferença na decoração. Dê vida a sua casa, boas compras!', 369.9, 244.9, NULL, 'Home & Living > Gardening > Plants', 'https://cf.shopee.com.br/file/br-11134207-820ly-mpo0pc778lxeaf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1474606866%2F50555830500', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
