INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193009519', 'Filtro De Cabine Ar Condicionado Corolla 2003 À 2006 Com Spray Higienizador | Bosch 0986BF0557', 'Bem-vindo(a) à nossa loja! Itens inclusos: 1 Filtro de Cabine Bosch 1 Spray Higienizador Orbi 200ml CÓDIGOS SEMELHANTES 0986BF0557 0986BF0556 FB810 CF9686 LA395 CU2035 MP034 ACP886 8713902150 AKX1963 Filtro de Ar Condicionado Bosch + Higienizador Orbi Spray 200ml Garanta um ar mais puro e saudável dentro do seu carro com o Filtro de Cabine Bosch e deixe tudo com cheirinho de novo usando o Higienizador Orbi! Benefícios do Filtro Bosch: - Filtra até 100% das impurezas: pó, pólen, fuligem, bactérias e até amianto! - Ajuda a proteger o sistema de ar do seu carro (ventiladores, painel, dutos etc.). - Maior resistência à umidade e à formação de micro-organismos. - Aplicação específica para cada modelo de veículo (confira a compatibilidade). Sobre o Higienizador Orbi (200ml): - Fácil aplicação com válvula tipo granada. - Elimina odores e ajuda na higienização interna do ar-condicionado. Modo de uso rápido (Spray): 1 - Ligue o carro e o ar-condicionado no modo recirculação interna. 2 - Direcione a ventilação para o para-brisa. 3 - Posicione o spray no assoalho do passageiro (sob o porta-luvas). 4 - Pressione a válvula até travar, saia do carro e feche todas as portas. 5 - Aguarde 15 minutos com o carro ligado e depois mais 10 minutos com ele desligado. 6 - Por fim, abra portas e janelas para ventilar. Pronto! Recomendações de troca do filtro: A cada 10.000 km, 1 vez ao ano, ou conforme orientação da montadora. APLICAÇÕES Toyota Corolla 1.6 - 1997 a 2008 Corolla 1.8 - 1992 a 2007 Yaris 1.3 Após 2018 • GARANTIA Colocamos à disposição nossa equipe para informar as etapas corretas de entrada no processo de garantia de acordo com as recomendações do fabricante. • As INFORMAÇÕES técnicas apresentadas no anúncio são de acordo com a aplicação repassada pelo fabricante do mesmo. • Recomendamos sempre que toda e qualquer instalação seja realizada por profissionais especializados para evitar problemas futuros, pois não somos responsáveis pela má instalação ou mau uso do produto. • 100% Original com nota fiscal.', 39.1, 39.1, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lv1ypj16a2zt32', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816129267%2F22193009519', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
