INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43826197363', 'Jogo Infantil Educativo Encontre as Palavras Diversos Sopecca - ES15', 'O Encontre as Palavras Diversos da Sopecca é um jogo educativo em MDF com 24 peças, recomendado para crianças a partir de 6 anos. Com ilustrações coloridas e palavras variadas, o jogo auxilia no desenvolvimento da leitura, escrita e reconhecimento de palavras. É seguro e durável, proporcionando aprendizado de forma divertida. Especificações: - Material: MDF 6 mm - Idade recomendada: a partir de 6 anos - Quantidade de peças: 24 unidades - Tamanho da embalagem: A 4,5 x L 14,5 x C 13 cm - Produto certificado pelo INMETRO Características: - Marca: Sopecca - Modelo: ES15 Imagens Meramente Ilustrativas Conteúdo da Embalagem: - 24x Peças', 19.0, 16.57, NULL, 'Mom & Baby > Toys > Others', 'https://cf.shopee.com.br/file/sg-11134201-821fu-mgqtzg61hy4u25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F43826197363', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3013108059', 'Suporte ferro c/ Jardineira Bege Pendurar Plantas Jardim', 'Suporte com Jardineira cor Amêndoa para Jardim Vertical O jeito mais fácil de colocar suas floreiras e jardineiras no seu jardim vertical Basta encaixar o suporte no seu Painel (Ou Treliça, se preferir chamar assim), e colocar a jardineira em cima. Está pronto! Se atente ao tamanho: 10cm Altura x 15 cm Largura x 29cm', 79.9, 79.9, NULL, 'Home & Living > Gardening > Garden Decorations', 'https://cf.shopee.com.br/file/30c59e5a5043e4c06acbec98a1026735', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F306698991%2F3013108059', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42950896939', 'Cross Mol Finisher Shampoo Automotivo Limpeza Pesada 580ml', 'CROSS MOL 580ML FINISHER Detergente flotador de ação neutra para pré-lavação sem toque. Desenvolvido para pré-lavar superfícies, sem que seja feita a esfregação, em veículos de passeio, off-road, maquinário e aeronaves. Possui pH levemente alcalino com ação neutra, não agredindo materiais sensíveis. DILUIÇÃO: De acordo com a sua necessidade, dilua 1 parte do produto para 10 a 100 partes de água MODO DE USO: 1. Com a superfície seca, pulverize o produto sobre toda a área desejada e espere agir de 2 a 3 minutos, para que as partículas sejam flotadas 2. Faça o enxágue com um jato d’água de alta pressão, removendo completamente o produto e a sujidade mais grossa 3. Em seguida, aplique o Cross Mol novamente ou outro produto para fazer a esfregação', 54.92, 54.92, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Shampoo', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9rbfi0jqyo2db', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F42950896939', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21099194687', 'Extractus Limpador Ultra Concentrado 1,5L Limpa Estofados Vonixx', 'EXTRACTUS 1,5L - LIMPADOR ULTRA CONCENTRADO DESCRIÇÃO: Extractus é um limpador ultra concentrado de alta performance e baixa espumação, desenvolvido para limpeza profissional de estofados, carpetes e tapetes. Seu uso é indicado em extratoras. Sua fórmula contém tensoativos e alcalinizantes especiais que removem facilmente os mais diversos tipos de sujeira, em especial as derivadas de graxa, suor e gorduras em geral. DILUIÇÕES: Sujeira pesada – 1:10 Sujeira média – 1:30 Sujeira leve – 1:60 MODO DE USO: 1. Diluir o produto na proporção ideal de acordo com o nível de sujeira 2. Pulverizar uma fina névoa do produto, mantendo distância entre 20cm a 30cm da superfície, a fim de evitar encharcamento do estofado ou carpete 3. Aguardar 2 minutos 4. Utilizar escova macia e realizar a esfregação para auxiliar no desprendimento da sujeira 5. Realizar a extração ou aspiração sem enxágue 6. Realizar uma segunda extração, dessa vez com enxágue', 44.48, 44.48, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lr7obk2nbm7861', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F21099194687', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
