INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194514865', 'VINHO TINTO SANTA HELENA MERLOT 750ML', 'O Vinho Santa Helena Reservado Merlot usa métodos de produção inovadores, garantindo máxima qualidade, resultando em fantásticas bebidas que exalam o melhor sabor das uvas. Criado em uma das maiores vinícolas chilenas com mais de 70 anos de história, possui cor vermelho intenso e aromas de ameixas, especiarias e menta, revelados em um paladar que combina a estrutura da Cabernet Sauvignon com o final frutado da Merlot. Corpo médio e final persistente. País: Chile Teor alcoólico: 13% Volume: 750ml Região: Vale Central', 41.9, 29.49, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/sg-11134201-824i0-mfo287lv9c0e90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1605305232%2F23194514865', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
