INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18099078467', 'Mini Prendedor Grampo Colorido Pregador Madeira 50 Und P/ Artesanato Lembrancinhas Fotos Bebidas Drinks', 'Olá, Bem vindo a Distribuidora Brester. Trabalhamos com uma grande variedade de ferramentas elétricas e manuais, descartáveis, eletroeletrônicos, artigos para casa, artigos de petshop e outros. Aqui você encontrará Produtos Originais, Nota Fiscal, Pronta Entrega e Envio Imediato! * Características do produto * Mini Prendedor Handy 50 Peças Western Apresentamos a você o Mini Prendedor Handy 50 Peças. A solução perfeita para tornar sua vida mais organizada e prática! Sabemos como é desafiador manter tudo organizado. Papéis espalhados, fotos desorganizadas... Mas não se preocupe! O Mini Prendedor veio para resolver esse problema de forma simples e eficiente. Características do Produto: > Cores diversas; > Material: madeira; > Podem ser utilizados em trabalhos manuais como: scrapbook, artesanato, lembrancinhas, festas infantis e drinks. Especificações Técnicas: > Dimensões do Produto: - Comprimento: 2,5 cm; - Largura: 0,5 cm; - Altura: 1,0 cm. - Marca: Western - Garantia: 90 dias contra defeitos de fabricação Vantagens de comprar na Brester: - Nota fiscal para Pessoa Física e Pessoa Jurídica; - Produto novo, com garantia de fábrica; - Produto a pronta entrega; - Envio em até 24hs em dias úteis após confirmação do pagamento. Obrigado por escolher a Brester Máquinas.', 20.43, 17.98, NULL, 'Home & Living > Party Supplies > Wooden Clips', 'https://cf.shopee.com.br/file/sg-11134201-7rblg-lpglassl3ntj97', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442506479%2F18099078467', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22891414540', 'Bitterpet Duprat Spray Educador Amargo para Cães - 140 mL', '- Desencoraja a automutilação e arrancamento de penas; - Ação hidratante atóxica; - Eficaz contra coprofagia; - Auxilio no desmame; Detalhes O Spray Educador Duprat Bitterpet foi desenvolvido para desencorajar a automutilação em cães, gatos, ferrets e roedores, além do arrancamento de penas em aves ornamentais. O produto também combate a coprofagia e auxilia no desmame. Sua fórmula hidratante e emoliente atóxica deve ser aplicada na derme do animal. Dicas Especiais - Não aplicar o produto na região dos olhos, bocas, mucosas, narinas ou bicos. - No caso de aves, se destina exclusivamente a aves ornamentais e canoras; - Manter o produto na embalagem original, em local seco, fresco, ao abrigo da luz solar e fora do alcance de crianças e animais domésticos; - Não reutilize a embalagem; - Não guarde ou aplique junto a alimentos, bebidas, medicamentos, produtos de higiene ou cosméticos.', 47.86, 35.9, NULL, 'Pets > Pet Healthcare > Vitamins & Supplements', 'https://cf.shopee.com.br/file/sg-11134201-7qvg8-lhmsnr1hlej1bb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F22891414540', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498188218', 'Cortina para Box Banheiro Cortina Box em PVC Vinil Para Banheiro Anti Mofo com Ganchos', 'A Cortina para Box de Banheiro em PVC Vinil é a solução ideal para quem busca praticidade, resistência e estilo no ambiente. Com 1,80m de altura e 1,75m de largura, ela se adapta perfeitamente à maioria dos boxes, oferecendo uma proteção eficaz contra respingos e mantendo a área do banho sempre seca. Sua **fabricação em PVC vinil** garante resistência à água e facilidade na limpeza, além de ser **anti mofo**, prevenindo o surgimento de bolores e odores desagradáveis. A cortina acompanha **ganchos**, facilitando a instalação e proporcionando maior durabilidade. Com design simples e funcional, ela agrega praticidade e sofisticação ao seu banheiro. 180cm x 175cm', 39.9, 19.9, NULL, 'Home & Living > Bathrooms > Shower Curtains', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5y8zkyfjeeq1f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F23498188218', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
