INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198216712', 'Chaveiro Mochila Bubba com 3 Mini-Squish - Squish a Longs', 'Descrição: "A nova linha de Squish A Longs chegou, trazendo uma fofura sem igual e uma diversidade incrível em seus produtos, garantindo que a diversão seja interminável! Com os novos chaveiros de Squish A Long, você pode exibir seu estilo único e fofo de uma maneira completamente nova e encantadora! Além de ser adorável e bonita, esse item Squish A Long é extremamente funcional, permitindo que você carregue vários squish a longs com facilidade e estilo. Personalize sua mochila com os chaveiros Squish A Longs e esteja sempre preparado para qualquer aventura, adicionando um toque de fofura ao seu dia. Seja único, seja fofo, seja você com os novos chaveiros de Squish A Long - uma maneira perfeita de expressar sua personalidade e amor pela diversão!" Características: Marca: Sunny Brinquedos Referência: 4291 Idade recomendada: A partir de 3 anos Pilhas Inclusas? Tipo de Pilha/Bateria Não necessita de pilhas Possui Luzes: Não Possui Sons: Não Dimensões aproximadas da embalagem: 10,8 x 9 x 4,2cm (A x L x C) Garantia: 3 meses a contar da emissão da Nota Fiscal Embalagem: Conteúdo da embalagem: 1 Chaveiro Mochila e 3 Mini-Squish Surpresa Certificado Inmetro: REGISTRO 011978/2024 Produtos de decoração não inclusos. Imagens meramente ilustrativas. As cores dos objetos podem sofrer alterações devido a luminosidade, configurações do monitor e até mesmo a percepção do usuário.', 69.99, 65.79, NULL, 'Hobbies & Collections > Souvenirs > Keychains', 'https://cf.shopee.com.br/file/sg-11134201-7rced-m6fnsewkwfeaf7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341622697%2F23198216712', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251686773', 'Tênis de Academia Treino Crossfit Tribase Reps 2 SE Unissex Confortável - Under Armour', 'Tênis de Academia Unissex Tribase Reps 2 SE – Under Armour Estabilidade e suporte para treinos de alta performance. O Tribase Reps 2 SE da Under Armour foi criado para quem busca máxima firmeza em cada repetição, oferecendo uma base sólida e responsiva para treinos funcionais, musculação e academia. Sua entressola em espuma Micro G transforma pousos sutis em impulsões explosivas, garantindo desempenho dinâmico e eficiente. Cabedal respirável com estrutura reforçada. Confeccionado em gáspea knit bicolor 100% poliéster, o modelo combina flexibilidade e suporte, moldando-se ao pé com leveza. A língua em tecido dupla frontura aumenta a ventilação e o conforto, enquanto a vista de atacador em TPU reforça a estabilidade lateral. O atacador achatado mantém o ajuste firme, ideal para transições rápidas durante o treino. Base firme e segurança em todos os movimentos. A sola com tecnologia TriBase maximiza o contato com o solo, oferecendo estabilidade superior em exercícios que exigem força e precisão. O forro em poliéster com espuma e a palmilha anatômica em EVA de 4 mm proporcionam conforto contínuo, evitando deslizamentos e garantindo foco total no treino. Uma combinação ideal entre potência, estabilidade e suporte profissional. Especificações Marca: Under Armour Modelo: Tribase Reps 2 SE Indicação: Academia / Treinos Cabedal: Knit bicolor 100% poliéster Entressola: Espuma Micro G Sola: Tecnologia TriBase Palmilha: Anatômica em poliéster + EVA (4 mm) Forro: Poliéster com espuma Vista de atacador: Laminado TPU Cadarço: Monocolor achatado Língua: Tecido dupla frontura', 529.9, 352.38, NULL, 'Sports & Outdoors > Sports Footwear > Training Shoes', 'https://cf.shopee.com.br/file/br-11