INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50851007079', 'Kit 4 Desinfetantes Pinho Sol Naturals Lavanda e Melaleuca 1,75L', 'O Kit Contém: 4 Desinfetantes Pinho Sol Naturals Lavanda e Melaleuca com 1,75L cada unidade. Desinfetante Pinho Sol Naturals Lavanda e Melaleuca 1,75L A marca de desinfetante que você já conhece e confia traz mais uma solução para cuidar da sua casa e do planeta. Pinho Sol Natural Essentials é um desinfetante com ativos biodegradáveis e fragrância com extratos naturais em sua fórmula, além de embalagem 100% recivável, tudo isso sem deixar de eliminar até 99,9% dos germes e bactérias. *Compre Produtos Pinho Sol.', 112.55, 74.64, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-821ez-mgsfujwahmve45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557242410%2F50851007079', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52756306755', 'Caixa 24un Pinati Sweet Cocada Chocolate Branco 14G', 'Experimente o Sweet Cocadinha com Chocolate Branco da PINATI: um doce de coco macio e delicioso, coberto com chocolate branco sem adição de açúcares e totalmente sem glúten. Ideal para quem quer um docinho saboroso sem abrir mão do equilíbrio na alimentação.Feito com coco ralado selecionado e adoçado naturalmente com xarope de maltitol, cada mordida combina sabor intenso e textura macia. Perfeito para lanches, sobremesas ou pequenos momentos de indulgência no dia a dia.Benefícios do Sweet Cocadinha:Sem glútenSem adição de açúcaresBaixo em açúcares e sódioTextura macia e sabor irresistível de coco com chocolate brancoAtenção: contém derivados de leite e lactose. Pode conter traços de castanhas, amendoim, aveia, soja e ovos.Validade: 12 meses | Conservação: local seco e fresco, ao abrigo do sol. Após aberto, consumir imediatamente.', 101.48, 81.53, NULL, 'Food & Beverages > Snacks > Sweets & Candy', 'https://cf.shopee.com.br/file/sg-11134201-8261z-mkybiatde9dxac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F590473480%2F52756306755', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22892828692', '4 Cabo Rca Y 2 Macho 1 Femia 2M1F Stetsom Banhado Ouro Audio Automotivo', '4 Cabo Rca Y 2m1f Stetsom Banhado Ouro Audio/video Automotivo - Stetsom: A conexão é a base do seu som automotivo, então não brinque em serviço. Escolha a qualidade do cabo RCA da Stetsom para ligar o seu sistema com excelente cancelamento de ruídos e maior limpeza no sinal transmitido. No modelo duplo com 5m de comprimento e bitola de 2mm², o cabo RCA possui plugs de alta pressão banhados à ouro, dando mais segurança para a ligação. Protegendo o condutor interno de cobre, o cabo da Stetsom possui isolamento dielétrico, dupla blindagem e revestimento em silicone transparente com detalhes vermelho e branco, tanto no isolamento interno, quanto para identificar os conectores. Especificações Técnicas: - Revestimento em Silicone Transparente com Isolamento Interno Vermelho - Cabo RCA Duplo - Condutor Interno de Cobre - Plugs Banhados á Ouro - Excelente Isolamento Dielétrico - Dupla Blindagem - 2mm² de Bitola - Perfeito no Cancelamento de Ruídos - Ideal para Som Automotivo Itens inclusos: 4 cabo y 2m1f', 74.02, 74.02, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lr7fhzip4ojff3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F414508631%2F22892828692', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397833098', 'Relógio Technos Masculino Golf Prata - 2115TXP/0P', 'Relógio Technos Golf com vidro abaulado e elegante pulseira de couro legitimo na cor marrom. Seu mostrador preto apresenta números arábicos grandes nas posições de 3/6/9/12 horas e assinatura de linha diferenciada. Produto 100% em aço inoxidável, com máquina quartz japonesa Miyota, calendário e resistência à água de 50 metros. Tamanho de caixa 44mm.', 570.0, 539.0, NULL, 'Watches > Men Watches', 'https://cf.shopee.com.br/file/sg-11134201-824hz-mpmjxuuswf0t5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1332527814%2F23397833098', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20198107993', 'Relógio Technos Masculino Slim Bicolor - GM10YX/1A', 'Com caixa ultrafina, a linha Slim reinventa o conceito clássico da simplicidade para apresentar seu novo modelo, moderno e sofisticado, com pulseira de aço inoxidável em 5 links. Seu diferencial está na lente de safira, altamente resistente a riscos e arranhões. Produto 100% em aço inoxidável, com máquina quartz Japonesa Miyota e resistência à água de 50 metros.', 700.0, 700.0, NULL, 'Watches > Men Watches', 'https://cf.shopee.com.br/file/sg-11134201-825ap-mqvwm2vl4ow054', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1332527814%2F20198107993', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22695559925', 'Sofá Fixo Orfeu 3 Lugares Luxo 2,00m Castellar Móbile', 'SOFÁ ORFEU LUXO CASTELLAR MÓBILE Com um visual elegante e moderno, o sofá conta com detalhes que valorizam o seu ambiente. Composto com capa nos braços, a base inteira com pés delicados, almofadas e o assento com pillow top capitonê, esse tipo de móvel oferece um maior conforto e beleza. DIMENSÕES: - Altura: 90cm - Profundidade: 90cm - Comprimento: 200cm - Largura dos braços: 20cm (Cada) - Altura do assento: 45cm CARACTERÍSTICAS: - Tipo de assento: Assento com espuma D28 Soft no Pillow de 80 mm de espessura e manta acrílica de gramatura 200. Em cada assento são colocadas molas Bonnel o que proporciona maior conforto. - Tipo de encosto: Almofada solta com fibra 100% siliconada. -Base em eucalipto na cor castanho. - Quantidade de pés: 4 pés na base - Material da estrutura: Madeira reflorestada, seca e imunizada. - Almofadas decorativas incluídas INSTRUÇÕES DE CUIDADOS E LIMPEZA: - Nossos produtos são indicados para área coberta, a exposição ao sol ou chuva podem danificá-los - Para limpar, utilize um pano levemente umedecido, seguido de pano seco - Não utilizar escovas, produtos químicos ou semelhantes ATENÇÃO: - O anúncio contém imagens reais do produto mas a tonalidade pode variar de acordo com a tela utilizada ou iluminação no dia da foto. - Certifique-se que, de acordo com as dimensões do produto, o mesmo terá fácil acesso até o local de uso. Evite o transtorno para acessar elevadores ou escadas e a necessidade de serem içados ou desmontados.', 3010.9, 3010.9, NULL, 'Home & Living > Furniture > Sofas', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mevbw97i9c7579', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F309237167%2F22695559925', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13648773478', 'Escova Dental Sorriso Original Média', 'Escova dental de cerdas macias com limpador de língua. A Escova Sorriso Original, possuí cerdas com pontas arredondadas que limpam os dentes e massageiam a gengiva, limpando a língua e ajudando a remover as bactérias causadoras do mau hálito. Além de dispor de três tipos de cerdas, macia, média e dura, também conta com um cabo antiderrapante facilitando o manuseio e oferecendo mais firmeza na escovação.', 9.89, 9.89, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/fb0a928f720cfb2c6e143c93036a48ab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557242410%2F13648773478', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250010413', 'Par Grade Tela Proteção Alto Falante Subwoofer 12 Polegadas Com Garra e Parafusos Preta', 'A Tela de Proteção para Alto-Falante/Subwoofer 12 Polegadas foi desenvolvida para evitar impactos e danos ao cone do falante, preservando a durabilidade e mantendo a qualidade sonora. Seu modelo com garras de fixação proporciona instalação firme, prática e segura, acompanhando parafusos para montagem. Fabricada em plástico resistente, oferece excelente acabamento, leveza e alta durabilidade para aplicações em caixas automotivas, residenciais e profissionais. Modelos similares em polipropileno resistente são usados justamente pela baixa absorção de umidade e boa resistência mecânica. Especificações: - Compatível com alto-falantes/subwoofers de 12"; - Material plástico resistente; - Cor: Preta; - Sistema com garras de fixação; - Fácil instalação; - Excelente acabamento; - Protege contra impactos e contato direto. Itens Inclusos: - 04 Telas 12 Polegadas Plástica com Garra; - 08 Parafusos. Importante: - Valor do Par; - Imagens meramente ilustrativas; - Recomendamos que a instalação seja feita por profissional especializado, não nos responsabilizamos pelo mau uso do produto. SUBGRAVE A SUA LOJA DE ACESSÓRIOS AUTOMOTIVOS', 26.9, 26.9, NULL, 'Audio > Home Audio & Speakers > Others', 'https://cf.shopee.com.br/file/br-11134207-820m8-moiksgh3h6v73d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F414508631%2F58250010413', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43276279382', 'Espuma de Limpeza Dermotivin 130ml Galderma', 'Linha Espuma de Limpeza 130ml Dermotivin Dermotivin Soft Sabonete em Espuma – 130ml Perfeito para quem tem pele sensível ou delicada, o Dermotivin Soft é um sabonete em espuma que proporciona limpeza suave, sem causar irritações ou ressecamento. Com fórmula dermatologicamente testada, ele remove impurezas e oleosidade na medida certa, mantendo o equilíbrio natural da pele. Sua textura em espuma é leve, fácil de espalhar e proporciona uma sensação de frescor e conforto após o uso. Dermotivin Original Sabonete em Espuma – 130ml O Dermotivin Original é um sabonete em espuma especialmente formulado para a limpeza profunda de peles mistas a oleosas, ajudando no controle da oleosidade sem ressecar a pele. Com textura leve e fácil de aplicar, sua fórmula dermatologicamente testada remove impurezas, excesso de óleo e ajuda a prevenir cravos e espinhas, deixando uma sensação de frescor e pele limpa por mais tempo. Dermotivin Oil Control Sabonete em Espuma - 130ml O Dermotivin Oil Control é o sabonete líquido facial formulado especialmente para as peles muito oleosas. Com agentes refrescantes e efeito adstringente, limpa a pele e reduz o excesso de oleosidade e brilho, ajudando a prevenir o surgimento de cravos. Ainda, possui ação seborreguladora, que regula a produção excessiva de sebo. Tenha uma pele limpa, refrescante e hidratada com Dermotivin Oil Control: para cada pele, a expertise ideal. Dermotivin Salix Sabonete em Espuma - 130ml O Dermotivin Salix possui: Ação secativa antiacne, desobstrução dos poros e ácido salicílico. Recomendado para pele muito oleosa e acneica MODO DE USO: Aplique sobre a pele umedecida do rosto e áreas afetadas em suaves movimentos circulares. Enxágue por completo. Use de uma a duas vezes ao dia ou conforme orientação do seu dermatologista.', 94.9, 79.9, NULL, 'Beauty > Skincare > Facial Cleanser', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgwbig0cl0xs7c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1295597776%2F43276279382', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698008321', 'Kit 4 Cadeira de Jantar Alice Suede Cinza Madeira Estofados Mesa Sala de Jantar Cozinha', 'Sabendo que a cozinha é um dos ambientes mais movimentados da casa, apresentamos a Cadeira de Jantar Alice. Com um design moderno e linhas retas, ela é feita em madeira de eucalipto de alta qualidade, possui acabamento impecável, espuma de alta densidade e revestimento em tecido premium. Seu estilo versátil combina facilmente com qualquer mobiliário, agregando elegância e conforto à sua casa. Que tal aproveitar essa novidade e trazer mais sofisticação para o seu espaço? Dimensões do Produto: Altura total: 94 cm Largura total: 42 cm Profundidade total: 46 cm Altura do encosto: 46 cm Largura do assento: 42 cm Profundidade do assento: 40 cm Altura do chão ao assento: 48 cm Espessura do assento: 08 cm Altura dos pés: 35 cm Peso: 7 kg Especificações do Produto: Estrutura: Madeira Eucalipto Espuma: D23 Tipo de pés: Trapézio Peso suportado: 120 kg Garantia: 90 dias contra defeitos de fabricação Montagem: Produto vai montado, basta rosquear os pés Instruções de limpeza: Pano úmido com sabão neutro Conteúdo da embalagem: Pode ser enviado até 4 cadeiras em 01 volume (caixa) Observações Importantes: Todos os produtos são embalados com segurança para garantir sua integridade durante o transporte. As cores podem variar conforme as configurações do seu monitor. Para compras futuras, as tonalidades de cor podem diferir devido a variações de lote do tecido. As imagens são ilustrativas e não incluem objetos de decoração ou eletrodomésticos. Verifique as dimensões do produto para garantir que ele passará por escadas, elevadores, portas e corredores. As medidas podem apresentar variações de espessura por se tratar de estofados. A entrega não inclui serviços de montagem, desmontagem ou instalação de produtos. A entrega não contempla subir escadas, elevadores ou uso de guinchos para acesso a pisos superiores. A entrega é realizada em todo o território nacional, de acordo com a acessibilidade por rodovias; entregas fluviais ou aéreas precisam ser cotadas separadamente. Seguindo essas orientações, evitam-se contratempos com a entrega. Custos adicionais, caso ocorram, serão de responsabilidade do cliente. FAQ – PERGUNTAS FREQUENTES • O STATUS DO MEU PEDIDO APARECE COMO ENVIADO, MAS NÃO CONSIGO RASTREAR Após a confirmação da compra, todos os pedidos passam pelo nosso processo de produção. O prazo pode variar conforme o volume de pedidos e períodos de maior demanda, como datas comemorativas. Assim que o produto for despachado, o link de rastreamento será atualizado. Basta acessar o link disponibilizado para acompanhar o andamento da entrega. • ACABEI DE COMPRAR E COLOQUEI O ENDEREÇO ERRADO. PRECISO CANCELAR A COMPRA PARA ALTERAR? Não é necessário cancelar a compra. Conseguimos alterar o endereço em até 48 horas após a confirmação do pedido. Basta enviar pelo chat da sua compra o endereço completo com CEP para que possamos realizar a atualização. • QUAIS SÃO AS CORES E TECIDOS DISPONÍVEIS? No tecido Suede temos: Preto, Vermelho, Terracota, Bege, Azul Marinho, Rosa, Amarelo, Verde e Cinza. No tecido Linho temos: Bege, Grafite, Cinza, Azul Marinho, Preto, Terracota e Verde. No tecido Corino (pode haver diferença de valor): Bege, Marrom, Preto e Terracota. • VOCÊS FAZEM PRODUTOS COM MEDIDAS DIFERENTES DO ANÚNCIO OU PERSONALIZADOS? No momento, não fabricamos produtos sob medida e não realizamos personalização com outros materiais ou medidas diferentes das informadas no anúncio. • COLOQUEI MEU CEP E APARECE COMO ENDEREÇO NÃO SUPORTADO Infelizmente ainda não conseguimos realizar entregas em algumas regiões. Estamos trabalhando para ampliar nossa área de atendimento e, em breve, atender mais localidades em todo o Brasil.', 1507.9, 1507.9, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/br-11134207-820lr-mofuqlvphq8655', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1344250083%2F22698008321', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22599257476', 'Válvula Schrader 1/4" x 100mm com União de Solda VIX', 'Válvula Schrader 1/4" x 100mm com União de Solda VIX Válvula Schrader com União de Solda VIX 1/4" x 100mm – Eficiência e Praticidade em Sistemas de Refrigeração A Válvula Schrader com União de Solda VIX é um componente essencial em sistemas de ar-condicionado e refrigeração, facilitando os processos de carga e descarga de fluidos refrigerantes com máxima segurança e controle. Com tubo de cobre de 1/4" e 100mm de comprimento, essa válvula oferece vedação eficiente e resistência à pressão, sendo amplamente utilizada por técnicos em instalações, manutenções e recargas de gás em sistemas diversos. Principais Aplicações: - Sistemas de ar-condicionado (residenciais e comerciais) - Equipamentos de refrigeração (geladeiras, freezers, balcões frigoríficos) - Carga e descarga de gás refrigerante - Linhas de serviço em sistemas com R134a, R404A, R410A, entre outros Benefícios: - Compatível com solda: fácil de instalar em tubulações de cobre - Alta durabilidade: fabricada em material resistente, ideal para uso técnico intenso - Versatilidade: compatível com diferentes tipos de gás e compressores - Facilita a manutenção: permite acesso rápido ao sistema sem desmontagens complexas Especificações Técnicas: - Tipo: Schrader com união de solda - Material: Cobre - Medidas: 1/4” x 100mm - Marca: VIX - Aplicação: Refrigeração e climatização - Garantia: 3 meses Informação adicional: Ideal para profissionais de refrigeração que buscam agilidade, confiabilidade e segurança em seus serviços. Produto com pronta entrega e qualidade garantida.', 3.3, 3.3, NULL, 'Home Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-82619-mkz9x1865d6s53', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1323031590%2F22599257476', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
