INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198694767', 'Bomba Direção Hidraulica Vectra 8v 16v 1996 Ate 2005 Indisa', 'APLICAÇÃO: CHEVROLET: VECTRA 8V 1996 ATE 2005 VECTRA 16V 1996 ATE 2005 CARACTERISTICAS: PRESSÃO: 100 BAR OBSERVAÇÃO: ROTAÇÃO SENTIDO HORÁRIO REFERENCIAS: DH252108 / 92108 AMP / JPR1124 TRW FAVOR CONSULTAR O VENDEDOR SE REALMENTE É COMPATÍVEL COM SEU VEÍCULO! • VALOR UNITÁRIO • PRODUTO NOVO E ORIGINAL • ENVIO DO PEDIDO COM NOTA FISCAL • COM GARANTIA DE FÁBRICA • ANTES DE EFETUAR O PEDIDO, FAVOR TIRAR AS DÚVIDAS NO CAMPO DE PERGUNTAS CUIDAR DO SEU CARRO DE MANEIRA PREVENTIVA GERA ECONOMIA E, ACIMA DE TUDO, GARANTE SUA SEGURANÇA PARA DIRIGIR TRANQUILO. A NOVA VIA TRABALHA PARA OFERECER O MELHOR EM AUTOPEÇAS, COM UM ESTOQUE DE MAIS DE VINTE MIL ITENS, PARA QUE VOCÊ ENCONTRE SEMPRE O QUE PRECISAR. DISTRIBUÍMOS AUTOPEÇAS DAS MAIORES E MELHORES MARCAS DO MERCADO, COM UM ATENDIMENTO QUALIFICADO DE PROFISSIONAIS QUE ATUAM HÁ MAIS DE VINTE ANOS NO SEGMENTO. NOVA VIA AUTOPEÇAS: SEMPRE O MELHOR PARA SEU CARRO!', 527.73, 501.35, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rdwv-mbs6m9cwxxu565', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F714090968%2F23198694767', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21499252815', 'Livro O apartamento de Paris, por Lucy Foley - Intrínseca', 'Livro O apartamento de Paris, por Lucy Foley - Intrínseca Novo livro de Lucy Foley traz suspense imprevisível ambientado em um prédio chique na capital francesa Após os best-sellers A última festa e A lista de convidados, também lançados pela Intrínseca, Lucy Foley agora apresenta uma trama instigante sobre uma jovem inglesa que vai à França em busca de um recomeço. Sozinha, sem emprego e sem dinheiro, Jess pede abrigo ao meio-irmão, Ben, que não parece muito animado para recebê-la em seu apartamento em Paris. Quando chega à cidade, Jess descobre que o irmão mora em um lugar que ela jamais imaginaria que ele teria condições de pagar. E o mais intrigante: embora a carteira e as chaves estejam ali, não há nenhum sinal do rapaz. Quanto mais tempo o irmão continua desaparecido, mais Jess tenta seguir seus passos e mais perguntas surgem em sua mente. Os vizinhos formam um grupo bem eclético, mas não são exatamente amigáveis, e em pouco tempo aquela investigação coloca a jovem em situações cada vez mais delicadas. Em meio à sua busca cada vez mais misteriosa e sem saber em quem confiar, Jess acaba construindo relações diversas com os moradores. Mas em um prédio em que as paredes parecem ter segredos sufocados e olhos sempre atentos, a desconfiança pode ultrapassar as raias da paranoia. Ela pode até ter ido para Paris com a intenção de escapar do passado, mas talvez o futuro de seu irmão é que esteja em jogo. Todos são vizinhos. Todos são suspeitos. E todos têm algo a esconder. Sobre a autora: Lucy Foley estudou literatura inglesa e trabalhou durante anos como editora de ficção, até passar a se dedicar à escrita em tempo integral. Já escreveu para veículos como ES Magazine, Sunday Times Style, Grazia e outros. Seus dois suspenses anteriores, A última festa e A lista de convidados, também foram publicados pela Intrínseca. Detalhes do Livro: Tradução: Marina Vargas Páginas: 336 Gênero: Thrillers suspense Formato: 16 x 23 x 1,6 cm Peso: 450 gramas Tipo de capa: Brochura Lançamento: 27/06/2022', 69.9, 55.92, NULL, 'Books & Magazines > Books > Action, Crime & Thrillers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lurqzxgiorys33', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1208017249%2F21499252815', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
