INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41055708255', 'Livro ABC das Virtudes | Vida Kids', 'ABC das Virtudes | Vida Kids Livro ABC das Virtudes | Vida Kids Este livro nasce da necessidade de cultivar, de forma simples e bela, virtudes bíblicas que moldam o caráter cristão desde a mais tenra idade. No ABC das virtudes, as letras do alfabeto representam uma virtude essencial à caminhada cristã. A cada virtude, um versículo bíblico cuidadosamente escolhido nos lembra que a Palavra de Deus é fonte eterna de sabedoria. Um livro precioso para enriquecer a alfabetização, os momentos de leitura bíblica em família e auxiliar no desenvolvimento das crianças de forma cognitiva, moral e espiritual através da recitação e da memorização de versículos bíblicos de maneira leve e prazerosa. As ilustrações em aquarela proporcionam momentos de maravilhamento e contemplação, valorizando a essência do bom, belo e verdadeiro. Que cada página seja uma semente lançada ao coração gerando frutos que perdurarão por toda a vida', 42.81, 42.81, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7ra3a-mbcx6qfkov365c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F41055708255', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998779017', 'Odorizante de Ambientes Aerossol Coala - Chá Branco - 400ml / 240g', 'A linha de Odorizantes de Ambiente Aerossol Coala reúne cheirinhos cuidadosamente desenvolvidos para agradar aos mais diversos estilos e ocasiões. O Odorizante de Ambiente Aerossol Coala Chá Branco apresenta um cheirinho aromática, cítrica e floral que traz leveza e equilíbrio aos ambientes. Combinando notas naturais e sofisticadas, oferece uma perfumação fresca e acolhedora que transforma qualquer espaço em um refúgio de bem-estar. Notas olfativas: Notas de Topo: Chá Branco, Bergamota, Folhas Verdes, Mandarina Notas de Corpo: Muguet, Jasmim, Rosa, Gerânio Notas de Fundo: Sândalo, Âmbar, Musk, Baunilha Modo de Uso: Agite bem antes de usar. Segure a embalagem com a tampa virada para cima. A partir do centro do ambiente, pulverize o produto direcionando o jato lentamente em todas as direções. Evite dirigir o jato sobre pessoas, plantas, animais, aquários, alimentos, utensílios de cozinha, paredes, tecidos, chamas ou superfícies aquecidas. Precauções: Mantenha fora do alcance de crianças e animais domésticos. Não manuseie o produto antes de ter lido e compreendido todas as precauções de segurança. Mantenha afastado do calor, superfícies quentes, faíscas, chamas e outras fontes de ignição. Não fume. Armazene em local bem ventilado. Não expor a temperaturas superiores a 50°C. Evite o contato do produto com a pele ou os olhos. Em caso de contato com os olhos ou pele, lave imediatamente com água em abundância. Se a irritação persistir, consulte o Centro de Intoxicações ou um médico, levando o rótulo do produto. Em caso de emergência, ligue para: Intoxicação 0800 722 6001 – Serviço de orientação médica. Produto sob pressão. Não armazene no interior de veículos. Atenção! Aerossol inflamável. Recipiente pressurizado: pode romper se aquecido Composição: Veículo, coadjuvante, fragrância e gás propelente. Volume: 400ml/240g Descubra todas as opções disponíveis aqui, em nosso site, e transforme seus ambientes com o toque perfumado de Coala.', 29.9, 25.9, NULL, 'Home & Living > Home Care Supplies > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdyt-mcupzkvlfev406', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1177903362%2F22998779017', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200535841', 'Buzina Moto Honda NXR Bros 160/ Bros 150 (Todas) Original Magnetron', 'Buzina para moto original Magnetron A Buzina Original Magnetron é fabricada com materiais de alta qualidade e tecnologia de ponta, ela oferece um som forte e claro, que pode ser ouvido de longe, alertando os outros motoristas e pedestres da sua presença. COMPATIBILIDADE: HONDA - CG 125 TITAN ( TODAS ) - FAN 125/150 ( 2004 - 2015 ) - XLR 125 ( TODAS ) - CG FAN TITAN 150 ( 2009 EM DIANTE ) - CG 125 TODAY ( 1988 A 1994 ) - NXR BROS 160 / BROS 150 ( TODAS ) - POP 100i ( 2016 em diante ) - CG TITAN 160 / FAN 160 START CARGO Som potente e claro: A buzina emite um som forte e claro de 110dB, que pode ser ouvido de longe, garantindo a sua segurança no trânsito. >>> Pronta entrega com envio em 24 Horas<<<', 37.0, 31.45, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Others', 'https://cf.shopee.com.br/file/sg-11134201-821ew-mgxzpefle68a12', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1645057427%2F58200535841', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
