INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27083685444', 'Bíblia Sagrada | NVI | Letra Grande | Couro Soft Preta', 'Bíblia Sagrada | NVI | Letra Grande | Couro Soft Preta Essa bíblia possui linguagem NVI (Nova Versão Internacional) baseada nos seguintes fundamentos: precisão, beleza de estilo, clareza e dignidade, trazendo uma versão ao mesmo tempo, fiel e contemporânea. Nela, você encontrará ainda a fonte Leitura Perfeita. Desenvolvida exclusivamente para a Thomas Nelson Brasil, a Leitura Perfeita é uma fonte singular, moderna, bonita, clara e legível, ao mesmo tempo, em que integra os melhores avanços em tipografia de bíblias modernas. O resultado é uma tipologia que traz total conforto na leitura em qualquer tamanho. Páginas:1.760 Dimensões:Altura: 22 cm Largura: 14 cm Profundidade: 4,0 cm', 106.59, 106.59, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7reov-m8nb3u2hr9a850', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F27083685444', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
