INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593230719', 'Armário Multiuso Com Chave Para Escritório Notável Marrom', 'O Multiuso Escritório da Notável Móveis é a melhor opção para quem precisa de um lugar para organizar seus livros, documentos e deixar tudo muito bem guardado. Ele possui 3 prateleiras, puxadores em alumínio e o armário possui chave para maior segurança dos seus itens. Tudo isso para deixar o seu local de trabalho bem arrumado e com muito bom gosto. Especificações: - Comprimento: 70 cm - Largura: 31 cm - Altura: 177,3 cm - Cor: Freijó Trend - Estrutura em MDP 15mm - Pintura U.V. - Acabamento Fosco - 2 Portas Articuladas com puxadores em alumínio - Porta com chave - 3 Prateleiras - Peso máximo suportado pelo produto: 25 kg - As configurações do seu monitor ou dispositivo móvel podem afetar a tonalidade da cor do produto. Conferir na descrição. - Recomendação de Limpeza: Limpar com pano seco para retirar o pó. Não aplicar produtos abrasivos. - Produtos de Enfeite e Eletrônicos Não Estão Inclusos.', 359.9, 359.9, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rdxz-lzfmpzmhhygn5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F390327339%2F23593230719', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
