INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58252960138', 'Par Bucha Central Braço Maior Tras Honda Civic Axios 99 a 00', 'ITENS INCLUSOS: 2 Bucha Central do Braço Traseiro - Marca Axios 2239; VEÍCULOS COMPATÍVEIS: Honda: • Civic 1996 Posição: Traseira • Civic 1997 Posição: Traseira • Civic 1998 Posição: Traseira • Civic 1999 Posição: Traseira • Civic 2000 Posição: Traseira GARANTIA: 6 meses DADOS TÉCNICOS: 52622SH3013(); 52622SH3013(); 52622SH3013(); 52622SH3013(); DESCRIÇÃO: Evite devoluções!!! Na dúvida, utilize o campo perguntas informando o ano, modelo, motor e/ou chassi do carro para nossa equipe especialista JOSECAR PRINCIPAIS BENEFÍCIOS: Qualidade de produto original; Homologado pelos principais fabricantes de Peças no OEM;', 151.9, 151.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-8261j-mj8x3p30cb9i14', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1338381202%2F58252960138', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297753953', 'Equaliv Glutamina - 300 gramas', 'Aminoácido de grande importância para o organismo. Sua atividade está ligada às funções imunológicas, intestinais, produtoras de energia renais. Em períodos de sobrecarga como cirurgias, traumas [como queimaduras], exercícios físicos de alta intensidade, e outros, ocorre uma redução da concentração da glutamina dentro das células, especialmente no músculo esquelético. Nestes quadros acima citados, a glutamina é consumida em altas concentrações por diversos tecidos e células do sistema imunológico, diminuindo as suas reservas disponíveis. Conforme estas reservas sanguíneas do músculo esquelético e dos tecidos imunológicos se reduzem, a função do sistema imune torna-se limitada. A quantidade de glutamina que nosso organismo produz não é suficiente para reverter essa deficiência. Mas para evitar essa situação, o uso oral de glutamina em concentrações ajustadas restabelece seus níveis adequados, melhorando a imunidade e reduzindo as infecções. Modo de uso: Diluir 5 g (1 medida/ 1 scoop) de Equaliv Glutamina em até 100 mL de água ou bebida de preferência. USO ADULTO. Lata com 300 g. Ingredientes: L-glutamina. NÃO CONTÉM GLÚTEN.', 119.9, 119.9, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-7rdvk-lzhrkywcgmned1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F994595343%2F22297753953', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198396232', 'PAR Bucha Bandeja Leque New Civic G8/G9 Sampel 2007 a 2016', 'ITENS INCLUSOS: 2 Bucha Menor Traseira da Bandeja Dianteira - Marca Sampel; VEÍCULOS COMPATÍVEIS: Honda: • Civic 2007 Posição: Dianteira • Civic 2008 Posição: Dianteira • Civic 2009 Posição: Dianteira • Civic 2010 Posição: Dianteira • Civic 2011 Posição: Dianteira • Civic 2012 Posição: Dianteira • Civic 2013 Posição: Dianteira • Civic 2014 Posição: Dianteira • Civic 2015 Posição: Dianteira • Civic 2016 Posição: Dianteira GARANTIA: 12 meses PRINCIPAIS BENEFÍCIOS: Alta qualidade e durabilidade; Estabilidade e segurança garantidas; Encaixe perfeito; Performance superior;', 123.22, 123.22, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-7reqa-m8moa3hg7jjb47', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1338381202%2F23198396232', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22599382408', 'PAPEL MANTEIGA 30cm x 5m THEOTO', 'Papel Manteiga em Rolo Contém: 30cm x 5m O Papel Manteiga 30cm x 5m é um produto essencial para qualquer cozinha, oferecendo uma solução prática e eficiente para diversas aplicações culinárias. Este papel é especialmente útil para forrar formas e assadeiras, prevenindo que alimentos grudem e facilitando a limpeza. Ideal para o preparo de biscoitos, bolos, massas e outras receitas, o papel manteiga é um aliado indispensável na hora de cozinhar. Além de suas funções tradicionais, o papel manteiga também é perfeito para uso em técnicas de confeitaria, como o trabalho com chocolate e decoração de bolos. Sua superfície antiaderente e resistente ao calor permite que você trabalhe com segurança e facilidade, garantindo resultados perfeitos e profissionais. O rolo de 30cm de largura e 5m de comprimento oferece uma quantidade generosa de papel, sendo ideal para uso frequente ou em grandes preparações. O papel é fácil de cortar e manusear, adaptando-se às suas necessidades específicas na cozinha. Seja para assar, cozinhar, ou armazenar alimentos, o Papel Manteiga é uma escolha versátil e prática para cozinheiros amadores e profissionais. Principais Benefícios: Versatilidade: Ideal para forrar assadeiras, cozinhar e decorar. Superfície Antiaderente: Previne que os alimentos grudem, facilitando a limpeza. Resistente ao Calor: Seguro para uso em altas temperaturas. Quantidade Generosa: 30cm de largura por 5m de comprimento para várias aplicações. Fácil de Usar: Pode ser cortado e adaptado conforme necessário.', 9.99, 9.99, NULL, 'Food & Beverages > Others', 'https://cf.shopee.com.br/file/sg-11134201-8261w-mlvxtxelsutf63', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1402904120%2F22599382408', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23694506909', 'Fogão 5 Bocas de Embutir Dako Supreme Mesa de Vidro Bivolt', 'O Fogão de Embutir 5 Bocas Preto Dako Supreme é uma escolha sofisticada e prática para a sua cozinha. Com um amplo forno de 100L, prateleira autodeslizante, lâmpada interna e porta transparente, oferece conveniência ao cozinhar. Suas grades de ferro fundido proporcionam estabilidade, e a Tripla Chama garante alta potência. O design moderno inclui mesa de vidro temperado e puxador em alumínio escovado. Possui acendimento automático e é fácil de limpar devido ao revestimento Limpa Fácil, botões removíveis e vidro resistente. Com 5 queimadores, é uma afirmação de bom gosto para sua cozinha. Atributos e benefícios - Design que se integra: mesa de vidro temperado e puxador de alumínio escovado, criando um visual sofisticado que se encaixa perfeitamente na sua cozinha planejada. - Performance de chef: Mega Chama na versão 4 bocas e a potente Tripla Chama na versão 5 bocas para garantir agilidade e precisão em todas as receitas. - Estabilidade e segurança: grades individuais de ferro fundido que oferecem uma base firme e segura para todos os tamanhos de panelas. - Capacidade que inspira: forno de 60L (4Q) ou 100L (5Q) com espaço de sobra para seus melhores pratos. - Praticidade no forno: duas prateleiras, uma autodeslizante e outra com altura ajustável, para facilitar o acesso aos alimentos com total segurança. - Tecnologia para o dia a dia: acendimento automático, visor amplo para acompanhamento e forno com acabamento Limpa Fácil. - Eficiência e economia: isolamento térmico com lã de basalto que garante assados uniformes e otimiza o consumo de gás. Ficha Técnica Marca: Dako Voltagem: Bivolt Padrão de Tomada: 10A Cor: Preto Linha: Supreme Quantidade de Bocas: 5 bocas Tipo de Acendimento: Automático Garantia: 12 Meses Acabamento da Mesa: Vidro Temperado Instalação: Fogão de Embutir Turbo Convecção: Não Dimensões do Produto (largura x altura x profundidade): 80 x 68,2 x 65 cm Comprimento do Cabo de Energia: 96 cm Dimensões do Nicho (largura x altura x profundidade): 77 x 59,8 x 58,6 cmGrill: Não Funcionamento: Gás Capacidade do Forno: 100 Litros Acabamento do Forno: Limpa Fácil Luz no Forno: Sim (lâmpada 220V acompanha o produto) Vidro do Forno: Vidro Duplo Tampa: Não Trempes: Individual de ferro fundido com 4 pontos de apoio Grades do Forno: 1 Grade autodeslizante e 1 deslizante Timer Digital: Não Botões Removíveis: Sim Fabricação: Nacional Potência dos Queimadores: 2Q Semirrápido de 1,7kW, 2Q Rápido de 2,0kW e 1Q Tripla Chama de 3,3kW Sistema Corta/Bloqueia Gás: Sim Eficiência Energética: A EAN: 7897180510183 SKU: 300002078 DÚVIDAS FREQUENTES Qual é o lado da mangueira do fogão? R: A saída é do lado esquerdo olhando o fogão de frente. Caso você queira colocar para o outro lado, deverá acoplar uma mangueira metálica e utilizar na transversal para evitar corrosão. ** Atenção nas compras com CNPJ: Para que o pedido seja processado corretamente, é obrigatório informar no momento da compra: - Se o CNPJ é Contribuinte: deve-se indicar se o cliente é Isento ou possui Inscrição Estadual (IE). Se o CNPJ é Não-Contribuinte: essa condição também deve ser informada. "Ex: Isento" - Pedidos sem essas informações serão automaticamente cancelados. - Não aceitamos atualizações via chat.', 2889.0, 1999.0, NULL, 'Home Appliances > Large Household Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-824jj-mfilpnlg5c0ffa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F864840659%2F23694506909', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42759464586', 'Kit 2x Óleo Extraordinario para Cabelos 100ml Elseve L''Oréal Paris', 'ATENÇÃO: KIT COM 2 UNIDADES O Óleo Extraordinário Elseve de L''Oréal Paris é um delicado óleo que proporciona tratamento profissional para a beleza dos seus cabelos. Possui 6 óleos de flores preciosas, com efeito condicionante, capaz de transformar a fibra para tornar sublime qualquer tipo de cabelo. Penetrando as fibras capilares, o Óleo Extraordinário de Elseve trata profundamente, produzindo brilho instantâneo, além de proteger os fios do calor da chapinha. Pode ser usado antes da aplicação do shampoo, como finalizador, antes do uso do secador ou a qualquer momento do dia. Escolha sua maneira de usar e impressione! Benefícios - Nutrição - Brilho - Leveza - Maciez - Hidratação - Suavidade Tecnologia Criado para uma hidratação profunda dos cabelos, a fórmula de Óleo Extraordinário é leve e não gordurosa e age adaptando-se a qualquer tipo de cabelo. Hidrata até os cabelos mais secos, fornecendo-lhes nutrição, maciez e brilho intenso. Os cabelos secos ficam hidratados, nutridos e macios. Modo de Uso Aplicar 3 a 4 pressões em todo o cabelo. O óleo extraordinário é leve e multiuso, pode ser usado tanto em cabelos molhados quanto secos. - Antes da escova: para nutrir os fios; - Como finalizador: para malear a fibra; - Em qualquer momento: para disciplinar o frizz e ressaltar a luz dos cabelos. Precauções: Manter fora do alcance das crianças. Caso o produto caia nos olhos, lave-os imediatamente com água. Advertências: Não usar em crianças.', 99.8, 89.8, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcia8c0rvbi9ed', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1295597776%2F42759464586', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
