INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298554706', 'Ativador de Cachos CURLyou – Definição Rápida com Hidratação Power', 'Descubra o poder do tratamento completo com o CURL YOU – ATIVADOR DE CACHOS, desenvolvido para realçar a beleza natural dos fios ondulados, cacheados e crespos com tecnologia avançada e ativos amazônicos. Sua fórmula de alta performance entrega resultados visíveis desde a primeira aplicação, combinando definição, nutrição e leveza na medida certa, sem deixar os fios pesados ou oleosos. Benefícios ✅Alta definição ✅Modelagem de alta performance ✅Nutrição com umectação controlada ✅Hidratação revitalizante ✅Reconstrução Indicação: Cabelos ondulados (2A-2C), cacheados (3A-3C) e crespos (4A-4C), especialmente os que necessitam de definição, tratamento intensivo e leveza. Armazenamento: Conservar ao abrigo da luz e calor. Manter bem fechado após o uso', 98.9, 52.99, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mi35iby7kkjn67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1551667567%2F23298554706', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18417391585', 'Bebedouro Tigela Gelada Para Cães HomePet 500mL', 'A Tigela Gelada HomePet é uma ótima opção para deixar a água do seu pet sempre fresca, é ideal para os dias mais quentes e para preservar a água gelada por horas. O bebedouro conta com suporte plástico e refil removível feito em gel, que é o responsável em manter a água do seu pet gelada por muito mais tempo. Permite manter a água resfriada por até 5 horas, basta que você coloque o refil removível no freezer por 2 horas, devolva em sua base e preencha com água. Ele possui um design exclusivo, com recipiente central removível, facilitando a higienização e até mesmo o seu transporte. Modo de usar A Tigela HomePet retire o refil e coloque-o no freezer por duas horas, após esse tempo adicione água e pronto! Seu pet terá água fresca à disposição. Medidas aproximadas Suporte 500mL Diâmetro; 24cm Altura: 6cm Refil Diâmetro: 17,5cm Altura: 5cm', 79.9, 79.9, NULL, 'Pets > Pet Accessories > Bowls & Feeders', 'https://cf.shopee.com.br/file/da4d22527f50846bf155ea9ad005d834', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F18417391585', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49453551582', 'Sal Marinho Natural Cimsal Sosal 90g Moedor Refil Para Uso Diário', 'Sosal Sal Marinho Natural com Moedor 90g – Sabor puro e versátil O Sal Marinho Natural Sosal é extraído diretamente das salinas do litoral nordestino e passa por mínima intervenção, preservando seus minerais naturais. Com textura em cristais médios e embalagem prática com moedor, é ideal para realçar o sabor de preparos do dia a dia com um toque saudável e funcional. ℹ Benefícios: ✅ 100% natural, sem aditivos químicos ✅ Cristais médios que facilitam a dosagem ✅ Ideal para carnes, saladas, grelhados e massas ✅ Rico em minerais como magnésio e potássio ✅ Embalagem prática com moedor reutilizável ✅ Produto da tradicional marca Cimsal ℹ Ficha Técnica: ✅ Produto: Sal Marinho Natural ✅ Marca: Cimsal – Linha Sosal ✅ Conteúdo: 90g ✅ Tipo: Cristais médios com moedor ✅ Ingredientes: Sal marinho natural ✅ Embalagem: Frasco PET com moedor ✅ Uso: Culinário geral e tempero final ✅ Não contém glúten', 19.82, 19.82, NULL, 'Food & Beverages > Cooking Essentials > Seasonings & Condiments', 'https://cf.shopee.com.br/file/sg-11134201-81ztk-milzxthsu41y15', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F394192376%2F49453551582', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
