INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19898132161', 'Camara De Ar Aro 26 Kenda Bike Bico Grosso Balão Mtb', 'Qualidade superior, borracha butyl, emenda invisível, mais elasticidade, espessura uniforme, maior resistência a impacto, aderência a remendos à quente ou frio, mais leve. Medida: 26x1.9/ 2.125. Válvula: tipo americana (borracha). Composição: borracha sintética, cobre e níquel. Quantidade de câmaras: 1. Instruções de montagem da câmara de ar: 1. Mantenha a bomba de ar e as alavancas de pneu prontas para serem utilizadas; 2. Retire o pneu do aro com as alavancas; 3. Retire a câmara antiga do aro; 4. Verifique se o pneu tem materiais estranhos ou furos; 5. Encha um pouco a câmara; 6. Monte a câmara, começando no orifício para a válvula existente no aro; 7. Monte o pneu, começando no orifício para a válvula existente no aro; 8. Certifique-se de que a câmara não fica trilhada entre o pneu e o aro da bicicleta; 9. Encha o pneu com a pressão recomendada (inscrita na parte lateral do pneu).', 16.99, 16.99, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rffp-m9dvl4ftkmmpe6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F19898132161', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
