INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16422160068', 'Escova Pet Cachorro e Gato Bass Retangular De Bambu Com Pinos De Metal Sem Bolinhas Lisa', 'Especialmente criada para todos os tipos de pelos. Com pinos medianos pode ser utilizada em diversas situações. Marca: BASS Medidas: Altura: 23,5cm Largura: 5cm Tamanho dos pinos: 2cm (aproximadamente) Leia atentamente sobre como cuidar e prolongar a vida útil da sua escova. - Evitar usar no pelo molhado (pingando); - Não guardar o item úmido; - Não usar produtos abrasivos para limpeza; - Nunca deixar o item de molho em qualquer líquido que seja; - Evitar utilizar para remover nós e embolos; - Não utilizar pente entre os pinos para remoção da pelagem que fica na escova, sempre remover delicadamente com as mãos; - Lembrando que em cidades mais úmidas ou com maresia a condição do aço pode ser afetada.', 150.0, 142.5, NULL, 'Pets > Pet Grooming > Hair Care', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7tn6mcwmxxee4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F688030691%2F16422160068', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
