INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49500556398', 'Guache com 6 Carimbos com Pote Encaixável Estojo C/ 6 cores 20ml cada Leo&Leo Leonora - 10174', 'Aprender pintando, seja em casa ou na escola é bem mais divertido e instigante com a Tinta Guache com Pote Encaixável - Estojo c/ 6 Cores 20 ML cada Leo&Leo. É um kit de 6 potes encaixáveis para a criança carimbar e pintar. São 6 cores de tinta variáveis e carimbos de EVA com estampas diferentes na tampa, sendo fácil de transportar e divertido de brincar, onde a criatividade é estimulada, ganhando formas, cores e descobertas. A Tinta Guache com Pote Encaixável - Estojo c/ 6 Cores 20 ML cada Leo&Leo é recomendada para crianças a partir de 4 anos, é atóxica e lavável, pois é facilmente removida da pele e da maioria dos tecidos. Características: Embalagem - Estojo de 6 cores Múltiplo de venda - 1 estojo Inner - 12 estojos Master - 72 estojos Composição - resinas, água, pigmentos, carga e conservantes Indicação de uso - ATENÇÃO! NÃO RECOMENDÁVEL PARA CRIANÇAS MENORES DE 3 (TRÊS) ANOS, POR CONTER PARTE(S) PEQUENA(S) QUE PODE(M) SER ENGOLIDA(S) OU ASPIRADA(S) E PONTA(S) AGUDA(S) FUNCIONAL(IS). Dimensões - 13cm x 8,3cm x 5,3cm Características: - Marca: Leo&Leo Leonora - Modelo: 10174 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - Guache com 6 Carimbos com Pote Encaixável Estojo C/ 6 cores 20ml cada', 20.48, 18.43, NULL, 'Stationery > Others', 'https://cf.shopee.com.br/file/sg-11134201-821fo-mggjx3f6093fe7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F49500556398', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
