INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293924591', 'Escova Sanitária com Suporte com Tampa Articulável - Arthi', 'Escova Sanitária com Suporte com Tampa Articulável - Arthi Com design moderno e funcionalidade inteligente, a Escova Sanitária com Suporte da Arthi é a escolha perfeita para manter o banheiro sempre limpo e bem organizado. Seu suporte com formato quadrado oferece estabilidade, enquanto o acabamento discreto permite que o item se integre facilmente à decoração de diversos estilos de ambientes. Praticidade no dia a dia. A tampa articulável acoplada ao suporte é um dos grandes diferenciais, pois se abre automaticamente com o movimento da escova, evitando o contato direto com a tampa e garantindo mais higiene e conforto na hora da limpeza. Essa funcionalidade também impede o acúmulo de sujeira, contribuindo para um ambiente mais limpo e agradável. Compacta e eficiente, essa escova ocupa pouco espaço e ainda oferece excelente desempenho na remoção de resíduos. Seu cabo longo e firme facilita o manuseio e garante acesso completo à área interna do vaso sanitário. Ideal para banheiros residenciais, lavabos e ambientes corporativos que prezam pela organização sem abrir mão da estética. Especificações Marca: Arthi Modelo: Escova Sanitária com Suporte Tampa: Articulável Formato do Suporte: Quadrado Medidas: Largura 10,5 cm Comprimento: 9,5 cm Altura: 35,8 cm', 45.9, 34.9, NULL, 'Home & Living > Home Care Supplies > Cleaning Brushes', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8ne24w2g6mp72', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1314243679%2F22293924591', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
