INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40212968478', 'Óculos de Sol Quadrado Viggo Tortoise Savana Unissex UV400 Armação Marmorizada', 'Óculos de Sol Quadrado Viggo Tortoise Savana — Design marcante com proteção UV400 O Óculos de Sol Quadrado Viggo Tortoise Savana apresenta estilo robusto e marcante com sua armação marmorizada em tons terrosos, ideal para quem busca presença e sofisticação no visual. Seu formato quadrado e acabamento tortoise Savana conferem um charme atemporal que se destaca em qualquer look. Versátil e elegante, esse modelo unissex é perfeito para uso diário, momentos ao ar livre e eventos casuais. A combinação entre visual clássico e acabamento sofisticado faz dele uma escolha certeira para complementar o estilo com personalidade. Benefícios: Visual marcante com acabamento tortoise Savana Proteção completa UV400 (UVA e UVB) Estilo unissex perfeito para diversas ocasiões Design quadrado atemporal e sofisticado Detalhes Técnicos: Dimensões: Lente 4,5 cm | Ponte 2,3 cm | Haste 14,1 cm | Largura total 13,7 cm Material da lente: Policarbonato com proteção UV400 Acessórios inclusos: Estojo e flanela de limpeza Garanta já o seu Óculos de Sol Quadrado Viggo Tortoise Savana e transforme seu visual com estilo, proteção e o padrão de qualidade premium da Saint Germain.', 183.42, 78.9, NULL, 'Fashion Accessories > Eyewear > Sunglasses', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdezsrosvem1d3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F411289902%2F40212968478', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
