INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194917494', 'Capa case capinha para Samsung Galaxy S26 Ultra - Raptor Slim - Gshield', 'DESCRIÇÃO O futuro da proteção inteligente chegou com a Capa Raptor Slim da Gshield – que combina resistência, praticidade e um design mais compacto para quem busca leveza sem abrir mão da segurança. Desenvolvida especialmente para Samsung Galaxy S26 Ultra, a Raptor Slim oferece proteção de alto nível contra impactos e arranhões, com uma estrutura mais enxuta e discreta. Seu anel MagSafe multifuncional é o grande diferencial: compatível com carregadores magnéticos e também funcional como suporte kickstand ajustável, ele permite apoiar o celular na vertical ou horizontal com conforto e estabilidade para vídeos, chamadas e produtividade. A inovação vai além: a Raptor Slim traz o exclusivo Dente Raptor, embutido no anel MagSafe — uma pequena lâmina estratégica que facilita abrir caixas, cortar fitas ou rasgar embalagens com agilidade, tornando a capa ainda mais útil no cotidiano. Seu acabamento conta com laterais antiderrapantes que garantem maior firmeza ao segurar o celular, reduzindo o risco de quedas acidentais. A lateral ainda possui espaço dedicado para encaixe de cordões ou alças de pulso, garantindo mais segurança no transporte. Apesar do design mais fino, a Raptor Slim mantém o padrão de qualidade Gshield com materiais premium, bordas elevadas para absorção de impactos e proteção da tela e da traseira do aparelho. Tudo isso com certificação US Military, que atesta sua resistência em situações de uso intenso. Compacta, robusta e funcional, a Capa Raptor Slim da Gshield é a escolha perfeita para quem busca desempenho, proteção e estilo no dia a dia. ESPECIFICAÇÕES Marca: Gshield Material: Policarbonato e TPU Dimensões: Dimensões exatas do aparelho Proteção: Contra impactos e riscos Laterais antiderrapantes: Maior aderência e segurança no manuseio Bordas ultra elevadas: Proteção extra contra impactos Anel MagSafe com suporte kickstand: Conforto para visualizar conteúdos Dente Raptor embutido: Facilidade para abrir caixas e embalagens Espaço para alça de pulso: Praticidade para o dia a dia Certificações: Us Military', 109.99, 109.99, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-8260s-mlu9aqy9pw5d4c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F23194917494', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
