INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23197994272', 'Pistola Tornador Para Limpeza Com Rolamento Vonder', 'Pistola tornador para limpeza, com rolamento, VONDER. Prática, leve e com alto poder de limpeza. Possui válvula de controle de saída de líquidos em metal e mecanismo de ação rolamentado, contribuindo para melhor poder de ação e maior durabilidade. Indicada para limpeza em geral, como: estofados, carpetes, bancos de tecido ou couro, tetos, entre outras aplicações. Utilizada com compressor de ar. Compressor indicado: 15 pcm. Não acompanha conector. Material da pistola: Alumínio Material da caneca: Polipropileno (PP) Capacidade da caneca: 1 Litro Conexão de entrada: Rosca fêmea 1/4" NPT Consumo de ar (pcm): 8,0 pcm (pé³/min) Pressão máxima de trabalho: 116 lbf/pol² Pressão máxima de trabalho: 8,0 bar Pressão mínima de trabalho: 6,0 bar Pressão mínima de trabalho : 87 lbf/pol² Rotação do tubo metálico girador (rpm): 16.300/min Atenuação - NRRsf: 105 dB Massa aproximada (peso) (kg): 0,680 kg Conteúdo da Embalagem: 1 Pistola tornador. Acompanha: 1 bico cone e 2 escovas para bico cone.', 459.9, 349.98, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rd6d-lvz2u0muhm5ob4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F23197994272', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
