INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42354426643', 'Boneco Geleia 25cm Articulado Acompanha 3 Chaveiros Youtuber Original Algazarra', 'Boneco Geleia 25cm Articulado Acompanha 3 chaveiros Youtuber Original Algazarra Transforme seu mundo com este incrível boneco articulado de 25cm! Feito de plástico durável, este boneco é perfeito para fãs de todas as idades que desejam trazer a magia do jogo para o mundo real. Acompanha também 3 chaveiros para seu boneco, que podem ser substituídas e acopladas à ele. Além disso a embalagem do produto se torna um incrível jogo da memória com todos os personagens. Características do produto: - Altura: 25cm - Material: Plástico de alta qualidade - Articulação: 5 pontos de articulação para poses dinâmicas e realistas - Conteúdo: Boneco de 25cm + 3 chaveiros Com os bonecos da linha da Algazarra, as horas de diversão são garantidas. Este boneco articulado é ideal tanto para brincar quanto para colecionar. Seja você um aventureiro em busca de ação ou um colecionador apaixonado, este boneco trará um toque especial ao seu universo.', 80.9, 74.9, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhs6enqmx4p255', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1314314958%2F42354426643', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
