INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798926019', 'Alicate Para Anéis Interno Bico Reto 12 Vonder', 'O alicate para anéis interno bico reto 12" Vonder é indicado para uso profissional na remoção e colocação de anéis internos de retenção, garantindo praticidade, segurança e precisão em serviços de manutenção mecânica. Sua construção robusta proporciona firmeza no manuseio e eficiência no encaixe dos anéis. Produzido em aço cromo vanádio, oferece alta resistência e durabilidade, com acabamento niquelado que aumenta a proteção contra oxidação. Possui cabo plastificado para maior conforto durante o uso e bico reto que assegura encaixe firme e estável em diferentes aplicações. Características: Modelo: 3662000310 Referência: 3662000310 Material do corpo: Aço cromo vanádio Acabamento: Niquelado Tipo do cabo: Plastificado Tipo do bico: Reto Diâmetro do bico: 3,40 mm Comprimento total: 12" - 305 mm Diâmetro de aplicação: 60 mm a 110 mm Massa aproximada: 0,479 kg Benefícios: Facilita a colocação e remoção de anéis internos de retenção Alta resistência e durabilidade em aço cromo vanádio Proteção contra oxidação com acabamento niquelado Cabo plastificado que garante conforto e firmeza Ferramenta prática e eficiente para uso profissional Conteúdo da embalagem: 1 Alicate para anéis.', 103.38, 82.33, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-824i3-mezsfa5v5k3t6f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F22798926019', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20099890219', 'Saia Shorts Xadrez Infantil Feminina Lilica Ripilica', 'A Saia Shorts em suede twill sublimado combina charme e praticidade em uma peça única! Com uma sofisticada estampa xadrez, ela traz um toque clássico e atemporal ao look das pequenas. O elástico na parte de trás do cós garante um ajuste confortável e perfeito ao corpo, proporcionando liberdade de movimentos para brincar e explorar com estilo. O design funcional une a delicadeza da saia à praticidade do shorts interno, permitindo mais segurança e conforto no dia a dia. Versátil e cheia de personalidade, essa peça é ideal para composições modernas e encantadoras!', 229.0, 114.5, NULL, 'Baby & Kids Fashion > Girl Clothes > Bottoms', 'https://cf.shopee.com.br/file/br-11134201-820l6-mqxhgu8bz95086', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F980954412%2F20099890219', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
