INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22292987179', 'Conjunto Curto Alfaiataria Infantil Feminino Lilica Ripilica', 'Um look perfeito para garantir muito charme em todos os momentos: Conjunto Lilica Ripilica em tecido alfaiataria com efeito gloss. Com detalhes que deixam o visual ainda mais incrível, a blusa possui gola levemente mais alta com laço, dando mais volumetria à peça, e abertura na lateral e nas costas com botões, facilitando a hora de vestir. Já a calça conta com elástico regulável no cós, fechamento em zíper e botão, bolsos laterais e abertura em botões nas barras. Além disso, a estampa lisa garante mais elegância ao look e a assinatura da marca aparece com sutileza nas peças. Aposte, sua menina vai ficar ainda mais linda!', 669.0, 334.5, NULL, 'Baby & Kids Fashion > Girl Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-7rd58-lugpofdnwpfi90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F980954412%2F22292987179', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
