INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19099675304', 'Pneu Aro 17 Westlake 185/35 R17 74V SA37', 'Pneu Aro 17 Westlake 185/35 R17 74V SA37 Sobre o pneu: O modelo SA37 conta com um design moderno na sua banda de rodagem, com perfil assimétrico aumenta estabilidade. Com seus sulcos largos garantem uma ótima aderência tanto em pista seca quanto molhada. Sobre a marca: A marca Westlake foi fundada em 1958 na China. A Westlake, detentora de outras marcas de pneus no mercado internacional, disponibiliza uma linha completa de modelos, para diversos tipos de veículos, de carros de passeio até agrícolas. A expertise de desenvolver pneus confiáveis e resistentes torna a Westlake uma marca de pneus bons para quem procura ter economia e segurança em seus trajetos. Informações adicionais: Marca: Westlake Modelo: SA37 Medida: 185/35 R17 Largura: 185mm Perfil: 35% Aro: 17 Índice de peso: 74 - 375 Kg Índice de velocidade: V - 240 Km/h Tipo de terreno: HT Tipo de construção: Radial Tipo de desenho: Assimétrico Tipo de montagem: Sem câmara RunFlat: Não Extra load: Não Protetor de bordas: Não Sidewall: Bsw letras pretas Garantia: 5 anos contra defeitos de fábrica OBSERVAÇÕES: IMAGEM MERAMENTE ILUSTRATIVA VERIFIQUE SEMPRE NO VEÍCULO QUAL É A MEDIDA EXATA DO SEU PNEU', 428.85, 428.85, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7reqk-m8c8uhb92hsy51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F882691919%2F19099675304', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
