INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398853136', 'Sandália Mississipi Rasteira Metalizada Com Amarração Feminina MF222', 'Produto marca Mississipi. A Sandália Mississipi Rasteira com Amarração é a peça-chave que faltava no seu guarda-roupa de verão. Com um design elegante e moderno, esta sandália rasteira destaca-se pelo bico quadrado e pelas finas tiras que envolvem delicadamente os pés. o detalhe das aplicações na parte frontal adiciona um toque de glamour, enquanto a amarração na perna permite que você crie looks autênticos e cheios de estilo para diversas ocasiões. É a escolha perfeita para quem busca conforto, versatilidade e sofisticação em um só produto. Sinta a leveza e a liberdade em cada passo. Ideal para o dia a dia e momentos de lazer, essa sandália Mississipi foi feita para mulheres que valorizam o bem-estar sem abrir mão da beleza. Seu solado com altura de 1,50 cm proporciona estabilidade e conforto duradouros, fazendo dela a companheira ideal para passeios no parque, encontros com amigos ou uma ida à praia. Mais do que um calçado, é um investimento no seu estilo de vida, garantindo que você esteja sempre deslumbrante e à vontade. Não perca a chance de transformar seus looks e elevar sua autoconfiança. a Sandália Mississipi com amarração é a união perfeita de beleza e praticidade, um item indispensável para a estação mais quente do ano. Com ela, você estará pronta para brilhar em qualquer lugar, esbanjando charme e elegância. Peso: 0,450 kg Altura do salto: 1,5 cm', 139.9, 129.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flat Sandals', 'https://cf.shopee.com.br/file/sg-11134201-824i7-mdx6dbh96c5f7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F22398853136', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894701245', 'Vinho Los Pasos Tinto Argentino - Malbec 750ml', 'Vinho Los Pasos Tinto Argentino - Malbec 750ml 🍷 Los Pasos Malbec 750ml: A Alma da Malbec Argentina em Mendoza Uma Experiência Típica Andina Descubra o Los Pasos Malbec, um vinho tinto envolvente e de notável estrutura, nascido nos céus altos de Mendoza, Argentina. Produzido pela aclamada Séptima, vinícola que carrega a chancela de qualidade do prestigiado grupo espanhol Cordoníu, este Malbec é uma homenagem à casta mais emblemática do país. Seus vinhedos, plantados majestosamente aos pés da imponente Cordilheira dos Andes, desfrutam de um terroir único. A altitude, o clima semiárido e a intensa luz solar andina são os segredos para o amadurecimento lento e concentrado das uvas, resultando em um vinho de profunda cor, taninos sedosos e um perfil aromático complexo e frutado. Notas de Degustação e Estilo Com 13.5% de teor alcoólico, o Los Pasos Malbec representa o autêntico estilo "Mendoza Malbec Red". Na taça, apresenta-se encorpado e com taninos aveludados que prometem uma experiência elegante e equilibrada. Espere encontrar: Aromas: Intenso foco em frutas vermelhas maduras, como cereja e framboesa, complementadas por notas de ameixa. Paladar: Fresco, frutado e de excelente persistência, mantendo a estrutura suculenta que caracteriza os grandes Malbecs. Harmonização Sofisticada A versatilidade deste Malbec permite que ele brilhe em diversas ocasiões gastronômicas. Sua estrutura robusta e taninos macios são o par ideal para: Pratos com molhos ricos e saborosos. A arquitetura da vinícola Séptima, construída predominantemente em pedra, não é apenas um espetáculo visual, mas também um elemento chave que garante a umidade e a temperatura ideais para o lento e controlado envelhecimento deste néctar, assegurando sua qualidade superior.', 69.99, 49.98, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/sg-11134201-82258-mhktilarm8le8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1599581471%2F22894701245', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
